window.CHAPTERS = [{"num":1,"title":"第1章 反光玻璃","file":"chapters/ch001.mp3","dur":743.8,"size_mb":5.7,"segs":[{"s":0,"e":6.42,"t":"时间：9 月初 · 高一开学第一周"},{"s":6.82,"e":14.52,"t":"高一开学的第三天，我才注意到那扇窗户。"},{"s":14.92,"e":38.02,"t":"不是教室的窗户——是走廊尽头那扇。611 班的教室在四楼最东边，走廊尽头有一扇大窗，正对着教学楼中间的天井。"},{"s":38.42,"e":42.91,"t":"天井不宽，大概 5 米。"},{"s":43.31,"e":46.84,"t":"对面是 610 班。"},{"s":47.24,"e":73.23,"t":"这件事本来是没什么特别的——两间教室隔着一个天井，走廊窗户对走廊窗户，仅此而已。我第三天早自习站到走廊上背课文的时候，纯粹是因为教室里太闷了。"},{"s":73.63,"e":104.44,"t":"九月初的早上还带着夏天的尾巴。电扇在头顶吱吱呀呀地转，吹出来的风全是热的。语文老师让我们自由朗读《滕王阁序》，我读了大概两遍\"豫章故郡，洪都新府\"，后背就湿了一片。"},{"s":104.84,"e":110.61,"t":"于是我拿着课本站到了走廊上。"},{"s":111.01,"e":123.85,"t":"走廊比教室凉快一点。有风从窗户外面吹进来，虽然也是热的，但至少是活的。"},{"s":124.25,"e":139.65,"t":"我翻到\"落霞与孤鹜齐飞，秋水共长天一色\"那一页，靠在窗台上，开始背。"},{"s":140.05,"e":145.83,"t":"然后我抬起头，看见了对面那个人。"},{"s":146.23,"e":160.99,"t":"610 班的窗户也是开着的。最后一排靠窗的位置坐着一个人——他低着头，正在写什么。"},{"s":161.39,"e":166.52,"t":"从我这个角度，只能看到他的侧脸。"},{"s":166.92,"e":185.21,"t":"光线从窗外照进来，落在他的侧脸上——他的眉毛不浓，鼻梁很直，下唇比上唇厚一点。这些是我后来才看清的。"},{"s":185.61,"e":189.78,"t":"当时我只注意到了一件事。"},{"s":190.18,"e":192.43,"t":"他的眼睛。"},{"s":192.83,"e":207.91,"t":"他抬头了——大概是写完了什么，抬起头活动了一下脖子。就在那一瞬间，我看见了他的眼睛。"},{"s":208.31,"e":216.97,"t":"很亮。"},{"s":217.37,"e":241.44,"t":"不是\"有精神\"的那种亮——是那种你隔着 5 米都能看清的亮。像早上第一节课前、太阳刚升起来、照到对面教学楼的白墙再反射过来的那种光。"},{"s":241.84,"e":246.01,"t":"我盯着他看了大概 3 秒。"},{"s":246.41,"e":250.9,"t":"然后他低下头，继续写了。"},{"s":251.3,"e":255.15,"t":"我也低下头，看我的课本。"},{"s":255.56,"e":270.31,"t":"\"落霞与孤鹜齐飞，秋水共长天一色\"——我盯着这行字看了很久，一个字都没读进去。"},{"s":270.72,"e":274.25,"t":"脑子里全是那双眼睛。"},{"s":274.65,"e":282.03,"t":"我对自己说：你只是没见过长成这样的人。"},{"s":282.43,"e":284.99,"t":"但我知道不是。"},{"s":285.39,"e":293.74,"t":"我那天早上回到教室之后，坐在座位上发了很久的呆。"},{"s":294.14,"e":305.05,"t":"周海——我新认识的同桌，坐我左边——拿胳膊肘捅了我一下。"},{"s":305.45,"e":306.73,"t":"\"你怎么了？\""},{"s":307.13,"e":308.74,"t":"\"没怎么。\""},{"s":309.14,"e":310.74,"t":"\"你脸红了。\""},{"s":311.14,"e":313.39,"t":"\"天热。\""},{"s":313.79,"e":317.64,"t":"他看了我一眼，没继续问。"},{"s":318.04,"e":331.52,"t":"我把课本翻到《滕王阁序》那一页，假装在背。但我的目光一直往窗外飘。"},{"s":331.92,"e":345.71,"t":"从我这个位置——靠窗，倒数第二排——刚好能看见对面 610 班的那扇窗户。"},{"s":346.12,"e":373.71,"t":"他的位置在最后一排。从我这里看过去，隔着天井，隔着反光玻璃，只能看到一个人影的轮廓。但我还是一眼认出了他——他低着头，伏在桌上，右手在动，在写东西。"},{"s":374.11,"e":378.92,"t":"他写字的时候头埋得很低。"},{"s":379.32,"e":389.59,"t":"偶尔他会停下来，用手摸一下后脑勺——就一下，然后继续写。"},{"s":389.99,"e":393.84,"t":"我盯着那个动作看了很久。"},{"s":394.24,"e":398.09,"t":"然后我发现了一件事。"},{"s":398.49,"e":408.76,"t":"我还没记住《滕王阁序》第二段，但我已经记住了他摸后脑勺的节奏。"},{"s":409.16,"e":413.65,"t":"那天的课我基本没听进去。"},{"s":414.06,"e":443.57,"t":"数学课老师在讲集合——我在纸上画了一条线，标了一个点，代表 5 米外的那个位置。语文课继续背《滕王阁序》——我背到\"潦水尽而寒潭清\"的时候，脑子里浮现的是他抬头时那双眼睛的光。"},{"s":443.97,"e":451.67,"t":"吃午饭的时候周海问我：\"你今天怎么魂不守舍的？\""},{"s":452.08,"e":454,"t":"\"有吗？\""},{"s":454.4,"e":460.5,"t":"\"有。数学老师叫你两遍你都没听见。\""},{"s":460.9,"e":462.82,"t":"我没说话。"},{"s":463.23,"e":478.63,"t":"下午最后一节自习课，我提前把作业写完了。然后我站起来，走到走廊尽头那扇窗户前面。"},{"s":479.03,"e":486.09,"t":"那个位置——正对着 610 班的走廊窗户。"},{"s":486.49,"e":488.73,"t":"他的窗户。"},{"s":489.13,"e":494.27,"t":"我站在那里，假装在看楼下的操场。"},{"s":494.67,"e":508.14,"t":"操场上有人在跑步，有人在打篮球，远处的围墙外面能看见城市的楼顶。"},{"s":508.54,"e":512.07,"t":"但我什么都没看进去。"},{"s":512.48,"e":540.39,"t":"我侧过头，往 610 班的方向看了一眼——隔着 5 米宽的天井，隔着玻璃的反光，我看见他的背影。他坐在最后一排，坐得很直，右手在写，左手搭在桌沿。"},{"s":540.79,"e":543.36,"t":"他就那么坐着。"},{"s":543.76,"e":546.97,"t":"我站了大概 3 分钟。"},{"s":547.37,"e":549.93,"t":"然后我回去了。"},{"s":550.34,"e":563.17,"t":"回教室的路上，我在心里对自己说：你只是好奇。你只是没见过这样的人。"},{"s":563.57,"e":570.31,"t":"但我记得回座位的时候，心跳快得不正常。"},{"s":570.71,"e":577.13,"t":"晚自习结束后，我背着书包走出教学楼。"},{"s":577.53,"e":596.46,"t":"九月的晚上有了点凉意，路灯把校园照成昏黄色。我往宿舍走的路上，经过食堂门口的时候——看见了个人。"},{"s":596.86,"e":606.48,"t":"他站在食堂门口的灯光下面，背着书包，手里拿着一瓶水。"},{"s":606.88,"e":608.17,"t":"是他。"},{"s":608.57,"e":616.59,"t":"他没看见我——他在看手机，屏幕的光映在他脸上。"},{"s":616.99,"e":639.13,"t":"我从他身后走过去，大概隔了 3 米。走过去的时候我放慢了脚步，不是故意的——是我的脚自己慢下来的。"},{"s":639.53,"e":648.52,"t":"我走过他身边的时候，听见他把瓶盖拧开、喝水的声音。"},{"s":648.92,"e":653.09,"t":"咕咚——很小的一声。"},{"s":653.49,"e":656.06,"t":"然后我走过去了。"},{"s":656.46,"e":658.7,"t":"没有回头。"},{"s":659.1,"e":677.39,"t":"但那个声音——瓶盖拧开的咔的一声，喝水的声音，路灯下他的侧脸——我都记住了。"},{"s":677.79,"e":685.49,"t":"回到宿舍，我爬上床，拿出手机，打开备忘录。"},{"s":685.89,"e":688.78,"t":"打了一行字："},{"s":689.18,"e":697.52,"t":"\"对面 610 班最后一排，靠窗。眼睛很亮。\""},{"s":697.93,"e":702.74,"t":"我看着这行字看了大概 10 秒。"},{"s":703.14,"e":705.39,"t":"然后删掉了。"},{"s":705.79,"e":711.56,"t":"把手机放到枕头底下，闭上眼睛。"},{"s":711.96,"e":729.93,"t":"但眼前全是那个画面——他坐在窗户后面，阳光落在他的侧脸上，他抬起头来，那一瞬间，他的眼睛里有光。"},{"s":730.33,"e":735.14,"t":"我翻了个身，把被子拉过头顶。"},{"s":735.55,"e":737.79,"t":"完了。"},{"s":738.19,"e":740.76,"t":"我在心里说。"},{"s":741.16,"e":743.73,"t":"这才第三天。"}]},{"num":2,"title":"第2章 越看越耐看","file":"chapters/ch002.mp3","dur":696.9,"size_mb":5.3,"segs":[{"s":0,"e":5.23,"t":"时间：9 月中至 11 月初 · 高一上"},{"s":5.54,"e":10.28,"t":"从那天之后，我开始注意那扇窗户了。"},{"s":10.59,"e":24.54,"t":"不是刻意的——至少我对自己是这么说的。我只是发现走廊尽头那个位置通风比较好，站那里背书比较凉快。只是这样。"},{"s":24.85,"e":31.58,"t":"但连续站了一周之后，周海问我：\"你怎么老往那边跑？\""},{"s":31.89,"e":33.64,"t":"\"那边凉快。\""},{"s":33.95,"e":36.19,"t":"\"这边也有窗户啊。\""},{"s":36.5,"e":38.25,"t":"\"这边太阳大。\""},{"s":38.56,"e":47.28,"t":"他看了一眼我站的位置——那个位置刚好被墙挡住一半的阳光——没再问了。"},{"s":47.59,"e":49.58,"t":"但我自己知道。"},{"s":49.89,"e":55.62,"t":"那个角度，刚好能看见 610 班的最后一排。"},{"s":55.94,"e":58.68,"t":"我发现了他的一些规律。"},{"s":58.99,"e":77.92,"t":"每天早上 7 点 15 分左右，他会从后门进教室。不早也不晚——不是最早到的那批，也不是踩点进来的那种。书包单肩背着，右手拎着一个透明的水杯。"},{"s":78.24,"e":97.17,"t":"他坐下来之后，会先把杯子放在桌角，然后从书包里抽出一本书。他翻书的动作很快——不像是在挑今天读什么，像是早就决定好了，直接翻到某一页。"},{"s":97.48,"e":103.71,"t":"他看书的时候头埋得很低，几乎要贴到桌面上。"},{"s":104.02,"e":109.01,"t":"这个姿势我隔着天井都看得清清楚楚。"},{"s":109.32,"e":126.51,"t":"偶尔他会停下来——不是抬头，是停下来，盯着书页的某一行，一动不动，大概 3 到 5 秒。然后他会拿起笔，在那一行下面画一条线。"},{"s":126.82,"e":132.8,"t":"画线的动作很干脆——一笔到头，不带犹豫。"},{"s":133.11,"e":149.06,"t":"我观察了两周，发现他几乎每页都会画线。不是整段整段地画——是偶尔一行，偶尔一行，像在书页上种了一排稀疏的篱笆。"},{"s":149.37,"e":152.11,"t":"我开始好奇他在读什么。"},{"s":152.42,"e":164.63,"t":"但距离太远了——5 米，隔着反光玻璃，我连他桌面上摊的是什么颜色的书都看不清，更别说字。"},{"s":164.94,"e":167.43,"t":"我只能看到他的动作。"},{"s":167.75,"e":172.73,"t":"看到他低头、抬头、画线、翻页。"},{"s":173.04,"e":182.01,"t":"看到他偶尔停下来，用手摸一下后脑勺——和第一天一模一样的动作。"},{"s":182.32,"e":188.55,"t":"我发现自己已经能预判他什么时候会摸后脑勺了。"},{"s":188.86,"e":206.05,"t":"一般是连续看完三页之后，或者写完一大段之后。他会停一两秒，然后抬起右手，用手掌贴住后脑勺，往上摸一下——很短，不到一秒。"},{"s":206.37,"e":211.6,"t":"有时候他摸完之后，会顺便伸一个懒腰。"},{"s":211.91,"e":231.84,"t":"伸懒腰的时候他会往后靠，椅背发出咯吱一声，两只手举过头顶，手指交叉，掌心朝天。那个动作会持续大概三秒，然后他收回来，继续低头看书。"},{"s":232.15,"e":237.14,"t":"第一次看见他伸懒腰的时候，我正在喝水。"},{"s":237.45,"e":239.19,"t":"差点呛到。"},{"s":239.5,"e":248.72,"t":"不是因为他伸懒腰的样子有什么特别的——是因为我发现我竟然在看他。"},{"s":249.03,"e":250.78,"t":"一直在看。"},{"s":251.09,"e":259.81,"t":"从早自习看到第一节课预备铃响，从大课间看到最后一节课下课。"},{"s":260.12,"e":274.57,"t":"我站在走廊上、站在窗户边上、有时候甚至站在教室后门——只要那个角度能看见他，我就会不自觉地往那边看。"},{"s":274.88,"e":281.36,"t":"我说服自己：我只是在发呆。只是刚好面朝那个方向。"},{"s":281.67,"e":283.42,"t":"但我知道不是。"},{"s":283.73,"e":288.21,"t":"因为我发呆的时候，脑子里想的全是他。"},{"s":288.53,"e":293.76,"t":"十月中旬的时候，我记住了他大部分的习惯。"},{"s":294.07,"e":310.02,"t":"他每天中午会去食堂，但不是去一楼的普通窗口——他去二楼，最里面那个面食窗口。每次都是同一碗面，不加辣，加一个煎蛋。"},{"s":310.33,"e":317.55,"t":"这件事我是怎么知道的？因为我开始调整自己去食堂的时间了。"},{"s":317.86,"e":328.83,"t":"不是跟踪他——我在心里这么强调。只是刚好我也想在那个时间去二楼。刚好。"},{"s":329.14,"e":338.11,"t":"有一个周五的中午，我端着餐盘找位子，发现他坐在靠窗的位置，一个人。"},{"s":338.42,"e":344.4,"t":"那张桌子能坐四个人，其他三个位子都是空的。"},{"s":344.71,"e":350.44,"t":"我端着餐盘站在走道中间，犹豫了大概五秒。"},{"s":350.75,"e":353,"t":"然后我走了过去。"},{"s":353.31,"e":359.04,"t":"坐到同一张桌子——但是隔了两个位子的对角。"},{"s":359.35,"e":361.34,"t":"他抬头看了我一眼。"},{"s":361.65,"e":368.88,"t":"就一眼——大概一秒。然后他低下头，继续吃面了。"},{"s":369.19,"e":381.9,"t":"那个眼神没有任何表情——不是友好，也不是不友好，就是看了一眼，确认有人坐过来了，然后移开。"},{"s":382.21,"e":386.45,"t":"就像确认今天天气不错一样普通。"},{"s":386.76,"e":390,"t":"但我记了一整个下午。"},{"s":390.31,"e":406.75,"t":"他看我的那一眼——他的眼睛确实很亮。在食堂的日光灯下面，那种亮不是阳光反射出来的亮，是他眼睛里本来就有的那种亮。"},{"s":407.06,"e":411.8,"t":"我低头扒饭的时候，心跳得有点快。"},{"s":412.11,"e":414.6,"t":"但我没表现出来。"},{"s":414.91,"e":416.66,"t":"吃完了就走了。"},{"s":416.97,"e":424.94,"t":"走出食堂大门的时候，我对自己说：他只是看了你一眼。你别想太多。"},{"s":425.25,"e":432.73,"t":"但我走出十米之后，还是回头看了一眼食堂二楼那扇窗户。"},{"s":433.04,"e":437.27,"t":"他还在那里。低着头，继续吃面。"},{"s":437.59,"e":440.33,"t":"后来我养成了一个习惯。"},{"s":440.64,"e":450.35,"t":"每天吃完晚饭之后，我不直接回教室——我会绕到教学楼后面，从那条小路走。"},{"s":450.67,"e":456.15,"t":"那条路不是回教室最近的路，甚至有点绕。"},{"s":456.46,"e":468.67,"t":"但那条路经过 610 班教室窗户的背面——从那里，我可以透过窗户的反光，看到里面的人影。"},{"s":468.98,"e":476.95,"t":"有一次我走到那棵梧桐树下面的时候——刚好看见他站在窗边。"},{"s":477.26,"e":485.24,"t":"他没在看书。他站窗户边上，一只手撑在窗沿上，看着窗外。"},{"s":485.55,"e":489.04,"t":"看的方向——是这边。"},{"s":489.35,"e":492.09,"t":"是 611 班的方向。"},{"s":492.4,"e":497.63,"t":"我站在那棵梧桐树下面，脚步停住了。"},{"s":497.94,"e":510.15,"t":"风把树叶吹得沙沙响，秋天的光从他身后的教室里透出来，把他的轮廓勾出一道金边。"},{"s":510.46,"e":513.95,"t":"他站在窗户边上，看着这边。"},{"s":514.26,"e":517,"t":"我不知道他在看什么。"},{"s":517.32,"e":527.28,"t":"但那一刻我发现——我在这棵梧桐树下面站了多久，他就站了多久。"},{"s":527.59,"e":531.08,"t":"然后他转过身，走回座位了。"},{"s":531.39,"e":535.88,"t":"我站在树下面，心脏跳得有点快。"},{"s":536.19,"e":540.92,"t":"刚才——他看的，是我这边吗？"},{"s":541.24,"e":544.72,"t":"还是只是碰巧看向这个方向？"},{"s":545.03,"e":546.78,"t":"我不知道。"},{"s":547.09,"e":554.32,"t":"但我发现——从那天起，我走那条路的次数更多了。"},{"s":554.63,"e":560.61,"t":"十月底的某一天，我在走廊上又站了快十分钟。"},{"s":560.92,"e":568.14,"t":"周海从教室里探出头来：\"林深，你最近是不是瘦了？\""},{"s":568.46,"e":569.45,"t":"\"有吗？\""},{"s":569.76,"e":574.75,"t":"\"有。你每天中午不去食堂的二楼吗？\""},{"s":575.06,"e":576.55,"t":"我愣了一下。"},{"s":576.86,"e":581.1,"t":"\"你——怎么知道我中午去二楼？\""},{"s":581.41,"e":591.88,"t":"\"因为你上周说了五次'二楼的面比较好吃'。\"周海靠在门框上，\"你以前不是吃一楼的吗？\""},{"s":592.19,"e":593.43,"t":"我没回答。"},{"s":593.75,"e":594.99,"t":"他也没追问。"},{"s":595.3,"e":606.76,"t":"但他看了一眼我站的位置——那个刚好能看到对面 610 班最后一排的位置——然后笑了一下。"},{"s":607.08,"e":610.56,"t":"那个笑很轻，什么话都没说。"},{"s":610.88,"e":617.6,"t":"但我总觉得他笑的那个意思，我有点不敢细想。"},{"s":617.91,"e":624.64,"t":"晚上躺在床上的时候，我想起下午窗口的那个画面。"},{"s":624.95,"e":628.94,"t":"他站在窗户边，看着这个方向。"},{"s":629.25,"e":635.98,"t":"夕阳的光照在他脸上，他眯了一下眼睛，但没有马上走。"},{"s":636.29,"e":639.03,"t":"他站了大概有七八秒。"},{"s":639.34,"e":641.83,"t":"然后才转身回去。"},{"s":642.14,"e":645.88,"t":"我翻了个身，把脸埋进枕头里。"},{"s":646.19,"e":652.92,"t":"我知道这个动作是什么意思——我在逃避。"},{"s":653.23,"e":655.23,"t":"逃避什么？"},{"s":655.54,"e":660.02,"t":"逃避一个我越来越清楚的念头。"},{"s":660.33,"e":663.57,"t":"我不是\"刚好\"站在那个位置。"},{"s":663.88,"e":668.37,"t":"我不是\"刚好\"在那个时间去食堂。"},{"s":668.68,"e":673.41,"t":"我不是\"刚好\"绕路走教学楼后面那条路。"},{"s":673.73,"e":677.21,"t":"我——我就是想看他。"},{"s":677.53,"e":684.25,"t":"这个念头，我在心里放了大概两周，没敢对自己说出口。"},{"s":684.56,"e":686.31,"t":"但它在那里。"},{"s":686.62,"e":694.59,"t":"像那扇窗户的反光一样——你看不透它，但你知道它后面有什么东西。"},{"s":694.9,"e":696.9,"t":"一直在那里。"}]},{"num":3,"title":"第3章 红笔划一道","file":"chapters/ch003.mp3","dur":692.5,"size_mb":5.3,"segs":[{"s":0,"e":10.16,"t":"时间：9 月底—11 月 7 日 · 高一上"},{"s":10.79,"e":22.47,"t":"我观察了他大概三个星期之后，发现了一个规律。"},{"s":23.1,"e":28.69,"t":"他每天会做同一件事。"},{"s":29.32,"e":80.1,"t":"下午最后一节自习课——大概 4 点 50 分左右——他会从笔袋里拿出一支红笔，在面前的本子上写几行字。写完之后，他会用红笔在那一页的末尾划一道——一笔，从右到左，不长不短。"},{"s":80.74,"e":88.86,"t":"然后他把本子合上，放回抽屉。"},{"s":89.49,"e":94.57,"t":"每天都这样。"},{"s":95.21,"e":112.98,"t":"我站在走廊上，隔着反光玻璃，看了整整一周才确认自己没看错。"},{"s":113.61,"e":139.51,"t":"那支红笔——不是老师用的那种批改红笔，是那种细头的、写字的红笔。笔帽上有一个小小的夹子。"},{"s":140.15,"e":143.19,"t":"他在写什么？"},{"s":143.83,"e":147.89,"t":"写日记？"},{"s":148.52,"e":151.57,"t":"做题？"},{"s":152.2,"e":155.76,"t":"我不知道。"},{"s":156.39,"e":170.61,"t":"但那个动作——写完，划一道，合上——我记住了。"},{"s":171.25,"e":193.59,"t":"周日下午我在宿舍洗衣服，端着盆往水房走的时候，在楼梯转角听见了一个声音。"},{"s":194.22,"e":197.78,"t":"有人在读什么。"},{"s":198.41,"e":202.47,"t":"我放慢脚步。"},{"s":203.11,"e":209.71,"t":"——不是中文。是英文。"},{"s":210.34,"e":222.02,"t":"声音不高，带着一点尾音。句子不长，像是诗。"},{"s":222.66,"e":231.29,"t":"我站在转角后面，没有走出去。"},{"s":231.92,"e":255.79,"t":"那声音继续读了几行。我听不太懂内容——有几个单词我没学过。但那个声音的节奏我记得。"},{"s":256.42,"e":260.49,"t":"是他的声音。"},{"s":261.12,"e":274.83,"t":"我站在那里，等到声音停下来，才端着盆走出去。"},{"s":275.47,"e":281.05,"t":"楼梯转角没有人了。"},{"s":281.69,"e":305.04,"t":"但我下楼的时候，看见了那个背影——他走在前面，手里拿着一本书，封面是深色的。"},{"s":305.68,"e":308.22,"t":"英文诗。"},{"s":308.85,"e":312.91,"t":"他在读英文诗。"},{"s":313.55,"e":321.17,"t":"第一次对视发生在一个周二。"},{"s":321.8,"e":343.63,"t":"我站在走廊上，假装在看楼下。其实我的目光在玻璃的反光里——他的方向。"},{"s":344.27,"e":348.84,"t":"他刚好抬起头。"},{"s":349.47,"e":355.57,"t":"然后他往窗外看了一眼。"},{"s":356.2,"e":376.01,"t":"就一眼——但那一瞬间，他的目光和我的目光，在反光玻璃上交错了。"},{"s":376.64,"e":379.69,"t":"不到 1 秒。"},{"s":380.32,"e":387.43,"t":"他低下头，继续写字了。"},{"s":388.06,"e":394.67,"t":"我也低下头，假装在看书。"},{"s":395.3,"e":400.89,"t":"心跳快得不像话。"},{"s":401.52,"e":420.82,"t":"但那 1 秒里——我看见他的眼睛了。不是隔着 5 米的轮廓，是真的看见了。"},{"s":421.45,"e":425.01,"t":"很亮。"},{"s":425.64,"e":430.21,"t":"和第一天一样亮。"},{"s":430.84,"e":443.03,"t":"11 月 7 号那一天，我做了一件自己都没想到的事。"},{"s":443.67,"e":464.99,"t":"早自习结束后，我从教学楼出来，往宿舍走。走到宿舍门口的时候——他站在门口。"},{"s":465.63,"e":478.83,"t":"不是等我。他站在门口看手机，大概是在等谁。"},{"s":479.46,"e":492.67,"t":"我从他旁边经过——准备进门的时候，他抬了一下头。"},{"s":493.3,"e":497.36,"t":"然后他看了我一眼。"},{"s":498,"e":509.17,"t":"不是\"不小心扫到\"的那种——是对上了。"},{"s":509.8,"e":513.87,"t":"他看着我的眼睛。"},{"s":514.5,"e":518.05,"t":"大概 3 秒。"},{"s":518.69,"e":526.81,"t":"然后他低下头，继续看手机了。"},{"s":527.45,"e":544.2,"t":"我走进宿舍大门，走到走廊尽头，推开自己那间的门，坐下来。"},{"s":544.84,"e":555.5,"t":"然后我才发现——我的手在抖。"},{"s":556.14,"e":572.39,"t":"我把书包放在床上，坐在床沿上，盯着对面墙上的某一块污渍。"},{"s":573.02,"e":579.11,"t":"然后我在心里说了一句话。"},{"s":579.75,"e":588.89,"t":"说出来的时候，整个房间都安静了。"},{"s":589.52,"e":592.57,"t":"\"我喜欢他。\""},{"s":593.2,"e":597.27,"t":"我用手捂住脸。"},{"s":597.9,"e":601.46,"t":"完了。"},{"s":602.09,"e":605.64,"t":"我在心里说。"},{"s":606.28,"e":609.33,"t":"彻底完了。"},{"s":609.96,"e":625.19,"t":"然后，我又在心里说了一遍——第二遍说得比第一遍更确定："},{"s":625.83,"e":628.88,"t":"\"我喜欢他。\""},{"s":629.51,"e":636.62,"t":"那天晚上我没怎么睡着。"},{"s":637.25,"e":647.41,"t":"不是因为紧张——是因为我终于承认了。"},{"s":648.04,"e":660.23,"t":"10 月底的时候，我在楼梯转角听到他读英文诗。"},{"s":660.87,"e":673.05,"t":"11 月 7 号，我在宿舍门口和他对视了 3 秒。"},{"s":673.69,"e":683.33,"t":"然后我对自己说：我喜欢他。"},{"s":683.97,"e":692.6,"t":"从那天开始，一切都变了。"}]},{"num":4,"title":"第4章 走廊上的守望","file":"chapters/ch004.mp3","dur":670.5,"size_mb":5.1,"segs":[{"s":0,"e":6.31,"t":"时间：11 月 8 日—16 日 · 高一上"},{"s":6.67,"e":13.26,"t":"11 月 7 号那天晚上，我在宿舍想了一夜。"},{"s":13.62,"e":42.01,"t":"不是刻意想——是闭上眼睛之后，那个画面就一直浮在眼前。宿舍门口，他看着我的那个眼神——3 秒。他一定看见了我的表情，看见了我愣住的样子，看见了我移开目光之前那一瞬间的慌张。"},{"s":42.37,"e":46.39,"t":"我翻了个身，把被子拉到下巴。"},{"s":46.74,"e":66.53,"t":"宿舍里很安静。上铺的周海已经睡着了，呼吸声很均匀。对面床的人不知道在梦里嘟囔了一句什么，翻了个身，又安静了。"},{"s":66.89,"e":70.33,"t":"我睁着眼睛看天花板。"},{"s":70.69,"e":75.56,"t":"那一刻我对自己说：你完了。"},{"s":75.92,"e":79.65,"t":"你知道\"完了\"是什么意思吗？"},{"s":80.01,"e":97.22,"t":"不是害怕。是终于承认了——你每天站在走廊上，不是为了吹风，不是为了背书，不是为了任何你对自己编的理由。"},{"s":97.57,"e":100.16,"t":"你就是为了看他。"},{"s":100.51,"e":106.82,"t":"这个念头说出来之后，反而没那么可怕了。"},{"s":107.18,"e":111.48,"t":"可怕的是——我接下来该怎么办？"},{"s":111.84,"e":118.44,"t":"第二天早上，我站在走廊上的时候，感觉不一样了。"},{"s":118.8,"e":129.69,"t":"以前我站在这里，心里是空的——我就是站着，看着对面，脑子里什么都不想。"},{"s":130.05,"e":133.78,"t":"但现在我心里有东西了。"},{"s":134.14,"e":152.78,"t":"一层薄薄的、透明的、说不清的东西——像窗户上那层反光。我知道它在那里，但我不想戳破。"},{"s":153.14,"e":160.59,"t":"我站在窗边，手里拿着英语课本，假装在背单词。"},{"s":160.95,"e":177.01,"t":"对面 610 班的窗户开着——他坐在最后一排，低着头在写什么。从我这个角度，只能看到他的头顶和肩膀的轮廓。"},{"s":177.37,"e":188.27,"t":"他今天穿了一件深蓝色的外套。不是校服，是那种拉链开到一半的抓绒外套。"},{"s":188.62,"e":193.79,"t":"我之前从来没注意过他穿什么衣服。"},{"s":194.14,"e":196.73,"t":"现在我开始注意了。"},{"s":197.08,"e":201.96,"t":"连续几天，我都在观察同一个细节。"},{"s":202.32,"e":204.04,"t":"他的窗户。"},{"s":204.4,"e":220.46,"t":"高一的教室朝南，上午的阳光会从窗户照进去。610 班那扇窗户——他那扇——有时候开着，有时候关着。"},{"s":220.81,"e":223.4,"t":"我发现了一个规律。"},{"s":223.75,"e":229.49,"t":"早自习的时候，他的窗户通常是关着的。"},{"s":229.85,"e":239.02,"t":"但到了大课间——大概九点半到十点之间——窗户会打开。"},{"s":239.38,"e":241.1,"t":"是他开的吗？"},{"s":241.46,"e":243.47,"t":"我开始留意。"},{"s":243.83,"e":262.47,"t":"有一次我特地在大课间的时候站到走廊上——刚好看见他站起来，伸手把窗户往外推。动作很随意，像顺手做的一件小事。"},{"s":262.83,"e":274.58,"t":"他推完窗户之后没有马上坐回去。他站在窗户前面站了两三秒——朝窗外看了一眼。"},{"s":274.94,"e":278.96,"t":"看的方向——是这栋楼。"},{"s":279.32,"e":281.9,"t":"是我站的位置。"},{"s":282.26,"e":288.28,"t":"我下意识往后退了半步，心脏猛地跳了一下。"},{"s":288.64,"e":296.09,"t":"但他没有停留——他看了一眼，然后低下头，转回去了。"},{"s":296.45,"e":300.47,"t":"我不知道他看到了什么。"},{"s":300.82,"e":307.13,"t":"但我知道——他推开窗户的时候，没有犹豫。"},{"s":307.49,"e":313.23,"t":"之后的一个星期，我开始记录他的窗户。"},{"s":313.59,"e":322.76,"t":"周一：早自习关，大课间开，午休关，下午开，晚自习关。"},{"s":323.12,"e":327.42,"t":"周二：一整天都关着。"},{"s":327.78,"e":333.8,"t":"周三：早自习关，大课间开了一整节课。"},{"s":334.16,"e":337.32,"t":"周四：全开。"},{"s":337.67,"e":340.26,"t":"周五：全开。"},{"s":340.61,"e":359.83,"t":"我不知道为什么记录这些。我也没打算用这些数据做什么。但我就是会注意到——看到那扇窗户开着的时候，心里会有一点点说不清的踏实。"},{"s":360.19,"e":361.62,"t":"好像他在。"},{"s":361.98,"e":367.14,"t":"好像那扇窗户是他给我的一个信号。"},{"s":367.5,"e":376.39,"t":"虽然我知道——他推开窗户，只是因为教室闷。跟我没有关系。"},{"s":376.75,"e":383.34,"t":"但每次看到那扇窗户开着，我还是会多站一会儿。"},{"s":383.7,"e":389.72,"t":"有一天午休，我又绕到教学楼后面那条路。"},{"s":390.08,"e":402.41,"t":"十一月的梧桐树已经秃了大半，落叶在地上铺了厚厚一层，踩上去沙沙响。"},{"s":402.77,"e":410.23,"t":"我从树后面走过的时候，习惯性地抬头看他的窗户。"},{"s":410.59,"e":412.88,"t":"然后我停住了。"},{"s":413.24,"e":415.53,"t":"他站在窗户边上。"},{"s":415.89,"e":432.52,"t":"不是那种\"走过来看看窗外\"的站法——他是靠在窗沿上，一只手撑着窗台，另一只手里拿着一本书，低头在看。"},{"s":432.88,"e":440.91,"t":"阳光从他身后照过来，把他的影子投在走廊的地面上。"},{"s":441.27,"e":453.6,"t":"那个画面很安静——安静到我站在树下看了大概十秒，才想起来自己不该看这么久。"},{"s":453.96,"e":457.69,"t":"就在我准备低头走过去的时候——"},{"s":458.05,"e":460.05,"t":"他抬了一下头。"},{"s":460.41,"e":469.02,"t":"不是刻意的抬头——是看书看久了，活动一下脖子那种抬头。"},{"s":469.37,"e":472.82,"t":"但他的目光落向了这边。"},{"s":473.17,"e":476.9,"t":"落在教学楼后面这条路上。"},{"s":477.26,"e":480.99,"t":"落在我站的那棵梧桐树的方向。"},{"s":481.35,"e":483.64,"t":"我整个人僵住了。"},{"s":484,"e":487.44,"t":"他没动。我也没动。"},{"s":487.8,"e":497.84,"t":"隔着大概七八米，隔着十一月的冷空气和满地落叶，他就那么看向这边。"},{"s":498.2,"e":503.07,"t":"然后他低下头，继续看书了。"},{"s":503.43,"e":506.58,"t":"整个过程大概 3 秒。"},{"s":506.94,"e":513.82,"t":"我站在树后面，心跳快得像刚跑完八百米。"},{"s":514.18,"e":515.9,"t":"他看见我了吗？"},{"s":516.26,"e":517.98,"t":"我不知道。"},{"s":518.34,"e":524.36,"t":"但那 3 秒里——我觉得他在看我。"},{"s":524.72,"e":531.03,"t":"回到教室之后，我坐在座位上，盯着桌面发呆。"},{"s":531.39,"e":541.43,"t":"周海从外面进来，手里端着一杯水。他路过我座位的时候停下来，看了我一眼。"},{"s":541.78,"e":544.65,"t":"\"你又去后面那条路了？\""},{"s":545.01,"e":546.73,"t":"\"……嗯。\""},{"s":547.09,"e":553.4,"t":"他不说话了。但他坐下来之前，说了一句："},{"s":553.76,"e":558.92,"t":"\"你最近走那条路的次数是不是有点多？\""},{"s":559.28,"e":561.29,"t":"我没回答。"},{"s":561.64,"e":563.65,"t":"他也等回答。"},{"s":564.01,"e":569.46,"t":"但他说完之后，喝了一口水，补了一句："},{"s":569.82,"e":571.25,"t":"\"我不问了。\""},{"s":571.61,"e":573.9,"t":"他确实没问了。"},{"s":574.26,"e":583.15,"t":"但我心里清楚——他能看出来的事情，别人也能看出来。"},{"s":583.51,"e":587.24,"t":"还好那条路没什么人走。"},{"s":587.6,"e":590.75,"t":"还好那棵梧桐树够大。"},{"s":591.11,"e":595.41,"t":"还好——他没有问我为什么脸红。"},{"s":595.77,"e":600.07,"t":"晚上我在床上想了很久。"},{"s":600.43,"e":607.31,"t":"我想的是：如果他真的看见我了——那又怎么样？"},{"s":607.67,"e":622.58,"t":"他看见一个 611 班的人，每天走教学楼后面的小路，经过他窗户下面的时候抬头看——他会怎么想？"},{"s":622.94,"e":625.81,"t":"我想了十几种可能。"},{"s":626.17,"e":641.65,"t":"最坏的一种是：他根本没注意到我。一切——窗户、抬头、看过来——都只是巧合。"},{"s":642.01,"e":648.61,"t":"最好的一种是：他知道我在看他，但他不介意。"},{"s":648.97,"e":653.55,"t":"我不知道哪一个更接近真相。"},{"s":653.91,"e":660.8,"t":"但那天晚上我入睡之前，脑子里浮出一个念头："},{"s":661.15,"e":666.03,"t":"明天早上，我还要站到走廊上去。"},{"s":666.39,"e":668.4,"t":"不是为了什么。"},{"s":668.75,"e":670.47,"t":"就是习惯了。"}]},{"num":5,"title":"第5章 不算巧合","file":"chapters/ch005.mp3","dur":738.3,"size_mb":5.6,"segs":[{"s":0,"e":9.04,"t":"时间：11 月 17 日—23 日 · 高一上"},{"s":9.46,"e":14.15,"t":"周三那天，我发现了一件事。"},{"s":14.57,"e":23.94,"t":"他的窗户——从那天之后，再也没有关过。"},{"s":24.36,"e":43.78,"t":"我说的是大课间。以前他偶尔会关，偶尔会开，没什么规律。但从上周开始，每天大课间那扇窗户一定是开的。"},{"s":44.2,"e":53.24,"t":"不是开到最大——是推开大概一巴掌宽的缝。"},{"s":53.66,"e":67.05,"t":"我从走廊上走过去的时候，刚好能透过那一条缝，看到他放在桌角的透明水杯。"},{"s":67.47,"e":73.83,"t":"我开始觉得——这不算巧合。"},{"s":74.25,"e":84.96,"t":"但我对自己说：你只是注意到了别人没注意到的细节。不代表什么。"},{"s":85.38,"e":90.07,"t":"周四下午最后一节自习课。"},{"s":90.49,"e":97.85,"t":"我坐在位置上，手里转着笔，盯着窗外发呆。"},{"s":98.27,"e":122.38,"t":"对面 610 班的窗户开着。他不在座位上——大概是去上厕所了。桌上摊着一本书，风从窗户吹进去，把书页吹得哗啦哗啦翻了几页。"},{"s":122.8,"e":129.16,"t":"然后我看见了一个人走到他座位旁边。"},{"s":129.58,"e":144.31,"t":"是隔壁班的一个男生。那人弯腰看了看他桌上的书，然后伸手拿了起来——像是在翻看什么。"},{"s":144.73,"e":149.42,"t":"就在这时，博文从后门进来了。"},{"s":149.84,"e":169.59,"t":"他看见那个人在翻他的书，没有发火，也没有说什么。他只是走过去，把书从那人手里拿回来，合上，放回桌上。"},{"s":170.01,"e":172.35,"t":"动作很平。"},{"s":172.77,"e":184.16,"t":"但那个拿书的男生愣了一下，然后笑了一下，拍了拍他的肩膀，走了。"},{"s":184.58,"e":188.26,"t":"整个过程不到 15 秒。"},{"s":188.68,"e":197.38,"t":"我坐在窗户这边，隔着 5 米的天井，看得清清楚楚。"},{"s":197.8,"e":215.21,"t":"他拿回书的时候——表情没变。没有生气，没有不耐烦，甚至没有多余的话。就像他只是在做一件理所当然的事情。"},{"s":215.63,"e":218.98,"t":"我觉得那个动作很帅。"},{"s":219.4,"e":223.08,"t":"但我没敢继续想下去。"},{"s":223.5,"e":228.19,"t":"周五早上，我去食堂吃早餐。"},{"s":228.61,"e":243,"t":"七点不到，食堂里人还不多。我端着粥找位子的时候——看见了他。"},{"s":243.42,"e":259.83,"t":"他坐在靠墙的位置，面前放着一碗白粥和一碟咸菜，手里拿着一本书，一边吃一边看。"},{"s":260.25,"e":274.65,"t":"他吃东西的速度很慢。舀一勺粥，吹一下，送进嘴里，放下勺子，翻一页书。"},{"s":275.06,"e":282.1,"t":"我端着托盘站在打饭窗口旁边，犹豫了两秒。"},{"s":282.51,"e":289.21,"t":"然后我选了一个离他三张桌子的位置坐下来。"},{"s":289.63,"e":303.69,"t":"不是故意的——至少我是这么告诉自己的。只是因为那个位置靠窗，光线好。"},{"s":304.11,"e":311.81,"t":"我低头喝粥的时候，余光一直往那个方向飘。"},{"s":312.23,"e":317.59,"t":"他没抬头。一直在看书。"},{"s":318.01,"e":323.7,"t":"但有一瞬间——他的动作停了一下。"},{"s":324.12,"e":335.17,"t":"没有抬头，没有转向我——但他在翻页的那一瞬间，停了一下。"},{"s":335.58,"e":337.93,"t":"像在想什么事。"},{"s":338.35,"e":341.7,"t":"然后他继续翻页了。"},{"s":342.11,"e":353.16,"t":"我低头喝了一口粥。甜的。大概是今天食堂的师傅多放了糖。"},{"s":353.58,"e":357.93,"t":"周六没有晚自习。"},{"s":358.35,"e":368.4,"t":"我在宿舍待了一晚上，躺在床上刷手机，什么也没刷进去。"},{"s":368.82,"e":372.83,"t":"脑子里一直转着一个念头。"},{"s":373.25,"e":379.95,"t":"明天是周日。周日晚上有晚自习。"},{"s":380.37,"e":383.05,"t":"他会上晚自习吗？"},{"s":383.47,"e":387.15,"t":"他周末会留在学校吗？"},{"s":387.57,"e":393.93,"t":"他——坐的那个位置，周日晚上能看到他吗？"},{"s":394.35,"e":400.37,"t":"我把手机翻了个面，扣在枕头旁边。"},{"s":400.79,"e":403.81,"t":"我到底在想什么。"},{"s":404.23,"e":410.25,"t":"周日晚上，我提前十分钟到了教室。"},{"s":410.67,"e":431.43,"t":"教室里的灯全亮着，大部分人都到了——周末回家的同学也陆续回来了。空气里有一股从外面带进来的凉意和食堂的饭菜味。"},{"s":431.85,"e":436.2,"t":"我坐下来，拿出物理作业。"},{"s":436.62,"e":440.64,"t":"然后往窗外看了一眼。"},{"s":441.06,"e":444.74,"t":"610 班的灯亮着。"},{"s":445.16,"e":446.5,"t":"他在。"},{"s":446.92,"e":461.31,"t":"坐在最后一排，低着头，在写什么。窗户开着——和上周一样，推开一条缝。"},{"s":461.73,"e":472.45,"t":"我看见他写了一会儿，停下来，拿起桌角的杯子喝了一口水。"},{"s":472.87,"e":479.23,"t":"放下杯子之后——他往窗外看了一眼。"},{"s":479.65,"e":490.7,"t":"不是刻意的——他就是写完了一道题，休息一下目光，往旁边看了一眼。"},{"s":491.11,"e":495.8,"t":"但他看的方向——是这边。"},{"s":496.22,"e":499.57,"t":"是我这扇窗户的方向。"},{"s":499.99,"e":504.34,"t":"然后他低下头，继续写了。"},{"s":504.76,"e":510.79,"t":"我握着笔，手心出了一层薄汗。"},{"s":511.2,"e":513.88,"t":"他的窗户开着。"},{"s":514.3,"e":517.65,"t":"他的杯子放在桌角。"},{"s":518.07,"e":523.09,"t":"他写完题之后，往这边看了一眼。"},{"s":523.51,"e":526.86,"t":"这些都不算巧合。"},{"s":527.28,"e":532.3,"t":"但它们加起来——能算什么？"},{"s":532.72,"e":535.73,"t":"我说不上来。"},{"s":536.15,"e":543.51,"t":"但那天晚上我做物理题的时候，效率特别高。"},{"s":543.93,"e":551.97,"t":"好像有什么东西，在我的胸口轻轻推了一下。"},{"s":552.39,"e":559.42,"t":"下晚自习的时候，我背着书包走出教室。"},{"s":559.84,"e":574.57,"t":"走廊上有好几个人，我侧着身子从人群里穿过去。走到楼梯口的时候——我看见了。"},{"s":574.99,"e":578,"t":"他走在我前面。"},{"s":578.42,"e":589.81,"t":"大概隔了五六级台阶。单肩背着书包，手里拿着那本透明封面的书。"},{"s":590.22,"e":595.25,"t":"他走路的步子不快不慢。"},{"s":595.66,"e":605.71,"t":"我跟在后面，隔着那段距离。没有加快，也没有放慢。"},{"s":606.13,"e":620.19,"t":"楼梯间的灯光把他的影子投在墙上——他的头发在灯光下看起来比白天深一些。"},{"s":620.61,"e":626.64,"t":"走到一楼的时候，他往左拐了。"},{"s":627.06,"e":629.4,"t":"宿舍的方向。"},{"s":629.82,"e":632.16,"t":"我也往左拐了。"},{"s":632.58,"e":643.29,"t":"他在前，我在后。路灯把两个人的影子拉向相反的方向。"},{"s":643.71,"e":651.08,"t":"我看见他走到宿舍楼下的时候，停了一下。"},{"s":651.5,"e":660.2,"t":"没回头——他站在那里，把手里的书换到另一只手上。"},{"s":660.62,"e":664.97,"t":"然后他推开门，进去了。"},{"s":665.39,"e":669.08,"t":"我也走到门口，推开门。"},{"s":669.5,"e":682.89,"t":"门还没完全合上——从我前面大概两三米的地方，有一个人正往走廊深处走。"},{"s":683.31,"e":684.98,"t":"是他。"},{"s":685.4,"e":687.41,"t":"他没回头。"},{"s":687.83,"e":695.86,"t":"但我看见他的脚步，比我走进来之前，慢了一些。"},{"s":696.28,"e":699.3,"t":"只是慢了一些。"},{"s":699.71,"e":703.06,"t":"大概慢了两步。"},{"s":703.48,"e":710.51,"t":"然后他拐进走廊尽头，消失在转角。"},{"s":710.93,"e":718.3,"t":"我站在门口，手指搭在门把手上，好一会儿没动。"},{"s":718.72,"e":730.1,"t":"门外是十一月的夜风。门里是走廊尽头那盏昏暗的灯。"},{"s":730.52,"e":733.2,"t":"他走进去的方向。"},{"s":733.62,"e":738.3,"t":"我刚才——不是巧合吧？"}]},{"num":6,"title":"第6章 嘴角一动","file":"chapters/ch006.mp3","dur":832.8,"size_mb":6.4,"segs":[{"s":0,"e":22.06,"t":"时间：11 月 24 日—26 日 · 高一上"},{"s":23.2,"e":52.61,"t":"11 月 24 号那天发生了一件事。不大。但我记了三天。"},{"s":53.76,"e":96.04,"t":"下午大课间，我站在走廊上。他在对面 610 班的窗户里面——侧着身，正在和同桌说什么。"},{"s":97.18,"e":162.43,"t":"他说话的时候，嘴角动了一下——不是笑，是那种说到一半、因为某个词而微微往上翘了一点的弧度。不到一秒。然后他继续说下去了。"},{"s":163.58,"e":185.64,"t":"我站在走廊上，把那个画面定格在脑子里。"},{"s":186.79,"e":214.36,"t":"回到教室之后，我坐在座位上，在草稿纸上写了一行字："},{"s":215.5,"e":231.13,"t":"\"他今天说话的时候，嘴角动了一下。\""},{"s":232.28,"e":246.98,"t":"写完之后我看着那行字发呆。"},{"s":248.13,"e":257.32,"t":"然后我在下面补了一句："},{"s":258.47,"e":265.82,"t":"\"我是不是完了。\""},{"s":266.97,"e":289.94,"t":"没有主语，没有标点。但我知道我在说什么。"},{"s":291.09,"e":323.26,"t":"11 月 25 号。大课间的时候，我看到他和一个女生站在走廊上说话。"},{"s":324.41,"e":390.57,"t":"不是普通的说话——那个女生站在他对面，手里拿着一本书，好像在问他什么问题。他低头看了一眼那本书，然后说了几句——她笑着点了点头。"},{"s":391.72,"e":402.75,"t":"整个过程大概两分钟。"},{"s":403.9,"e":428.71,"t":"我站在 611 班的走廊转角，隔着天井看到了这一幕。"},{"s":429.86,"e":460.19,"t":"然后我走回教室，坐下来，发现刚才背的单词全都忘了。"},{"s":461.34,"e":469.61,"t":"不是因为那个女生。"},{"s":470.76,"e":503.84,"t":"是因为——他给别人讲题的时候，也会那样侧过头、微微低头吗？"},{"s":504.99,"e":510.5,"t":"会的。"},{"s":511.65,"e":518.08,"t":"他当然会。"},{"s":519.23,"e":537.61,"t":"但我看到的时候，心里还是咯噔了一下。"},{"s":538.76,"e":552.55,"t":"11 月 26 号。降温了。"},{"s":553.7,"e":586.78,"t":"零下十二度。早自习的时候我站在教室门口，呼出的气全是白雾。"},{"s":587.93,"e":665.12,"t":"我往窗外看了一眼——窗户上全是霜雾。反光玻璃变成了毛玻璃，什么都看不见。他的窗户，我的窗户，中间那片天井——全部被白色的霜雾遮住了。"},{"s":666.27,"e":677.3,"t":"我站了一会儿，然后回座位了。"},{"s":678.45,"e":685.8,"t":"那天我没有看到他。"},{"s":686.95,"e":696.14,"t":"一整天都没有。"},{"s":697.29,"e":719.34,"t":"不是因为他不在——是因为什么都看不见。"},{"s":720.49,"e":744.39,"t":"零下十二度的天气，把唯一能看到他的那扇窗户封住了。"},{"s":745.54,"e":778.62,"t":"晚自习的时候，我坐在座位上，看着那片被霜雾封住的玻璃发了一会儿呆。"},{"s":779.77,"e":792.63,"t":"然后我拿起笔，继续做题。"},{"s":793.78,"e":815.84,"t":"但我心里知道——我今天没有看到他。"},{"s":816.99,"e":832.61,"t":"而这件事，比零下十二度还冷。"}]},{"num":7,"title":"第7章 我配不上他","file":"chapters/ch007.mp3","dur":563.3,"size_mb":4.3,"segs":[{"s":0,"e":7.86,"t":"时间：11 月 30 日（周日）— 12 月 3 日（周三）· 高一上"},{"s":8.17,"e":10.87,"t":"周日晚上有晚自习。"},{"s":11.18,"e":26.17,"t":"我坐在靠窗的位置上，面前摊着一本数学练习册——已经做了三页，但脑子里全是乱的。对面的 610 班还有灯。"},{"s":26.48,"e":27.7,"t":"他在不在？"},{"s":28.01,"e":44.23,"t":"我把目光往窗户外移了半寸——没敢转过去太多。余光里，610 班最后一排坐着一个人。低着头，在写什么。"},{"s":44.53,"e":45.76,"t":"博文。"},{"s":46.07,"e":48.53,"t":"他周末也不回家吗？"},{"s":48.83,"e":53.5,"t":"我收回目光，深吸一口气，继续做题。"},{"s":53.81,"e":55.53,"t":"\"林深。\""},{"s":55.84,"e":62.72,"t":"第二天大课间，周海从外面跑进来，表情有点神秘兮兮的。"},{"s":63.02,"e":64.5,"t":"\"我打听到了。\""},{"s":64.81,"e":66.28,"t":"\"打听什么？\""},{"s":66.59,"e":68.06,"t":"\"博文。\""},{"s":68.37,"e":70.83,"t":"我手里的笔顿了一下。"},{"s":71.13,"e":88.33,"t":"周海压低了声音：\"我找张尧问的——张尧你记得吧？上次宿舍楼梯口碰见的那个，他说他就住博文家楼下。\""},{"s":88.64,"e":89.87,"t":"\"他怎么说？\""},{"s":90.18,"e":119.66,"t":"\"他说博文初中是一中附的，从初一开始就是年级前五十——不是 top 那种，但一直稳定在上游。数理特别好，尤其物理，班里经常前五。现在是他们班的学习委员，不是学生会主席——张尧说你听错了，是学习委员不是主席。\""},{"s":119.97,"e":126.85,"t":"我心里记下了：学习委员，数理好，一直稳定。"},{"s":127.15,"e":128.14,"t":"\"还有呢？\""},{"s":128.44,"e":143.43,"t":"\"还有——\"周海看了我一眼，\"他说博文的目标是考个重点一本，一本线往上走的那种。不是清北，就是稳扎稳打的好一本。\""},{"s":143.74,"e":150.87,"t":"我不知道为什么——听到这句话的时候，我反而松了一口气。"},{"s":151.17,"e":152.89,"t":"不是清北。"},{"s":153.2,"e":158.36,"t":"那是不是说明我还有一点点追上的可能？"},{"s":158.67,"e":161.86,"t":"然后我又被自己的想法逗笑了。"},{"s":162.17,"e":166.35,"t":"追什么追。我连他的班都还没进。"},{"s":166.65,"e":168.37,"t":"\"我配不上他。\""},{"s":168.68,"e":174.82,"t":"这句话是周三午休的时候，突然从脑子里冒出来的。"},{"s":175.13,"e":183.97,"t":"我们刚考完数学周测。我翻开答题卡看了一眼——78 分。"},{"s":184.28,"e":186,"t":"78。"},{"s":186.31,"e":189.5,"t":"班里的平均分是 85。"},{"s":189.81,"e":204.31,"t":"我闭上眼，脑子里浮现出博文的身影。他侧身坐着，拿笔在卷子上勾画——我甚至不用去问就知道他能考多少。"},{"s":204.61,"e":209.04,"t":"130？140？"},{"s":209.34,"e":211.8,"t":"起码比我高 50 分。"},{"s":212.11,"e":216.29,"t":"我趴在桌上，把脸埋进胳膊里。"},{"s":216.59,"e":243.62,"t":"\"脑子满了就不会想他了\"——这句话是我自己发明的。意思是，如果我每天做 6 道数学题、背 20 个单词，累到脑子转不动了，就不会有闲工夫翻来覆去地想他在干什么、他今天有没有往窗外看、他走路的时候为什么从来不回头。"},{"s":243.93,"e":249.09,"t":"但事实证明，脑子满了，心还是空的。"},{"s":249.4,"e":252.1,"t":"12 月 1 日，大课间。"},{"s":252.41,"e":262.48,"t":"我站在走廊上——那个我每天都会站的位置。不是故意的，是走惯了。"},{"s":262.79,"e":265.73,"t":"然后我看见了一件事。"},{"s":266.04,"e":273.41,"t":"610 班的窗户——博文那一扇——从里面被推开了。"},{"s":273.72,"e":274.7,"t":"是他。"},{"s":275.01,"e":290,"t":"他站起来，把手伸到窗沿，把窗户往外推开了一点。然后他没有马上坐回去，而是站在窗户边上，抬头往外面看了一眼。"},{"s":290.31,"e":292.03,"t":"往我这个方向。"},{"s":292.33,"e":307.57,"t":"我后退了半步，心猛地跳了一下。——不对。隔着 5 米的天井，他不可能看清我。他只是刚好看向这边。只是刚好。"},{"s":307.87,"e":321.14,"t":"但我还是在他收回目光之前，看到了他的侧脸。阳光落在他的鼻梁上，他眯了一下眼——然后坐回去了。"},{"s":321.45,"e":323.66,"t":"窗户没关。"},{"s":323.97,"e":327.9,"t":"12 月的冷风——他开着窗。"},{"s":328.21,"e":336.56,"t":"我看着那扇敞开的窗户，心里有一个念头，不敢承认，但一直在冒："},{"s":336.87,"e":341.04,"t":"他是不是……也在看这边？"},{"s":341.35,"e":344.05,"t":"12 月 2 日，早自习。"},{"s":344.36,"e":350.75,"t":"我站在教室门口，手里端着水杯，正要转身进去。"},{"s":351.06,"e":353.51,"t":"然后我看见了。"},{"s":353.82,"e":359.72,"t":"对面六楼，610 班的窗户——博文抬起了头。"},{"s":360.03,"e":367.64,"t":"不是一时抬头——他抬起来之后，往窗外看了一下，停住了。"},{"s":367.95,"e":370.41,"t":"他就那么看着这边。"},{"s":370.71,"e":372.19,"t":"看了大概 3 秒。"},{"s":372.5,"e":381.34,"t":"我端着水杯，站在那里，一动不动。不是我故意不动——是我忘了怎么动。"},{"s":381.65,"e":391.23,"t":"我感觉有什么东西在动——不是天井那边的风，是我胸口里的那团东西。它在翻。"},{"s":391.54,"e":393.75,"t":"然后他低下头了。"},{"s":394.06,"e":395.78,"t":"继续看书。"},{"s":396.08,"e":398.79,"t":"像什么都没发生过一样。"},{"s":399.09,"e":401.06,"t":"12 月 3 日。"},{"s":401.37,"e":403.33,"t":"我做了一个决定。"},{"s":403.64,"e":410.52,"t":"每天 6 道数学题，2 篇英语阅读，睡前背 10 个单词。"},{"s":410.83,"e":415.99,"t":"不是为了考试，是为了能进 610 班。"},{"s":416.29,"e":421.94,"t":"周海听说了之后，歪着头看我：\"你认真的？\""},{"s":422.25,"e":423.23,"t":"\"认真的。\""},{"s":423.54,"e":431.9,"t":"\"下学期分班按成绩——你知不知道 610 班至少要年级前 200？\""},{"s":432.2,"e":433.19,"t":"\"我知道。\""},{"s":433.49,"e":435.21,"t":"\"你现在多少名？\""},{"s":435.52,"e":438.96,"t":"\"不知道。但应该不到前 300。\""},{"s":439.27,"e":440.74,"t":"周海没说话。"},{"s":441.05,"e":444.49,"t":"然后他说：\"那你得拼了。\""},{"s":444.8,"e":447.01,"t":"我说：\"我知道。\""},{"s":447.31,"e":455.67,"t":"那天下午，物理老师发完周测卷子，路过我座位的时候停了一下。"},{"s":455.98,"e":459.42,"t":"\"林深，这次比上次进步了。\""},{"s":459.72,"e":465.87,"t":"我抬头——物理老师没有多说什么，只是点了一下头。"},{"s":466.17,"e":476,"t":"旁边化学老师在讲台上也看了我一眼：\"你们班最近几个同学上课精神头不错啊。\""},{"s":476.31,"e":479.99,"t":"他说这句话的时候没看我。"},{"s":480.3,"e":482.76,"t":"但我知道他在说我。"},{"s":483.06,"e":487.73,"t":"被看见的感觉——很暖。"},{"s":488.04,"e":493.94,"t":"晚自习结束我收拾书包的时候，往窗外看了一眼。"},{"s":494.24,"e":497.93,"t":"对面 610 班的灯已经灭了。"},{"s":498.24,"e":505.12,"t":"我背着书包走出教室，走过那条走廊，走下楼梯。"},{"s":505.42,"e":510.83,"t":"走到一楼拐角的时候——我停下了。"},{"s":511.14,"e":520.23,"t":"博文站在宿舍楼门口的灯光下面，单肩背着书包，手里拿着一本书，正在看。"},{"s":520.54,"e":523.73,"t":"他听见脚步声，抬了一下头。"},{"s":524.04,"e":528.46,"t":"看见是我——他好像停了一秒。"},{"s":528.77,"e":532.45,"t":"然后他低头，继续看书了。"},{"s":532.76,"e":538.66,"t":"我走过去，从他身后经过的距离——大概 1 米。"},{"s":538.96,"e":541.67,"t":"我没敢回头看第二眼。"},{"s":541.97,"e":554.5,"t":"但我记住了那个画面：12 月的路灯把他手上的书页照得发白，他的影子斜斜地落在地上，很长。"},{"s":554.81,"e":559.23,"t":"我走进宿舍楼的时候，在心里说了一句："},{"s":559.54,"e":563.23,"t":"我一定要进 610 班。"}]},{"num":8,"title":"第8章 分班之誓","file":"chapters/ch008.mp3","dur":924.3,"size_mb":7.1,"segs":[{"s":0,"e":10.65,"t":"时间：12 月中旬—次年 1 月 · 高一上期末"},{"s":11.19,"e":21.42,"t":"从 12 月 3 号那天开始，我给自己定了一个规矩。"},{"s":21.95,"e":35.16,"t":"每天 6 道数学大题、2 篇英语阅读、睡前背 10 个单词。"},{"s":35.69,"e":42.09,"t":"不是老师布置的——是我自己加的。"},{"s":42.62,"e":54.13,"t":"周海看见我桌上摊开的练习册，歪着头看了一会儿。"},{"s":54.66,"e":58.49,"t":"\"你认真的？\""},{"s":59.03,"e":61.58,"t":"\"认真的。\""},{"s":62.12,"e":68.08,"t":"\"下学期分班——要前 200。\""},{"s":68.62,"e":71.6,"t":"\"我知道。\""},{"s":72.13,"e":75.97,"t":"\"你现在多少？\""},{"s":76.5,"e":82.47,"t":"\"不知道。应该不到前 300。\""},{"s":83,"e":85.98,"t":"他沉默了一会儿。"},{"s":86.51,"e":89.5,"t":"\"那得加把劲。\""},{"s":90.03,"e":93.87,"t":"我说：\"我知道。\""},{"s":94.4,"e":116.99,"t":"那天的对话就这么结束了。但那天晚上我在台灯下面做到第二道数学题的时候，抬头看了一眼窗外。"},{"s":117.52,"e":123.91,"t":"对面 610 班的灯已经灭了。"},{"s":124.45,"e":148.74,"t":"但我脑子里浮现出他坐在最后一排的样子——低头写字，偶尔停下来摸一下后脑勺，偶尔站起来推开窗户。"},{"s":149.27,"e":162.91,"t":"如果我进不了 610 班——下学期我就再也看不到这些了。"},{"s":163.44,"e":168.13,"t":"我低头，继续做题。"},{"s":168.66,"e":178.46,"t":"第三道题的辅助线我画了三遍才画对。"},{"s":179,"e":187.09,"t":"那段时间是我高中最拼命的时候。"},{"s":187.63,"e":243.03,"t":"不是那种热血沸腾的拼——就是每天多做一点，每天多熬一会儿。十二月的教室很冷，窗户关紧了风还是从缝里钻进来。我把校服拉链拉到最高，缩着脖子做题。草稿纸用了一张又一张，写到手指发酸的时候就停下来甩两下，然后继续。"},{"s":243.56,"e":251.23,"t":"我没有告诉任何人我为什么要这么拼。"},{"s":251.77,"e":256.03,"t":"但周海大概是猜到了。"},{"s":256.56,"e":267.22,"t":"有一天晚自习结束的时候，他收拾书包，随口说了一句："},{"s":267.75,"e":272.01,"t":"\"你最近不看对面了。\""},{"s":272.54,"e":275.53,"t":"我的手停了一下。"},{"s":276.06,"e":277.76,"t":"\"……是吗？\""},{"s":278.3,"e":291.51,"t":"\"以前你每写两道题就要抬头看一眼。现在你写半节课都不抬头。\""},{"s":292.04,"e":295.88,"t":"我不知道怎么回答。"},{"s":296.41,"e":305.79,"t":"因为他说的是对的。我确实没怎么抬头了。"},{"s":306.32,"e":310.15,"t":"不是因为不想看了。"},{"s":310.69,"e":329.44,"t":"是因为我怕——如果现在看了，就会分心。如果分心了，就考不进去。"},{"s":329.97,"e":340.2,"t":"如果考不进去——下学期就再也看不到了。"},{"s":340.73,"e":344.14,"t":"所以我低着头。"},{"s":344.67,"e":350.64,"t":"一遍一遍地做题。"},{"s":351.17,"e":368.22,"t":"用每一道题的辅助线、每一个公式、每一页草稿纸——来换一个能继续看到他的资格。"},{"s":368.75,"e":378.56,"t":"期末前两周，有一天下午我在楼梯上遇见了他。"},{"s":379.09,"e":396.14,"t":"不是故意的——我从办公室交作业回来，走到三楼拐角的时候，他从上面走下来。"},{"s":396.67,"e":401.78,"t":"大概隔了三四级台阶。"},{"s":402.32,"e":409.56,"t":"我抬头的时候，他刚好走到我面前。"},{"s":410.09,"e":443.76,"t":"那个距离很近——近到我能看见他外套拉链头的反光，近到我能闻到他身上的味道——不是柚子味的那件衣服，是那种干净的、带着一点洗衣粉残留的味道。"},{"s":444.29,"e":448.13,"t":"他看见了我。"},{"s":448.66,"e":453.78,"t":"我的脚步下意识顿了一下。"},{"s":454.31,"e":456.87,"t":"他也顿了一下。"},{"s":457.4,"e":466.35,"t":"然后他侧了一下身子——让我先走。"},{"s":466.88,"e":474.13,"t":"我说了一声\"谢谢\"，声音比我想象中小。"},{"s":474.66,"e":490.43,"t":"他没回答——但我走过他身边的时候，听到他的脚步声在我身后停了一拍。"},{"s":490.96,"e":496.08,"t":"然后才继续往楼下走。"},{"s":496.61,"e":498.74,"t":"我没有回头。"},{"s":499.27,"e":510.78,"t":"但我走到四楼走廊上的时候，靠在墙边站了大概 10 秒。"},{"s":511.31,"e":514.72,"t":"心跳有点快。"},{"s":515.25,"e":536.14,"t":"不是因为碰到他——是因为我发现，即使只是楼梯上擦肩而过的那一瞬间，我都能认得出他的脚步声。"},{"s":536.67,"e":541.36,"t":"这个认知让我有点慌。"},{"s":541.89,"e":552.54,"t":"我加快脚步走回教室，坐下，翻开练习册。"},{"s":553.08,"e":560.75,"t":"做了两道题之后，才慢慢平静下来。"},{"s":561.28,"e":572.79,"t":"期末考最后一天，我写完英语作文的时候，还剩十五分钟。"},{"s":573.32,"e":578.86,"t":"我放下笔，往窗外看了一眼。"},{"s":579.39,"e":595.59,"t":"对面 610 班的窗户开着——但那排座位是空的。他们已经考完交卷了。"},{"s":596.12,"e":608.48,"t":"我看着那扇空荡荡的窗户，心里忽然涌上来一个念头——"},{"s":609.01,"e":620.09,"t":"如果没考好，这就是我最后一次从这个角度看他了。"},{"s":620.63,"e":628.3,"t":"我低下头，把答题卡检查了一遍。"},{"s":628.83,"e":634.8,"t":"交卷的时候，手指是稳的。"},{"s":635.33,"e":643.43,"t":"但走出考场的那一刻，手心全是汗。"},{"s":643.96,"e":652.06,"t":"寒假开始那天，我在宿舍收拾东西。"},{"s":652.59,"e":673.9,"t":"走廊上很多人都在搬行李，有人喊着\"下学期见\"，有人在楼道里拖着行李箱发出咕噜咕噜的声音。"},{"s":674.43,"e":685.94,"t":"我收拾好背包，站在宿舍门口，往教学楼的方向看了一眼。"},{"s":686.47,"e":697.55,"t":"610 班的窗户关着。放假了，整栋楼都是空的。"},{"s":698.09,"e":700.64,"t":"我站了一会儿。"},{"s":701.18,"e":705.86,"t":"然后背上包，走了。"},{"s":706.4,"e":713.64,"t":"走出校门的时候，我回头看了一眼。"},{"s":714.17,"e":718.01,"t":"那扇窗户还关着。"},{"s":718.54,"e":729.62,"t":"但我在心里说了一句话——不是说出来，是在心里说的："},{"s":730.16,"e":738.25,"t":"下学期，我一定要坐在那扇窗户的后面。"},{"s":738.79,"e":740.49,"t":"等着。"},{"s":741.02,"e":748.7,"t":"寒假里的每一天，我都在做卷子。"},{"s":749.23,"e":767.98,"t":"除夕那天晚上，外面在放鞭炮，我妈在客厅看春晚，我坐在书桌前做了一套物理卷子。"},{"s":768.51,"e":773.2,"t":"做完的时候零点了。"},{"s":773.73,"e":785.67,"t":"我放下笔，拿起手机，打开 QQ——他的头像亮着。"},{"s":786.2,"e":789.18,"t":"在线。"},{"s":789.72,"e":796.53,"t":"我盯着那个亮着的头像看了很久。"},{"s":797.07,"e":800.48,"t":"最后发了一条消息："},{"s":801.01,"e":803.57,"t":"\"新年快乐。\""},{"s":804.1,"e":828.82,"t":"发完之后我立刻把手机翻了过去——不知道为什么，发出去的那一瞬间，我突然觉得这条消息好明显。"},{"s":829.35,"e":834.46,"t":"一分钟后，手机震了一下。"},{"s":835,"e":837.98,"t":"我拿起来看。"},{"s":838.51,"e":841.5,"t":"他回了两个字："},{"s":842.03,"e":844.16,"t":"\"新年快乐。\""},{"s":844.69,"e":850.66,"t":"没有表情，没有多余的标点。"},{"s":851.19,"e":861.42,"t":"但那两个字——我翻来覆去看了好几遍。"},{"s":861.95,"e":870.05,"t":"然后把手机放到枕头下面，闭上眼睛。"},{"s":870.58,"e":875.7,"t":"那天晚上我做了一个梦。"},{"s":876.23,"e":895.83,"t":"梦见开学那天，我走进 610 班的教室，他坐在倒数第三排靠窗的位置，抬起头来看见我。"},{"s":896.37,"e":899.78,"t":"他嘴角动了一下。"},{"s":900.31,"e":909.69,"t":"然后他说——不，梦里他没说话。"},{"s":910.22,"e":913.63,"t":"他只是看了我一眼。"},{"s":914.16,"e":924.39,"t":"但那个眼神——我记了一整个冬天。"}]},{"num":9,"title":"第9章 80 厘米","file":"chapters/ch009.mp3","dur":1009.6,"size_mb":7.7,"segs":[{"s":0,"e":15.45,"t":"时间：2 月 13 日 · 高一下开学第一天"},{"s":16.42,"e":47.32,"t":"高一下开学那天，我站在 610 班的门口，手里攥着书包带子，手心全是汗。"},{"s":48.28,"e":54.46,"t":"我考进来了。"},{"s":55.43,"e":99.46,"t":"611 班到 610 班——中间隔了半层楼、一个学期、无数道数学题。但我做到了。"},{"s":100.43,"e":110.47,"t":"我站在门口往里面看了一眼。"},{"s":111.43,"e":142.34,"t":"教室里已经有人了。三三两两坐在一起的，低头看手机的，趴在桌上补觉的。"},{"s":143.3,"e":150.25,"t":"然后我看到了他。"},{"s":151.22,"e":176.71,"t":"他坐在倒数第三排靠窗的位置——不是最后一排了。换位置了。"},{"s":177.68,"e":182.31,"t":"但他还在。"},{"s":183.28,"e":193.32,"t":"我深吸了一口气，走进去。"},{"s":194.29,"e":215.92,"t":"选座位的时候，我没有犹豫——我走到他正后方的那一排，坐下来。"},{"s":216.88,"e":228.47,"t":"坐下之后，我才发现一件事。"},{"s":229.44,"e":249.52,"t":"以前我在走廊上看他的时候，隔着一个天井，5 米。"},{"s":250.49,"e":264.39,"t":"现在他坐在我前面——隔了不到 1 米。"},{"s":265.36,"e":271.54,"t":"80 厘米。"},{"s":272.5,"e":280.23,"t":"5 米到 80 厘米。"},{"s":281.19,"e":288.15,"t":"用了一个学期。"},{"s":289.11,"e":303.02,"t":"上午第一节课之前，班主任进来点名。"},{"s":303.98,"e":317.89,"t":"点到他的名字的时候——\"博文。\""},{"s":318.85,"e":322.72,"t":"\"到。\""},{"s":323.68,"e":333.73,"t":"我听到了他答\"到\"的声音。"},{"s":334.69,"e":386.45,"t":"声母 d，韵母 ao——dào。正常的音量，不高不低。但那个字落到我耳朵里的时候，我握笔的手指紧了一下。"},{"s":387.41,"e":441.49,"t":"这是我第一次这么近听到他的声音。不是楼梯转角那种远远的诗句声，不是模糊的轮廓——是他坐在我前面不到 1 米的地方，发出的那个字。"},{"s":442.46,"e":454.04,"t":"我低下头，假装在看课本。"},{"s":455.01,"e":462.73,"t":"中午我去办宿舍入住。"},{"s":463.7,"e":487.65,"t":"宿舍楼四楼。我找到分配表上写的那一间——409。"},{"s":488.61,"e":504.84,"t":"推开门的时候，房间里已经有一个人了。"},{"s":505.8,"e":523.57,"t":"蹲在靠窗的床旁边，正在往柜子里塞东西。"},{"s":524.54,"e":533.03,"t":"他听见门响，转过来。"},{"s":534,"e":538.63,"t":"我愣住了。"},{"s":539.6,"e":556.6,"t":"他手里拿着那件没叠好的校服，也停了一下。"},{"s":557.56,"e":562.2,"t":"然后他说："},{"s":563.16,"e":569.34,"t":"\"你也住这间？\""},{"s":570.31,"e":582.67,"t":"我说不出话来，只点了点头。"},{"s":583.63,"e":592.13,"t":"他放下校服，站起来。"},{"s":593.1,"e":599.28,"t":"\"我睡靠窗那边。\""},{"s":600.24,"e":605.65,"t":"\"……那我睡靠门。\""},{"s":606.62,"e":612.8,"t":"对话就这么简单。"},{"s":613.76,"e":644.66,"t":"但我在心里翻来覆去想了一整天——409。同一间。"},{"s":645.63,"e":661.08,"t":"从 5 米外的走廊到 80 厘米的前后桌。"},{"s":662.04,"e":673.63,"t":"从两栋楼到同一间宿舍。"},{"s":674.6,"e":679.23,"t":"这叫什么呢？"},{"s":680.2,"e":693.33,"t":"我想了半天，想不出一个合适的词。"},{"s":694.3,"e":709.75,"t":"但我放行李的时候，嘴角一直在往上翘。"},{"s":710.71,"e":724.62,"t":"晚自习结束后，我收拾好书包站起来。"},{"s":725.58,"e":757.26,"t":"他走到门口的时候停了一下——我以为他忘了什么东西。但他没回头，只是停在那里。"},{"s":758.22,"e":771.35,"t":"等我走到他旁边，他才继续往前走。"},{"s":772.32,"e":786.22,"t":"我们一起走出了教室，走到走廊上。"},{"s":787.19,"e":791.83,"t":"没有说话。"},{"s":792.79,"e":825.24,"t":"但那个距离——不是前后桌的 80 厘米，是并排的、中间隔了大概一个人的距离。"},{"s":826.2,"e":832.38,"t":"我走在他左边。"},{"s":833.35,"e":875.06,"t":"他比我高一点——不，他没我高，但他走路的步子比我长。我稍微加快了一点脚步才能和他保持平行。"},{"s":876.03,"e":889.93,"t":"走到楼梯口的时候，他忽然开口了。"},{"s":890.9,"e":896.31,"t":"\"你叫什么名字？\""},{"s":897.27,"e":900.36,"t":"他问。"},{"s":901.33,"e":916.01,"t":"声音和早上点到的时候一样——不高不低。"},{"s":916.97,"e":940.15,"t":"我走在他旁边，楼梯间的灯光把两个人的影子投在墙上。"},{"s":941.11,"e":944.2,"t":"\"林深。\""},{"s":945.17,"e":951.35,"t":"他点了一下头。"},{"s":952.31,"e":957.72,"t":"\"林深。\""},{"s":958.69,"e":964.87,"t":"他重复了一遍。"},{"s":965.83,"e":972.79,"t":"然后没再说话。"},{"s":973.75,"e":992.29,"t":"但他的脚步，在念完我名字之后，放慢了一点。"},{"s":993.26,"e":1009.48,"t":"刚好够我不用加快脚步，也能走在他旁边。"}]},{"num":10,"title":"第10章 借橡皮","file":"chapters/ch010.mp3","dur":881.3,"size_mb":6.7,"segs":[{"s":0,"e":11.96,"t":"时间：2 月 13 日晚—2 月 14 日 · 高一下开学第一天"},{"s":12.46,"e":17.24,"t":"开学第一天，我办了入住。"},{"s":17.74,"e":45.65,"t":"宿舍在四楼，走廊尽头倒数第二间。推开门的时候，房间里已经有一个人了——背对着我，蹲在靠窗的那张床旁边，正在往柜子里塞东西。"},{"s":46.15,"e":50.93,"t":"他听见门响，转过来。"},{"s":51.43,"e":56.21,"t":"我和博文同时愣了一下。"},{"s":56.71,"e":67.88,"t":"我愣住的原因很明显——我没想过会和他分到同一间。"},{"s":68.37,"e":91.5,"t":"他愣住的原因——我不知道。但他手里的那件叠到一半的校服停在了半空中，过了大概两秒，他才放下。"},{"s":92,"e":95.58,"t":"然后他说了一句话。"},{"s":96.08,"e":98.08,"t":"\"你也住这间？\""},{"s":98.57,"e":101.36,"t":"\"……嗯。\""},{"s":101.86,"e":123.79,"t":"就这么简单。没有多余的寒暄，没有\"好巧啊\"或者\"以后多关照\"——他就点了下头，转过头继续塞柜子了。"},{"s":124.29,"e":139.84,"t":"我站在门口，手里拎着行李箱的拉杆，感觉心脏还没从刚才那一下里缓过来。"},{"s":140.34,"e":144.72,"t":"我选了靠门的那张床。"},{"s":145.22,"e":155.58,"t":"放好行李之后，我坐在床沿上，偷偷看了一眼他的方向。"},{"s":156.08,"e":189.17,"t":"他背对着我，正在铺床单。动作不太熟练——床单的一角塞进去了，另一角又跑出来。他拽了一下，又塞了一次，然后放弃了，把被子往上一盖，眼不见为净。"},{"s":189.67,"e":192.86,"t":"我差点笑出来。"},{"s":193.36,"e":200.14,"t":"原来他铺床单也铺不好。"},{"s":200.64,"e":208.21,"t":"这个发现让我莫名其妙地放松了一点。"},{"s":208.71,"e":214.29,"t":"晚自习结束之后，我回到宿舍。"},{"s":214.79,"e":229.54,"t":"推门进去的时候，他已经在了——坐在床上，手里拿着一本书，在看。"},{"s":230.04,"e":247.58,"t":"我进去的动作很轻——不是故意的，是因为我不知道该用多大声量出现在他面前。"},{"s":248.08,"e":254.46,"t":"我拿了洗漱用品，去水房刷牙。"},{"s":254.96,"e":272.9,"t":"回来的时候，他换了一个姿势——躺下了，书扣在枕头旁边，手机屏幕的光映在他脸上。"},{"s":273.39,"e":279.77,"t":"我轻手轻脚地爬上自己的床。"},{"s":280.27,"e":282.66,"t":"关灯。"},{"s":283.16,"e":293.93,"t":"黑暗中，我听见他的呼吸声——很轻，很均匀。"},{"s":294.43,"e":297.61,"t":"我以为他睡着了。"},{"s":298.11,"e":300.9,"t":"但过了一会儿——"},{"s":301.4,"e":303.79,"t":"\"你叫什么来着？\""},{"s":304.29,"e":314.26,"t":"他的声音从黑暗中传过来。不大，像是随口问的。"},{"s":314.76,"e":316.75,"t":"\"林深。\""},{"s":317.25,"e":319.64,"t":"\"林深。\""},{"s":320.14,"e":326.92,"t":"他重复了一遍。然后安静了几秒。"},{"s":327.42,"e":333.4,"t":"\"森林的林，深浅的深？\""},{"s":333.89,"e":335.89,"t":"\"对。\""},{"s":336.39,"e":338.38,"t":"\"好。\""},{"s":338.88,"e":342.86,"t":"然后就没有了。"},{"s":343.36,"e":350.14,"t":"我躺在黑暗中，睁着眼睛。"},{"s":350.64,"e":354.23,"t":"他记住了我的名字。"},{"s":354.73,"e":365.09,"t":"第二天早自习，我在座位上翻笔袋的时候，发现了一个问题。"},{"s":365.59,"e":368.78,"t":"我的橡皮不见了。"},{"s":369.28,"e":397.58,"t":"我把笔袋翻了个底朝天——没有。又翻了书包的每一个夹层——也没有。昨晚明明放在桌上的，大概是收拾的时候掉在宿舍了。"},{"s":398.08,"e":407.25,"t":"我今天有三节课要写课堂练习。没橡皮不行。"},{"s":407.75,"e":414.13,"t":"我正犹豫要不要回宿舍拿的时候——"},{"s":414.63,"e":420.21,"t":"一块橡皮从旁边推了过来。"},{"s":420.71,"e":423.5,"t":"停在我桌角。"},{"s":424,"e":433.56,"t":"白色的，用得只剩一半了，边角被切掉了一小块。"},{"s":434.06,"e":436.85,"t":"我抬起头。"},{"s":437.35,"e":450.51,"t":"博文已经转回去了——他坐在我前面，背对着我，已经在低头写东西了。"},{"s":451.01,"e":457.39,"t":"他什么时候注意到我在找橡皮的？"},{"s":457.88,"e":462.27,"t":"他什么时候把橡皮拿出来的？"},{"s":462.77,"e":468.75,"t":"他——为什么要借我？"},{"s":469.25,"e":489.58,"t":"我把那块橡皮拿起来，握在手心。上面还带着一点温度——大概是他在口袋里放了一早上。"},{"s":490.08,"e":492.47,"t":"\"谢谢。\""},{"s":492.97,"e":495.36,"t":"我说。"},{"s":495.86,"e":497.85,"t":"他没回头。"},{"s":498.35,"e":513.1,"t":"但我看见他握笔的手停了一下——不到一秒——然后继续写了。"},{"s":513.6,"e":520.38,"t":"那天上午我用了那块橡皮好几次。"},{"s":520.88,"e":528.85,"t":"每次用的时候都下意识看一眼前面那个背影。"},{"s":529.35,"e":558.05,"t":"他坐得很直，低头写字的时候肩膀会微微往左偏。他用的笔是黑色的那种，写字的力道不小，我在后面都能听到笔尖落在纸上的沙沙声。"},{"s":558.55,"e":562.94,"t":"中午我把橡皮还给他。"},{"s":563.43,"e":566.62,"t":"\"谢谢，用完了。\""},{"s":567.12,"e":573.9,"t":"他接过去，没看，直接放进了笔袋里。"},{"s":574.4,"e":576.79,"t":"\"以后不用还。\""},{"s":577.29,"e":579.28,"t":"他说。"},{"s":579.78,"e":581.77,"t":"\"……什么？\""},{"s":582.27,"e":589.05,"t":"\"橡皮这种东西——借了就不用还。\""},{"s":589.55,"e":596.72,"t":"他语气很平，像在陈述一个常识。"},{"s":597.22,"e":599.61,"t":"我愣了一下。"},{"s":600.11,"e":604.1,"t":"\"那我要用的时候——\""},{"s":604.6,"e":606.59,"t":"\"来拿。\""},{"s":607.09,"e":623.44,"t":"他依然没回头。但我看见他的耳朵好像红了一点——也可能是走廊的光线问题。"},{"s":623.93,"e":632.31,"t":"我回到座位上，把这句话在脑子里翻了两遍。"},{"s":632.8,"e":635.2,"t":"\"来拿。\""},{"s":635.7,"e":640.08,"t":"他说的是\"来拿\"。"},{"s":640.58,"e":645.76,"t":"意思是——我可以再找他。"},{"s":646.26,"e":653.44,"t":"晚上回到宿舍，他已经在房间里了。"},{"s":653.93,"e":667.89,"t":"坐在床上，正在往脚上套袜子——看样子是刚从水房洗完脚回来。"},{"s":668.39,"e":679.55,"t":"我推门进去的时候，他抬头看了我一眼，然后又低下去。"},{"s":680.05,"e":685.63,"t":"中间的沉默大概持续了几秒。"},{"s":686.13,"e":697.29,"t":"然后他说：\"你今天下午那节英语课——老师叫你回答问题那次。\""},{"s":697.79,"e":699.78,"t":"\"……怎么了？\""},{"s":700.28,"e":703.47,"t":"\"你答得挺好的。\""},{"s":703.97,"e":716.33,"t":"他说完这句话之后，就低头继续穿袜子了，像什么都没说过一样。"},{"s":716.83,"e":723.6,"t":"我站在房间中央，手里拿着水杯。"},{"s":724.1,"e":726.89,"t":"\"你——你注意到了？\""},{"s":727.39,"e":731.78,"t":"他手上的动作停了一下。"},{"s":732.28,"e":734.67,"t":"\"我坐你前面。\""},{"s":735.17,"e":738.75,"t":"\"……所以？\""},{"s":739.25,"e":742.84,"t":"\"所以——听到了。\""},{"s":743.34,"e":748.12,"t":"他的语气还是那么平。"},{"s":748.62,"e":756.2,"t":"但我注意到他说这句话的时候，没抬头。"},{"s":756.69,"e":765.07,"t":"那天晚上我躺在床上，很久没睡着。"},{"s":765.57,"e":779.52,"t":"不是因为第一天住宿舍不习惯——是因为今天发生的事情太多了。"},{"s":780.02,"e":784,"t":"分了同一间宿舍。"},{"s":784.5,"e":788.09,"t":"他记住了我的名字。"},{"s":788.59,"e":791.78,"t":"他借了我橡皮。"},{"s":792.28,"e":795.47,"t":"他说\"来拿\"。"},{"s":795.96,"e":800.35,"t":"他说我英语回答得好。"},{"s":800.85,"e":816.4,"t":"这些事每一件都不大。但它们堆在一起——堆在我胸口——变成了一种说不清的重量。"},{"s":816.9,"e":819.69,"t":"不重。"},{"s":820.18,"e":823.37,"t":"但让我睡不着。"},{"s":823.87,"e":829.06,"t":"我翻了个身，面向窗户那边。"},{"s":829.55,"e":841.91,"t":"月光从窗帘的缝隙里透进来，在地上画了一条细细的白线。"},{"s":842.41,"e":857.16,"t":"他的床在不远处。我看不清他的脸——只能看到被子微微起伏的轮廓。"},{"s":857.66,"e":860.85,"t":"他已经睡着了。"},{"s":861.35,"e":866.13,"t":"呼吸很均匀。"},{"s":866.63,"e":881.38,"t":"我听着那个声音——不知道为什么——觉得这个房间好像没那么陌生了。"}]},{"num":11,"title":"第11章 你是以前 611 那个","file":"chapters/ch011.mp3","dur":709.5,"size_mb":5.4,"segs":[{"s":0,"e":16.64,"t":"时间：2 月 15 日 · 高一下"},{"s":17.86,"e":43.31,"t":"开学第三天。大课间的时候，我正坐在座位上看书。"},{"s":44.53,"e":68.02,"t":"他转过身来了——不是侧过头，是整个转过来。"},{"s":69.24,"e":73.16,"t":"\"林深。\""},{"s":74.38,"e":97.87,"t":"他叫了我的名字。这是他第一次主动叫我的名字。"},{"s":99.09,"e":114.75,"t":"\"你以前是 611 班的，对吧？\""},{"s":115.97,"e":128.7,"t":"我握着笔的手指紧了一下。"},{"s":129.92,"e":134.81,"t":"\"……对。\""},{"s":136.04,"e":142.89,"t":"他点了点头。"},{"s":144.11,"e":149,"t":"\"我见过你。\""},{"s":150.23,"e":155.12,"t":"我愣住了。"},{"s":156.34,"e":164.17,"t":"\"你——什么时候？\""},{"s":165.4,"e":184.97,"t":"\"你以前每天站在走廊上。靠窗那个位置。\""},{"s":186.19,"e":216.53,"t":"他说这句话的语气很平——像在陈述一个他早就知道的事实。"},{"s":217.76,"e":233.41,"t":"我脑子里的某根弦，绷了一下。"},{"s":234.64,"e":238.55,"t":"他知道。"},{"s":239.78,"e":249.56,"t":"他知道我站在走廊上。"},{"s":250.79,"e":258.62,"t":"他一直知道。"},{"s":259.84,"e":294.09,"t":"我从高一开始就站在那个位置看他——而他，从一开始就看到了我。"},{"s":295.32,"e":314.89,"t":"\"你是以前 611 那个，老站走廊上的人。\""},{"s":316.11,"e":322.96,"t":"他又说了一遍。"},{"s":324.19,"e":337.89,"t":"不是疑问句。是陈述句。"},{"s":339.11,"e":367.49,"t":"我坐在座位上，感觉有什么东西在我胸口稳稳地落下来了。"},{"s":368.72,"e":372.63,"t":"他知道。"},{"s":373.85,"e":391.47,"t":"那天晚自习结束的时候，我在收拾书包。"},{"s":392.69,"e":403.46,"t":"他站起来，走到我桌边。"},{"s":404.68,"e":419.36,"t":"\"明天我把那个英语笔记借你。\""},{"s":420.59,"e":426.46,"t":"\"……什么？\""},{"s":427.68,"e":449.21,"t":"\"你英语笔记上次不是没记全吗？我有完整的。\""},{"s":450.44,"e":460.22,"t":"他说完就走了出去。"},{"s":461.45,"e":483.96,"t":"我坐在座位上，手里握着还没拉好的书包拉链。"},{"s":485.18,"e":499.86,"t":"他连我英语笔记没记全都知道。"},{"s":501.08,"e":527.51,"t":"回到宿舍之后，周海——新同桌——看了我一眼。"},{"s":528.73,"e":540.47,"t":"\"你今天看了他几次你知道吗？\""},{"s":541.7,"e":546.59,"t":"\"……不知道。\""},{"s":547.81,"e":553.69,"t":"\"我帮你数了。\""},{"s":554.91,"e":572.53,"t":"他伸出两只手——十根手指。"},{"s":573.75,"e":579.62,"t":"\"15 次。\""},{"s":580.84,"e":586.72,"t":"我不说话了。"},{"s":587.94,"e":598.71,"t":"\"你知道这意味着什么吗？\""},{"s":599.93,"e":603.84,"t":"\"……什么？\""},{"s":605.07,"e":630.51,"t":"\"你一节晚自习能看他 15 次，但你一道物理题都没做出来。\""},{"s":631.74,"e":640.54,"t":"他说的是对的。"},{"s":641.77,"e":655.47,"t":"我确实一道题都没做出来。"},{"s":656.69,"e":671.37,"t":"因为我一直在想他说的那句话——"},{"s":672.6,"e":693.15,"t":"\"你是以前 611 那个，老站走廊上的人。\""},{"s":694.37,"e":699.26,"t":"他知道。"},{"s":700.49,"e":709.3,"t":"他从一开始就知道。"}]},{"num":12,"title":"第12章 一秒钟","file":"chapters/ch012.mp3","dur":687.5,"size_mb":5.2,"segs":[{"s":0,"e":7.56,"t":"时间：2 月 16 日 · 高一下"},{"s":8.24,"e":18.5,"t":"借笔记这件事，我想了两天才敢做。"},{"s":19.18,"e":54.84,"t":"周四晚自习，我坐在他后面，盯着他的后脑勺看了大概十分钟。他在写物理作业——笔尖在纸上发出沙沙的声音，偶尔停下来翻一页。"},{"s":55.51,"e":60.91,"t":"我深吸了一口气。"},{"s":61.59,"e":68.07,"t":"然后我推了一下椅子——"},{"s":68.75,"e":71.99,"t":"吱。"},{"s":72.67,"e":92.65,"t":"他停了一下笔。没回头，但他知道我在叫他——我们之间好像已经有了这种默契。"},{"s":93.33,"e":97.11,"t":"\"博文。\""},{"s":97.79,"e":100.49,"t":"\"嗯？\""},{"s":101.16,"e":109.81,"t":"\"你英语笔记——能借我看一下吗？\""},{"s":110.48,"e":127.23,"t":"他回头看了我一眼，然后从他桌角拿过那个笔记本，递过来。"},{"s":127.91,"e":131.69,"t":"我伸手去接——"},{"s":132.36,"e":137.23,"t":"我们的手指碰到了。"},{"s":137.9,"e":141.14,"t":"大概 1 秒。"},{"s":141.82,"e":148.3,"t":"他的手指是暖的。"},{"s":148.98,"e":161.94,"t":"我接过来，说了声谢谢，然后低头翻开笔记本。"},{"s":162.62,"e":171.26,"t":"但他的温度，还留在我手指上。"},{"s":171.94,"e":182.2,"t":"那个笔记本我在手里翻了大概 30 分钟。"},{"s":182.88,"e":196.38,"t":"不是因为他记得有多好——是因为我在看他的字。"},{"s":197.06,"e":237.58,"t":"他的英文字母写得很整齐——不圆，偏方，每个字母之间的距离都差不多。不像他写中文那样飞起来的样子，写英文的时候他好像会认真一点。"},{"s":238.26,"e":270.13,"t":"我翻到中间的时候，看见了一个小小的涂鸦——在某一页的右下角，他画了一个歪歪扭扭的笑脸，只有眼睛和嘴巴，没有脸。"},{"s":270.81,"e":275.13,"t":"我差点笑出来。"},{"s":275.8,"e":287.15,"t":"然后我合上笔记，深吸一口气，还给他。"},{"s":287.82,"e":291.07,"t":"\"谢谢。\""},{"s":291.74,"e":295.52,"t":"他接过去。"},{"s":296.2,"e":310.24,"t":"然后他又把物理作业本推了过来——打开到最新的一页。"},{"s":310.92,"e":323.89,"t":"\"你看一下这道题的方法——我用的和老师讲的不一样。\""},{"s":324.56,"e":341.31,"t":"我低头看。他确实用了另一种解法——比老师讲的短两步。"},{"s":341.99,"e":357.11,"t":"我抬头想说\"谢谢\"的时候——他正低着头，翻自己的书。"},{"s":357.79,"e":373.46,"t":"从他的校服领口那里，我看到他脖颈上那一截白。"},{"s":374.13,"e":378.99,"t":"只露了一瞬间。"},{"s":379.67,"e":385.07,"t":"然后他抬起头来了。"},{"s":385.75,"e":392.77,"t":"我赶紧把目光移回本子上。"},{"s":393.44,"e":402.63,"t":"晚自习快结束的时候，我收拾书包。"},{"s":403.3,"e":409.79,"t":"他坐在前面，也在收拾。"},{"s":410.46,"e":427.21,"t":"然后他回头了——不是转身，是侧过头，往我这边看了一眼。"},{"s":427.89,"e":432.75,"t":"他的嘴角动了一下。"},{"s":433.42,"e":446.39,"t":"不是说话——是嘴角微微往上翘了一下，不到半秒。"},{"s":447.07,"e":451.39,"t":"然后他转回去了。"},{"s":452.06,"e":459.63,"t":"我握着书包带子，愣在原地。"},{"s":460.3,"e":469.49,"t":"这个嘴角动——我见过。"},{"s":470.16,"e":482.05,"t":"11 月 24 号，隔着天井，5 米之外。"},{"s":482.72,"e":499.47,"t":"现在他坐在我前面 80 厘米的地方，我不用隔着玻璃也能看到了。"},{"s":500.15,"e":504.47,"t":"同一个弧度。"},{"s":505.14,"e":508.39,"t":"同一个人。"},{"s":509.06,"e":529.05,"t":"周海——新的周海，不是高一上同铺的那个——在我回到宿舍之后，看了我一眼。"},{"s":529.73,"e":537.83,"t":"\"你今天看了他多少次你知道吗？\""},{"s":538.51,"e":541.21,"t":"\"……不知道。\""},{"s":541.88,"e":548.36,"t":"\"我帮你数了。15 次。\""},{"s":549.04,"e":552.28,"t":"我愣了一下。"},{"s":552.96,"e":556.74,"t":"\"你数这个干嘛？\""},{"s":557.41,"e":574.16,"t":"\"帮你数。\"他坐在床沿上，翘着腿。\"15 次。一节晚自习。\""},{"s":574.84,"e":578.62,"t":"他顿了顿。"},{"s":579.29,"e":591.18,"t":"\"要不要我帮你定一个标准——每天最多 5 次。\""},{"s":591.86,"e":596.18,"t":"\"……5 次太少了。\""},{"s":596.85,"e":600.09,"t":"\"那就 10 次。\""},{"s":600.77,"e":603.47,"t":"我想了想。"},{"s":604.15,"e":607.93,"t":"\"……7 次。\""},{"s":608.6,"e":611.31,"t":"\"成交。\""},{"s":611.98,"e":629.81,"t":"——那天晚上我躺在床上，把今天发生的事情在脑子里过了一遍。"},{"s":630.48,"e":635.89,"t":"手指碰到他的那一秒。"},{"s":636.56,"e":643.05,"t":"他脖颈上那一截白。"},{"s":643.72,"e":651.82,"t":"他回头时嘴角动了一下的弧度。"},{"s":652.5,"e":662.77,"t":"嘴角动了一下——和 11 月 24 号一模一样。"},{"s":663.44,"e":666.14,"t":"7 次。"},{"s":666.82,"e":670.6,"t":"我闭上眼睛。"},{"s":671.27,"e":679.38,"t":"明天一定要控制在 7 次以内。"},{"s":680.05,"e":687.62,"t":"--- 第二天我看了他 11 次。"}]},{"num":13,"title":"第13章 错题本","file":"chapters/ch013.mp3","dur":901.7,"size_mb":6.9,"segs":[{"s":0,"e":14.53,"t":"时间：2 月 18 日—20 日 · 高一下"},{"s":15.25,"e":27.45,"t":"借完笔记之后，我以为接下来不会再有什么了。"},{"s":28.18,"e":40.96,"t":"但第三天晚上，我桌子上多了一个本子。"},{"s":41.69,"e":45.76,"t":"不是我的。"},{"s":46.48,"e":72.05,"t":"我坐下来的时候，一眼就看见了——一个牛皮纸封面的笔记本，A5 大小，放在我桌子的正中央。"},{"s":72.77,"e":76.84,"t":"我翻开第一页。"},{"s":77.57,"e":129.28,"t":"字迹飞起来了一样——不是那种整整齐齐的笔记，是写的人自己才看得懂的写法。公式和公式之间穿插着只有缩写和箭头，有些地方用红笔打了圈，旁边写着三个字："},{"s":130,"e":132.91,"t":"\"别踩坑。\""},{"s":133.64,"e":138.87,"t":"我往后翻了几页。"},{"s":139.59,"e":177.94,"t":"每一页都是这样的——不是完整的题目解析，是那种\"我当年做错了、你们别走我的老路\"的错题集。不是老师布置的，是他自己的。"},{"s":178.67,"e":192.61,"t":"翻到中间的时候，有一页的页脚多了一行小字："},{"s":193.34,"e":203.8,"t":"\"这题期中考了，记住。回头看后面那道。\""},{"s":204.52,"e":220.79,"t":"我看了一下日期——不是今年的，是他高一的期中考。"},{"s":221.52,"e":229.07,"t":"他把自己的错题本，拿给我了。"},{"s":229.8,"e":242.58,"t":"第二天早上我把本子带去教室，准备还给他。"},{"s":243.31,"e":249.7,"t":"\"博文，这个——\""},{"s":250.42,"e":253.91,"t":"\"看完了？\""},{"s":254.64,"e":263.35,"t":"\"还没——但这是你的——\""},{"s":264.08,"e":268.14,"t":"\"看完再还。\""},{"s":268.87,"e":277,"t":"他头也没抬，正在翻英语书。"},{"s":277.73,"e":285.28,"t":"\"里面可能有你看得上的题。\""},{"s":286.01,"e":293.56,"t":"他说完就站起来去接水了。"},{"s":294.29,"e":309.4,"t":"我站在原地，手里拿着那本错题本，好几秒没动。"},{"s":310.12,"e":338.59,"t":"\"里面可能有你看得上的题\"——他不是说\"可能有你不会的题\"，他说的是\"你可能看得上的\"。"},{"s":339.32,"e":346.29,"t":"他用了\"看得上\"这个词。"},{"s":347.02,"e":353.99,"t":"好像他默认我有那个水平。"},{"s":354.72,"e":360.53,"t":"那天中午我没去食堂。"},{"s":361.25,"e":375.78,"t":"我坐在座位上，把他的错题本从头到尾翻了一遍。"},{"s":376.51,"e":434.61,"t":"他的字虽然飞，但每一道题旁边都写了错因。大部分不是\"公式记错了\"或者\"计算失误\"——是很具体的，像\"这题我用了分析法但应该用建系\"\"第二问我跳过了一个隐条件，在这里→画了一条线标出来\"。"},{"s":435.33,"e":451.02,"t":"他用红笔写的不是正确答案，是\"我当时怎么掉坑里的\"。"},{"s":451.75,"e":465.11,"t":"我看完最后一页的时候，有一种很奇怪的感觉。"},{"s":465.84,"e":482.69,"t":"不是\"他好厉害\"——他确实厉害，但这不是我最大的感受。"},{"s":483.41,"e":500.26,"t":"我最大的感受是——他是一个会认真对待自己犯过的错的人。"},{"s":500.99,"e":513.77,"t":"大多数人是把错题抄一遍，记个答案就完了。"},{"s":514.5,"e":518.57,"t":"他不是。"},{"s":519.29,"e":541.37,"t":"他把每一道错题都变成了一个标记——\"这里要注意\"、\"这里我下次不会再错了\"。"},{"s":542.1,"e":551.4,"t":"我把本子合上，手指按在封面上。"},{"s":552.12,"e":569.55,"t":"那一瞬间我忽然觉得——我好像认识他更多了一点。"},{"s":570.28,"e":583.64,"t":"晚自习结束后，我回宿舍的时候，他已经在了。"},{"s":584.37,"e":595.99,"t":"坐在床上，戴着一边耳机，在看手机。"},{"s":596.72,"e":608.34,"t":"我走过去，把那本错题本放在他床角。"},{"s":609.06,"e":613.13,"t":"\"看完了。\""},{"s":613.86,"e":617.34,"t":"他摘下耳机。"},{"s":618.07,"e":621.55,"t":"\"怎么样？\""},{"s":622.28,"e":642.04,"t":"\"——你那个分析法的题，我看懂了。但你画的那个图，我看了三遍才明白。\""},{"s":642.76,"e":660.19,"t":"他嘴角动了一下——不是笑，是那种\"果然\"的表情。"},{"s":660.92,"e":671.96,"t":"\"第一遍看都那样。看多了就习惯了。\""},{"s":672.68,"e":678.49,"t":"\"……你还有多少本？\""},{"s":679.22,"e":682.71,"t":"他想了想。"},{"s":683.43,"e":695.05,"t":"\"数学两本，物理一本半，化学半本。\""},{"s":695.78,"e":699.85,"t":"\"半本？\""},{"s":700.57,"e":705.22,"t":"\"化学刚开。\""},{"s":705.95,"e":708.85,"t":"他顿了顿。"},{"s":709.58,"e":715.39,"t":"\"你想看的话，自己拿。\""},{"s":716.12,"e":743.42,"t":"他说这句话的时候，目光落在手机屏幕上，语气像在说\"冰箱里有吃的你自己拿\"一样随意。"},{"s":744.15,"e":754.03,"t":"我说了一声\"好\"，转身走回自己的床。"},{"s":754.75,"e":777.41,"t":"坐下来的那一刻，我才注意到——我刚才和他说话的时候，没有任何紧张。"},{"s":778.14,"e":785.69,"t":"像和老朋友说话一样自然。"},{"s":786.42,"e":798.04,"t":"这个认知让我坐在床沿上愣了一会儿。"},{"s":798.77,"e":811.55,"t":"周五晚上，我坐在书桌前，也翻出了一个本子。"},{"s":812.28,"e":834.94,"t":"不是新的——是我高一上的数学错题本，零零散散记了十几页，后面就空了。"},{"s":835.66,"e":844.38,"t":"我在第一页空白处写了几行字："},{"s":845.1,"e":877.06,"t":"\"2/18 借了博文的错题本。 他写错因的方式：不是写正确答案，是写'我当时怎么掉坑里的'。 我以后也这么写。\""},{"s":877.79,"e":889.99,"t":"写完之后我看着这几行字，忽然觉得——"},{"s":890.72,"e":901.75,"t":"这个本子，以后大概会经常翻开了。"}]},{"num":14,"title":"第14章 顺路","file":"chapters/ch014.mp3","dur":653.3,"size_mb":5,"segs":[{"s":0,"e":8.53,"t":"时间：2 月 20 日—21 日 · 高一下"},{"s":8.98,"e":18.58,"t":"周五晚自习结束后，我收拾书包的时候，他在门口站了一下。"},{"s":19.02,"e":26.13,"t":"不是等我——他站在门口，低头看手机。"},{"s":26.58,"e":33.69,"t":"我背上书包走过去的时候，他刚好抬起头。"},{"s":34.13,"e":42.31,"t":"然后他什么也没说，转身往楼梯的方向走了。"},{"s":42.76,"e":54.13,"t":"我跟在后面——不是刻意的，是因为回宿舍就这一条路。"},{"s":54.58,"e":62.04,"t":"走了大概十步之后，我发现他走得不快。"},{"s":62.49,"e":71.73,"t":"不是平时那种步子——是比我正常速度慢一点点的节奏。"},{"s":72.18,"e":78.58,"t":"我本能地放慢了脚步，跟上他的节奏。"},{"s":79.02,"e":91.11,"t":"就这样——他走在前面，我跟在后面，中间隔了大概两米。谁都没说话。"},{"s":91.56,"e":102.22,"t":"走到一楼拐角的时候，他往旁边侧了一下身，让我走到他旁边。"},{"s":102.67,"e":106.22,"t":"\"你明天早上要出去？\""},{"s":106.67,"e":108.09,"t":"他问。"},{"s":108.53,"e":109.96,"t":"\"……什么？\""},{"s":110.4,"e":115.02,"t":"\"我看你周五晚上都在学校。\""},{"s":115.47,"e":123.29,"t":"\"哦——对，我家有点远，周末一般待学校。\""},{"s":123.73,"e":126.22,"t":"他点了点头。"},{"s":126.67,"e":129.51,"t":"\"我也是。\""},{"s":129.96,"e":133.16,"t":"然后他没再说话了。"},{"s":133.6,"e":145.69,"t":"但我们从那栋楼走到宿舍楼的那段路——大概 200 米——是并排走的。"},{"s":146.13,"e":156.8,"t":"路灯把两个人的影子投在地上，一个偏左，一个偏右。"},{"s":157.25,"e":165.07,"t":"到宿舍楼下的时候，他推开门，侧了一下身。"},{"s":165.51,"e":169.78,"t":"等我进去了，他才跟上来。"},{"s":170.22,"e":173.07,"t":"那个动作很小。"},{"s":173.51,"e":176.36,"t":"但我注意到了。"},{"s":176.8,"e":182.13,"t":"第二天下午，我在食堂碰见了他。"},{"s":182.58,"e":197.51,"t":"不是碰见——是我正在排队，他从另一边走过来，看了一眼队伍，然后站到了我后面。"},{"s":197.96,"e":200.8,"t":"\"你也这个点吃饭？\""},{"s":201.25,"e":203.02,"t":"他问。"},{"s":203.47,"e":206.31,"t":"\"……对。你也是？\""},{"s":206.76,"e":212.8,"t":"\"嗯。中午吃太早了，下午饿。\""},{"s":213.25,"e":217.87,"t":"我们之间隔了一个人的距离。"},{"s":218.31,"e":225.07,"t":"队伍往前挪了一点，他也往前挪了一点。"},{"s":225.51,"e":243.29,"t":"中间还是隔了一个人的距离——但感觉和昨天走路的那个距离一样，不远不近，像一个已经被人量过的尺寸。"},{"s":243.73,"e":250.13,"t":"打到饭之后，我端着盘子找位子。"},{"s":250.58,"e":253.42,"t":"他跟在我后面。"},{"s":253.87,"e":261.69,"t":"我坐下来的时候——他坐到了我对面。"},{"s":262.13,"e":273.16,"t":"不是刻意选的位置——食堂的桌子，对面是空着的，他就坐下了。"},{"s":273.6,"e":286.05,"t":"但我抬头的时候，看见他把餐盘放下，拆开筷子，低头开始吃。"},{"s":286.49,"e":292.89,"t":"从头到尾没有问我\"我可以坐这里吗\"。"},{"s":293.33,"e":296.18,"t":"他就直接坐下了。"},{"s":296.62,"e":301.6,"t":"好像这件事已经不需要问了。"},{"s":302.05,"e":306.67,"t":"我低头吃饭，吃得比平时快。"},{"s":307.11,"e":320.27,"t":"不是因为饿——是因为我不知道和他在一张桌子上吃饭的时候应该说什么。"},{"s":320.71,"e":324.27,"t":"但他好像没有这个困扰。"},{"s":324.71,"e":343.2,"t":"他吃得很自然，偶尔夹一筷子菜，偶尔看一眼手机。吃到一半的时候，他把碗里的煎蛋夹起来，放到了我盘子里。"},{"s":343.65,"e":346.13,"t":"我愣住了。"},{"s":346.58,"e":348.71,"t":"\"你——\""},{"s":349.16,"e":352.36,"t":"\"我不喜欢吃煎蛋。\""},{"s":352.8,"e":355.29,"t":"他头也没抬。"},{"s":355.73,"e":357.87,"t":"\"那你为什么打？\""},{"s":358.31,"e":370.4,"t":"\"食堂阿姨给的。她说'不要煎蛋啊？'我说'要吧'。\""},{"s":370.85,"e":373.33,"t":"\"……那你可以不拿。\""},{"s":373.78,"e":375.91,"t":"\"已经打了。\""},{"s":376.36,"e":378.49,"t":"他顿了顿。"},{"s":378.93,"e":381.78,"t":"\"你帮我吃了就行。\""},{"s":382.22,"e":395.73,"t":"我看着盘子里那个金黄色的煎蛋，蛋白的边缘煎得有点焦，是他盘子里过来的。"},{"s":396.18,"e":400.8,"t":"我用筷子夹起来，咬了一口。"},{"s":401.25,"e":405.16,"t":"和普通煎蛋一个味道。"},{"s":405.6,"e":413.78,"t":"但不知道为什么——我觉得它挺好吃的。"},{"s":414.22,"e":420.98,"t":"吃完饭后我们沿着操场走了半圈。"},{"s":421.42,"e":431.38,"t":"不是散步——是回宿舍的路刚好从操场边上经过。"},{"s":431.82,"e":452.8,"t":"走到操场中间那段的时候，路边有一盏路灯在闪，一亮一灭，一亮一灭。光落在他的侧脸上，忽明忽暗的。"},{"s":453.25,"e":459.29,"t":"走到看台附近的时候，他忽然开口了。"},{"s":459.74,"e":466.14,"t":"\"你昨天那本错题本——你看完了？\""},{"s":466.58,"e":469.07,"t":"\"看完了。\""},{"s":469.51,"e":471.65,"t":"\"有不懂的吗？\""},{"s":472.09,"e":480.27,"t":"\"有一道——你画图的那题，第三问我没太懂。\""},{"s":480.71,"e":483.2,"t":"他点了点头。"},{"s":483.65,"e":487.2,"t":"\"晚上回去讲给你听。\""},{"s":487.65,"e":494.76,"t":"他说\"晚上回去\"——他说的是\"回去\"。"},{"s":495.2,"e":501.96,"t":"好像那个房间，已经默认是我们的房间了。"},{"s":502.4,"e":510.94,"t":"晚上他到宿舍之后，第一件事就是坐到书桌前。"},{"s":511.38,"e":513.87,"t":"\"把你那题拿出来。\""},{"s":514.31,"e":522.14,"t":"他从抽屉里抽出一张草稿纸，把笔帽咬开。"},{"s":522.58,"e":530.4,"t":"我坐到他旁边——隔了大概一个拳头的距离。"},{"s":530.85,"e":534.76,"t":"他开始在纸上画图。"},{"s":535.2,"e":546.94,"t":"画到第三步的时候，他的手指点在某一条辅助线上——停住了。"},{"s":547.38,"e":552,"t":"\"这里——我当时也卡了很久。\""},{"s":552.45,"e":569.16,"t":"他的手指按在纸上，指甲修剪得很干净。拇指按着纸面，食指沿着那条线划了一下。"},{"s":569.6,"e":575.29,"t":"\"你从这个角连过去——能看到什么？\""},{"s":575.74,"e":580.71,"t":"我盯着那张图看了大概五秒。"},{"s":581.16,"e":584.71,"t":"\"……一个直角三角形？\""},{"s":585.16,"e":596.89,"t":"\"对。\"他没有抬头，但声音里带着一点\"对了\"的那种轻快。\"然后呢？\""},{"s":597.34,"e":602.31,"t":"\"然后——用勾股？\""},{"s":602.76,"e":604.89,"t":"\"对。\""},{"s":605.34,"e":614.58,"t":"他放下笔，往后靠了一点，让我自己把剩下的写完。"},{"s":615.02,"e":623.2,"t":"我写完最后一个等号的时候，答案确实是对的。"},{"s":623.65,"e":625.78,"t":"\"懂了？\""},{"s":626.22,"e":628.36,"t":"\"懂了。\""},{"s":628.8,"e":633.78,"t":"他点了下头，把笔帽盖回去。"},{"s":634.22,"e":639.91,"t":"然后把那张草稿纸对折，递给我。"},{"s":640.36,"e":645.69,"t":"\"留着。下次再看就不会忘了。\""},{"s":646.14,"e":647.91,"t":"我接过来。"},{"s":648.36,"e":653.34,"t":"那张纸还带着他手指的温度。"}]},{"num":15,"title":"第15章 甜的","file":"chapters/ch015.mp3","dur":733.8,"size_mb":5.6,"segs":[{"s":0,"e":13.43,"t":"时间：2 月 22 日 · 高一下"},{"s":14.27,"e":47.83,"t":"换座位了。按成绩排的——我 187 名，坐第 12 行附近。离他的距离从 80 厘米变成了 4 米。"},{"s":48.67,"e":74.18,"t":"我到新座位坐下的时候，看了一眼他的方向——他坐在第 6 行靠窗，没有回头看我。"},{"s":75.02,"e":90.46,"t":"但早自习开始之前，一杯豆浆出现在我的桌角。"},{"s":91.3,"e":96,"t":"温的。"},{"s":96.83,"e":114.96,"t":"我抬起头——他已经坐回自己的位置了，低着头在翻书。"},{"s":115.8,"e":129.22,"t":"我握着那杯豆浆，手心被烫得发热。"},{"s":130.06,"e":136.78,"t":"他记得我喜欢甜的。"},{"s":137.62,"e":155.74,"t":"中午在食堂，吃完饭后我和他碰见了生物老师张老师。"},{"s":156.58,"e":180.75,"t":"张老师认识他——他是生物课代表。看见我们走在一起，张老师笑了一下。"},{"s":181.59,"e":190.98,"t":"\"博文，这次生物考得不错啊。\""},{"s":191.82,"e":195.85,"t":"\"还行。\""},{"s":196.69,"e":212.13,"t":"\"97 分还不叫不错？你打算多少才算好？\""},{"s":212.97,"e":218.34,"t":"\"100。\""},{"s":219.18,"e":235.29,"t":"张老师笑了——不是被顶撞的那种笑，是欣赏的。"},{"s":236.13,"e":273.72,"t":"我也在旁边跟着松了一口气。他和老师说话的方式——不卑不亢，没有讨好，没有紧张——让我觉得他就是这样的人。"},{"s":274.56,"e":288.66,"t":"他不需要在任何人面前变成另一种样子。"},{"s":289.5,"e":299.57,"t":"张老师走了之后，他转过来看我。"},{"s":300.4,"e":305.77,"t":"\"你这次生物多少？\""},{"s":306.61,"e":309.97,"t":"\"……82。\""},{"s":310.81,"e":319.54,"t":"\"那下周一中午，来我座位。\""},{"s":320.38,"e":325.07,"t":"\"干什么？\""},{"s":325.91,"e":328.6,"t":"\"教你。\""},{"s":329.44,"e":334.81,"t":"他说完就走了。"},{"s":335.65,"e":343.7,"t":"我站在原地，愣了一下。"},{"s":344.54,"e":360.65,"t":"他说的不是\"帮你看看\"——他说的是\"教你\"。"},{"s":361.49,"e":375.59,"t":"下午历史课结束的时候，我正在收拾课本。"},{"s":376.43,"e":380.46,"t":"他走过来。"},{"s":381.3,"e":385.99,"t":"\"明天一起走。\""},{"s":386.83,"e":390.19,"t":"\"……去哪？\""},{"s":391.03,"e":402.44,"t":"\"我今天要去生物实验室。你跟我一起。\""},{"s":403.28,"e":411.34,"t":"他说完没等我回答，就走了。"},{"s":412.17,"e":423.59,"t":"我坐在座位上，看着他走出去的背影。"},{"s":424.43,"e":439.19,"t":"明天一起走——他没有问我愿不愿意。"},{"s":440.03,"e":447.42,"t":"但我知道他为什么不问。"},{"s":448.26,"e":457.66,"t":"因为我已经开始期待明天了。"},{"s":458.49,"e":484,"t":"晚自习的时候，周海坐在我旁边，看了一眼我桌上那杯已经喝完的空豆浆杯。"},{"s":484.84,"e":488.2,"t":"\"他买的？\""},{"s":489.04,"e":493.74,"t":"\"……嗯。\""},{"s":494.58,"e":499.28,"t":"\"每天都买？\""},{"s":500.11,"e":504.14,"t":"\"不是每天。\""},{"s":504.98,"e":511.69,"t":"\"那今天是第几次？\""},{"s":512.53,"e":516.56,"t":"我想了一下。"},{"s":517.4,"e":521.43,"t":"\"……第二次。\""},{"s":522.27,"e":527.64,"t":"周海沉默了一下。"},{"s":528.48,"e":533.18,"t":"\"林深。\""},{"s":534.01,"e":537.37,"t":"\"嗯？\""},{"s":538.21,"e":552.31,"t":"\"你有没有想过——他可能也喜欢你？\""},{"s":553.15,"e":563.22,"t":"我握着那个空杯子的手指停住了。"},{"s":564.06,"e":568.08,"t":"\"……他不可能。\""},{"s":568.92,"e":573.62,"t":"\"为什么？\""},{"s":574.46,"e":579.83,"t":"\"因为——\""},{"s":580.67,"e":584.7,"t":"我停住了。"},{"s":585.54,"e":605,"t":"因为什么？因为我配不上他？因为他那么亮而我那么普通？"},{"s":605.84,"e":614.57,"t":"因为我不知道他喜欢我什么？"},{"s":615.41,"e":620.78,"t":"我说不出来。"},{"s":621.62,"e":631.02,"t":"周海看了我一眼，没有再问。"},{"s":631.86,"e":640.58,"t":"但他走之前，说了一句话："},{"s":641.42,"e":654.18,"t":"\"你等他主动找你。比你主动找他有用。\""},{"s":655.02,"e":669.11,"t":"那天晚上，我躺在床上，看着天花板。"},{"s":669.95,"e":686.73,"t":"等他主动找我——他今天已经主动了两次了。"},{"s":687.57,"e":694.96,"t":"豆浆。教我生物。"},{"s":695.8,"e":700.5,"t":"明天一起走。"},{"s":701.34,"e":706.71,"t":"——这算不算主动？"},{"s":707.54,"e":712.24,"t":"我不知道。"},{"s":713.08,"e":733.89,"t":"但那个空豆浆杯，我一直没扔。放在书桌的角落里，放了三天。"}]},{"num":16,"title":"第16章 搭档","file":"chapters/ch016.mp3","dur":565.1,"size_mb":4.3,"segs":[{"s":0,"e":8.76,"t":"时间：2 月 23 日—25 日 · 高一下"},{"s":9.22,"e":19.07,"t":"换座位之后，我和他的距离从 80 厘米变成了 4 米。"},{"s":19.53,"e":22.81,"t":"但有些事情没变。"},{"s":23.27,"e":33.12,"t":"每天早上我走到教室的时候，我桌上会放着一杯豆浆。"},{"s":33.58,"e":55.12,"t":"第一次发现的时候，我还以为是别人放错了——塑料杯，封着盖子，还是温的。我拿起来看了看，杯子上没有任何标记。"},{"s":55.57,"e":60.32,"t":"我回头看了一眼他的位置。"},{"s":60.77,"e":76.1,"t":"他坐在第 6 行靠窗，已经在了。低着头在看书，桌角放着一杯一模一样的豆浆。"},{"s":76.56,"e":82.77,"t":"我握着那杯豆浆，手心被烫得发热。"},{"s":83.22,"e":85.78,"t":"他什么时候买的？"},{"s":86.23,"e":89.88,"t":"他怎麼知道我喝甜的？"},{"s":90.34,"e":93.99,"t":"他为什么要多买一杯？"},{"s":94.45,"e":113.79,"t":"我想问他，但又不知道怎么开口——总不能拿着豆浆走过去说\"你是不是给我买的\"，万一他说\"不是\"呢？"},{"s":114.25,"e":129.94,"t":"但我坐下来的时候，他刚好回过头来看了一眼——扫过我桌上的杯子，然后收回去了。"},{"s":130.4,"e":132.59,"t":"就一眼。"},{"s":133.05,"e":139.25,"t":"但那个眼神的意思是：你拿到了。"},{"s":139.71,"e":142.99,"t":"后来我观察了一下。"},{"s":143.45,"e":164.62,"t":"他每天早上大概 7 点 10 分到教室，先去食堂。回来的时候左手一杯豆浆，右手一杯豆浆——都是甜的。"},{"s":165.08,"e":174.93,"t":"他把自己那杯放桌角，然后把另一杯放在我桌上。"},{"s":175.39,"e":187.8,"t":"整个过程从不超过 3 秒。动作熟练得好像已经做了一百次。"},{"s":188.25,"e":193.73,"t":"第三天早上我终于开口了。"},{"s":194.19,"e":196.01,"t":"\"博文。\""},{"s":196.47,"e":198.29,"t":"\"嗯？\""},{"s":198.75,"e":202.76,"t":"\"豆浆——你买的？\""},{"s":203.22,"e":205.41,"t":"他头也没抬。"},{"s":205.87,"e":208.79,"t":"\"顺手。\""},{"s":209.24,"e":213.26,"t":"\"……怎么会顺手就多买一杯？\""},{"s":213.71,"e":217.73,"t":"他翻书的手停了一下。"},{"s":218.19,"e":224.39,"t":"然后他说：\"因为知道你要喝。\""},{"s":224.85,"e":230.69,"t":"语气平得像在说\"今天是周二\"。"},{"s":231.14,"e":238.08,"t":"我握著那杯豆浆，一句话都说不出来。"},{"s":238.53,"e":242.18,"t":"他知道我要喝。"},{"s":242.64,"e":244.47,"t":"他买了。"},{"s":244.92,"e":247.48,"t":"每天都买。"},{"s":247.93,"e":253.04,"t":"周海大概是第一个注意到的。"},{"s":253.5,"e":269.93,"t":"周五早上，他看着我桌上的豆浆，又看了一眼博文桌上的豆浆，然后把目光移到我脸上。"},{"s":270.38,"e":272.21,"t":"\"他买的？\""},{"s":272.66,"e":274.85,"t":"\"……嗯。\""},{"s":275.31,"e":277.13,"t":"\"每天？\""},{"s":277.59,"e":280.15,"t":"\"……嗯。\""},{"s":280.6,"e":283.89,"t":"周海沉默了一会儿。"},{"s":284.34,"e":290.55,"t":"然后他说：\"你们俩现在是什么组合？\""},{"s":291,"e":294.65,"t":"\"什么什么组合？\""},{"s":295.11,"e":313,"t":"\"就是——你们是不是已经是固定搭档了？早上一起来，中午一起吃饭，晚自习回宿舍也一起走。\""},{"s":313.45,"e":328.42,"t":"我愣了一下，想说\"没有\"——但仔细一想，好像确实是这样。"},{"s":328.87,"e":362.82,"t":"每天早上他带豆浆。中午有时候一起吃食堂，有时候不吃，但下午 4 点半他会在座位等我。晚自习结束后我们会一起走回宿舍——不用约，收拾书包站起来，他在门口，我跟上去。"},{"s":363.28,"e":365.83,"t":"没有人约定过。"},{"s":366.29,"e":370.3,"t":"但就是变成了这样。"},{"s":370.76,"e":374.41,"t":"\"——不知道。\"我说。"},{"s":374.87,"e":379.61,"t":"周海看了我一眼，没再问了。"},{"s":380.07,"e":387.73,"t":"但他笑了一下——那种\"你心里有数\"的笑。"},{"s":388.19,"e":403.15,"t":"周六下午没有课。我在宿舍看书，他坐在对面床，盘着腿，戴着一只耳机。"},{"s":403.61,"e":421.13,"t":"房间里很安静。窗外的阳光在地板上画了一块斜斜的亮斑，灰尘在光柱里慢慢飘。"},{"s":421.59,"e":428.52,"t":"我翻了一页书的时候，听见他换了一首歌。"},{"s":428.98,"e":434.09,"t":"然后他把另一只耳机递了过来。"},{"s":434.55,"e":436.74,"t":"\"听吗？\""},{"s":437.19,"e":439.02,"t":"我接过来。"},{"s":439.47,"e":443.85,"t":"耳机线上还带着他的温度。"},{"s":444.31,"e":450.51,"t":"我坐到床沿上，把耳机塞进耳朵里。"},{"s":450.97,"e":477.25,"t":"是一首英文歌。吉他前奏，男声很轻，唱到副歌的时候鼓点才进来。我听不太懂歌词，但旋律让那个下午的光线变得更慢了一些。"},{"s":477.71,"e":496.32,"t":"他也没说话。我们就这样面对面坐着——隔了大概一米——各自看着自己的手机，共享同一首歌。"},{"s":496.78,"e":500.43,"t":"耳机线不长。"},{"s":500.89,"e":509.28,"t":"所以我们之间的距离，被那根白色的线固定住了。"},{"s":509.74,"e":511.93,"t":"不算近。"},{"s":512.38,"e":514.94,"t":"但也不算远。"},{"s":515.39,"e":526.35,"t":"晚上我想了很久一个问题——我们这样算什么。"},{"s":526.8,"e":528.99,"t":"朋友？"},{"s":529.45,"e":532.73,"t":"比朋友近一点？"},{"s":533.19,"e":535.74,"t":"还是我想多了？"},{"s":536.2,"e":538.76,"t":"我找不到答案。"},{"s":539.21,"e":554.18,"t":"但第二天早上我看见桌上那杯热豆浆的时候——我想，算了，不找了。"},{"s":554.63,"e":557.19,"t":"管它算什么。"},{"s":557.64,"e":562.76,"t":"反正每天早上都有一杯甜的。"},{"s":563.21,"e":565.04,"t":"这样就够了。"}]},{"num":17,"title":"第17章 80 厘米的亮","file":"chapters/ch017.mp3","dur":518.3,"size_mb":4,"segs":[{"s":0,"e":9.87,"t":"时间：2 月 26 日 · 高一下"},{"s":10.64,"e":18.05,"t":"周一中午我去他座位了。"},{"s":18.82,"e":51.52,"t":"他已经把桌子收拾好了——书推到左上角，笔记本翻开到空白页，桌面上清出了一块属于我的位置。"},{"s":52.29,"e":69.56,"t":"他让我坐在他旁边，然后他拿起笔，开始画图。"},{"s":70.34,"e":106.12,"t":"两个圆——一个大一个小——画在一起。光反应，暗反应。他一边画一边讲，从类囊体薄膜讲到卡尔文循环。"},{"s":106.89,"e":117.38,"t":"我坐在他旁边，距离大概 80 厘米。"},{"s":118.15,"e":150.23,"t":"他低头画图的时候，会先画一个圈，然后在圈里标字。标完之后他会抬起头看我一眼——确认我听懂了没有。"},{"s":151.01,"e":167.66,"t":"然后他抬头的那一瞬间——我看见了他眼睛里的东西。"},{"s":168.44,"e":211.01,"t":"不是瞳孔。不是睫毛。是光——从窗户外面照进来的阳光，落在他的眼睛里面，让他的整个虹膜看起来像在发光。"},{"s":211.78,"e":237.07,"t":"不是亮的——是亮的。80 厘米的距离，我甚至能看见那团光里反射出来的我。"},{"s":237.85,"e":246.48,"t":"我的脸。在他眼睛里。"},{"s":247.26,"e":260.83,"t":"我低下头，假装在看那个光合作用的图。"},{"s":261.6,"e":280.73,"t":"但我记住了那个画面——他的眼睛里有光，光里有我。"},{"s":281.5,"e":286.43,"t":"下午历史课。"},{"s":287.2,"e":317.44,"t":"上课到一半的时候，我走神了——我在草稿纸上画了一个圆圈，然后在里面标了\"光反应\"三个字。"},{"s":318.21,"e":325.61,"t":"然后我听到了一声轻响。"},{"s":326.38,"e":335.02,"t":"我抬头——他回头了。"},{"s":335.79,"e":349.98,"t":"不是侧头——是整个人往右转了一下，看了我一眼。"},{"s":350.75,"e":371.11,"t":"然后他笑了一下——不是嘴角动，是真的笑——眼睛底下那一块皱了一下。"},{"s":371.89,"e":376.82,"t":"不到 1 厘米的皱。"},{"s":377.59,"e":383.15,"t":"然后他转回去了。"},{"s":383.92,"e":406.74,"t":"我捏着笔，在草稿纸上的\"光反应\"旁边画了一个歪歪扭扭的箭头。"},{"s":407.52,"e":413.07,"t":"指向他的方向。"},{"s":413.84,"e":422.48,"t":"晚自习的时候，周海凑过来。"},{"s":423.25,"e":431.89,"t":"\"他今天历史课回头对你笑了。\""},{"s":432.66,"e":436.36,"t":"\"……嗯。\""},{"s":437.13,"e":443.92,"t":"\"你知道这意味着什么吗？\""},{"s":444.69,"e":447.16,"t":"\"……什么？\""},{"s":447.93,"e":451.63,"t":"\"他在看你。\""},{"s":452.4,"e":455.49,"t":"周海说。"},{"s":456.26,"e":467.98,"t":"\"上课的时候不看黑板——回头看你。\""},{"s":468.75,"e":471.84,"t":"我没回答。"},{"s":472.61,"e":476.93,"t":"但我知道。"},{"s":477.7,"e":486.34,"t":"我看见了——他眼睛底下的皱。"},{"s":487.11,"e":496.36,"t":"不是 5 米外的玻璃反光里看到的。"},{"s":497.13,"e":510.71,"t":"是 80 厘米外、能看清他每一根睫毛的距离。"},{"s":511.48,"e":518.26,"t":"他回头看我，然后笑了。"}]},{"num":18,"title":"第18章 三十厘米","file":"chapters/ch018.mp3","dur":643.1,"size_mb":4.9,"segs":[{"s":0,"e":11.36,"t":"时间：2 月 27 日—28 日 · 高一下"},{"s":11.95,"e":15.74,"t":"我发现了一件事。"},{"s":16.33,"e":32.42,"t":"不知道从什么时候开始——我和他之间的距离，已经不需要我刻意去量了。"},{"s":33.01,"e":66.62,"t":"以前我算得很清楚：隔着天井的时候是 5 米，坐在他后面的时候是 80 厘米，换座位之后变成 4 米，绕操场散步的时候大概 50 厘米。"},{"s":67.21,"e":101.29,"t":"但现在我在宿舍里，坐在他床上，背靠着墙，他坐在我旁边，把我做错的物理卷子摊在两个人中间——我们的肩膀之间大概隔了 30 厘米。"},{"s":101.88,"e":106.14,"t":"不是刻意拉近的。"},{"s":106.73,"e":113.36,"t":"是自然而然变成这样的。"},{"s":113.95,"e":117.74,"t":"起因是这样的。"},{"s":118.33,"e":151.94,"t":"周日晚上的物理作业有一道大题，我做了三遍都跟答案对不上。我坐在书桌前咬着笔帽盯着草稿纸，盯了快十分钟，还是一点头绪都没有。"},{"s":152.53,"e":155.37,"t":"\"哪题？\""},{"s":155.96,"e":161.17,"t":"他的声音从背后传来。"},{"s":161.76,"e":177.38,"t":"我回头——他坐在床上，手里拿着一本书，大概是看我坐那儿太久了。"},{"s":177.97,"e":181.76,"t":"\"最后一道。\""},{"s":182.35,"e":188.97,"t":"他放下书，站起来，走过来。"},{"s":189.57,"e":200.93,"t":"他没有坐回自己的书桌——他直接坐到了我旁边。"},{"s":201.52,"e":204.36,"t":"我的床。"},{"s":204.95,"e":207.79,"t":"他坐下来了。"},{"s":208.38,"e":235.36,"t":"我往旁边挪了一点，给他腾位置。他坐下来的时候，床垫往下陷了一点——他往我这边偏了一下，肩膀碰到了我的肩膀。"},{"s":235.95,"e":239.26,"t":"\"这题？\""},{"s":239.86,"e":259.74,"t":"他把卷子拿起来，低头看题。好像碰到我的肩膀这件事，在他那里没有任何值得注意的。"},{"s":260.33,"e":265.53,"t":"但我僵了大概两秒。"},{"s":266.13,"e":273.7,"t":"然后我才想起回答：\"……对。\""},{"s":274.29,"e":304.58,"t":"他开始在草稿上演算。写的步骤不多，每一步之间停一下，像是在确认思路没有跑偏。他的手指按在纸面上，指节微微发白。"},{"s":305.17,"e":312.75,"t":"写到第三步的时候，他停了一下。"},{"s":313.34,"e":315.71,"t":"\"你卡在哪？\""},{"s":316.3,"e":325.76,"t":"\"——第二问。我算出 h 但到不了 \\Delta t。\""},{"s":326.36,"e":330.14,"t":"\"你 h 用的什么公式？\""},{"s":330.73,"e":340.67,"t":"\"自由落体——h=½gt²。\""},{"s":341.27,"e":346.94,"t":"\"那到了 \\Delta t 要换什么？\""},{"s":347.54,"e":350.85,"t":"\"……能量？\""},{"s":351.44,"e":354.28,"t":"\"对。\""},{"s":354.87,"e":370.49,"t":"他侧过脸来看我——那个距离近到我甚至能看清他睫毛的弧度。"},{"s":371.08,"e":380.08,"t":"然后他又转回去了，在纸上补了两行。"},{"s":380.67,"e":387.77,"t":"\"用能量守恒大思路就顺了。\""},{"s":388.36,"e":397.83,"t":"他放下笔，往后靠了一点，把空间让给我。"},{"s":398.42,"e":422.08,"t":"我低头看那张纸——他的字写得很清楚，每一步都在旁边标了根据。最后一行是答案，画了一个圈。"},{"s":422.68,"e":432.62,"t":"我拿起笔，顺着他的思路重新写了一遍。"},{"s":433.21,"e":438.41,"t":"这次一次就对了。"},{"s":439.01,"e":445.63,"t":"\""},{"s":446.22,"e":448.59,"t":"懂了？\""},{"s":449.18,"e":452.5,"t":"\"懂了。\""},{"s":453.09,"e":458.29,"t":"他点了点头，站起来。"},{"s":458.89,"e":471.67,"t":"从他坐到我旁边到站起来——整个过程大概 7 分钟。"},{"s":472.26,"e":483.14,"t":"但我记住了那 7 分钟里他肩膀贴着我的触感。"},{"s":483.73,"e":491.31,"t":"第二天中午，我在走廊上碰见他。"},{"s":491.9,"e":506.57,"t":"他从办公室出来，手里抱着一摞作业本。看见我的时候，他停了一下。"},{"s":507.16,"e":521.36,"t":"\"你昨天那道题——类似的还有一道，我放你桌上了。你下午做一下。\""},{"s":521.96,"e":524.32,"t":"\"……好。\""},{"s":524.91,"e":531.07,"t":"他走了两步，又停下来。"},{"s":531.66,"e":540.65,"t":"\"做完不用给我看。你自己知道对错就行。\""},{"s":541.24,"e":546.92,"t":"他说完就往前走远了。"},{"s":547.51,"e":554.14,"t":"我站在走廊上，看着他的背影。"},{"s":554.73,"e":565.62,"t":"他放了一题在我桌上——不是老师布置的，是他找的。"},{"s":566.21,"e":569.52,"t":"特意找的。"},{"s":570.12,"e":586.21,"t":"晚自习的时候，我做完了他留的那道题，在答案旁边画了一个小小的勾。"},{"s":586.8,"e":591.53,"t":"其实他不在我旁边。"},{"s":592.13,"e":623.84,"t":"但我画那个勾的时候，脑子里想的是昨天晚上他坐在我旁边讲题的样子——他低头画图，手指点在某一条线上，他说\"这里\"。"},{"s":624.43,"e":632.48,"t":"我低头看卷子上自己写出来的答案。"},{"s":633.07,"e":643.01,"t":"30 厘米的距离，好像比我想象中更近一些。"}]},{"num":19,"title":"第19章 小深","file":"chapters/ch019.mp3","dur":624.8,"size_mb":4.8,"segs":[{"s":0,"e":8.17,"t":"时间：3 月下旬 · 高一下"},{"s":8.77,"e":16.46,"t":"选科的通知是三月中旬下来的。"},{"s":17.06,"e":27.64,"t":"一张表，每人一份，要在周五之前交上去。"},{"s":28.24,"e":44.1,"t":"\"物理、化学、生物\"——我在那三个格子前面站了很久。"},{"s":44.7,"e":48.55,"t":"不是犹豫。"},{"s":49.15,"e":53.47,"t":"是太确定了。"},{"s":54.07,"e":58.88,"t":"确定得有点心虚。"},{"s":59.48,"e":83.51,"t":"因为我知道他会选什么——他上学期说过他喜欢物理和生物。所以\"物化生\"对我来说根本不需要考虑。"},{"s":84.11,"e":88.44,"t":"不是因为我喜欢。"},{"s":89.04,"e":93.37,"t":"是因为他要选。"},{"s":93.97,"e":105.5,"t":"交表之前的那天晚上，我在宿舍对着那张纸发呆。"},{"s":106.1,"e":125.33,"t":"他洗完澡进来，头发还是湿的，用毛巾搭在头上擦了两下，看了一眼我手里的表。"},{"s":125.93,"e":128.81,"t":"\"你还没交？\""},{"s":129.41,"e":132.78,"t":"\"……在想。\""},{"s":133.38,"e":140.11,"t":"他坐下来，把毛巾挂到椅背上。"},{"s":140.71,"e":143.59,"t":"\"你想选什么？\""},{"s":144.19,"e":146.12,"t":"\"不知道。\""},{"s":146.72,"e":166.91,"t":"这句话是假的。我知道——我早就知道。我只是不想让他觉得我是因为他才选的。"},{"s":167.51,"e":171.83,"t":"但他看了我一眼。"},{"s":172.43,"e":186.85,"t":"然后他说了一句话——语气很随意，像在说一件没什么大不了的事："},{"s":187.45,"e":191.3,"t":"\"我选物化生。\""},{"s":191.9,"e":198.15,"t":"我握着笔的手指紧了一下。"},{"s":198.75,"e":201.63,"t":"\"……哦。\""},{"s":202.23,"e":204.64,"t":"\"你呢？\""},{"s":205.24,"e":209.56,"t":"我低头看那张表。"},{"s":210.16,"e":225.54,"t":"然后我在\"物理\"\"化学\"\"生物\"三个格子前面，各打了一个勾。"},{"s":226.15,"e":229.51,"t":"\"我也选这个。\""},{"s":230.11,"e":244.53,"t":"他看了一眼我的表，没有说\"你也选这个啊\"或者\"好巧\"。"},{"s":245.13,"e":249.46,"t":"他只是点了点头。"},{"s":250.06,"e":264,"t":"然后把他的表也拿了出来——三个勾，和我的一模一样。"},{"s":264.6,"e":268.44,"t":"\"以后课表一样了。\""},{"s":269.04,"e":271.93,"t":"他说。"},{"s":272.53,"e":277.33,"t":"语气还是那么平。"},{"s":277.94,"e":289.95,"t":"但我注意到——他说完之后，嘴角往上翘了一点。"},{"s":290.55,"e":302.57,"t":"选科表交上去之后，班主任在班会上念了统计结果。"},{"s":303.17,"e":309.9,"t":"\"物化生——27 人。\""},{"s":310.5,"e":324.44,"t":"我坐在座位上，听到这个数字的时候，心里悄悄松了一口气。"},{"s":325.04,"e":341.86,"t":"全班 45 个人，选了物化生的是大多数。我和他都在那 27 个人里面。"},{"s":342.46,"e":352.08,"t":"下个学期——我们还在同一个班。"},{"s":352.68,"e":368.54,"t":"不，不止——同一个教室、同一张课表、同一间实验室。"},{"s":369.14,"e":372.5,"t":"同一个方向。"},{"s":373.1,"e":381.28,"t":"这个认知让我在座位上坐了很久。"},{"s":381.88,"e":389.57,"t":"周海在旁边看了一眼我的表情。"},{"s":390.17,"e":394.97,"t":"\"你怎么笑得那么傻？\""},{"s":395.57,"e":398.94,"t":"\"我没有。\""},{"s":399.54,"e":408.67,"t":"\"你脸上写着：'我和他选了同一个组合'。\""},{"s":409.27,"e":415.04,"t":"我把脸转到窗外。"},{"s":415.64,"e":430.06,"t":"窗外的阳光很亮——三月底的春天，风已经有了暖意。"},{"s":430.66,"e":434.03,"t":"我确实在笑。"},{"s":434.63,"e":439.43,"t":"但我没让周海看见。"},{"s":440.03,"e":444.84,"t":"周五晚上，宿舍。"},{"s":445.44,"e":457.94,"t":"我坐在床上看书。他从外面进来，顺手关上门。"},{"s":458.54,"e":462.87,"t":"然后他叫了我一声。"},{"s":463.47,"e":465.39,"t":"\"小深。\""},{"s":465.99,"e":468.87,"t":"我抬起头。"},{"s":469.47,"e":472.84,"t":"\"……你叫我什么？\""},{"s":473.44,"e":484.98,"t":"\"小深。\"他又说了一遍，语气很自然。\"怎么了？\""},{"s":485.58,"e":489.42,"t":"\"没——没怎么。\""},{"s":490.02,"e":497.23,"t":"我低下头，假装继续看书。"},{"s":497.83,"e":508.89,"t":"但我的手指捏着书页的边缘，捏出了一道印子。"},{"s":509.49,"e":513.81,"t":"他叫我\"小深\"。"},{"s":514.41,"e":521.62,"t":"不是林深——是\"小深\"。"},{"s":522.23,"e":529.44,"t":"这个世界上只有他这么叫我。"},{"s":530.04,"e":532.92,"t":"\"小深。\""},{"s":533.52,"e":541.21,"t":"熄灯之后，他在黑暗里又叫了一声。"},{"s":541.81,"e":543.73,"t":"\"嗯？\""},{"s":544.34,"e":550.1,"t":"\"你为什么会选物化生？\""},{"s":550.7,"e":559.36,"t":"黑暗中，他的声音比平时轻一些。"},{"s":559.96,"e":563.8,"t":"我沉默了一会儿。"},{"s":564.4,"e":571.13,"t":"\"因为——我想跟你同一个班。\""},{"s":571.73,"e":588.55,"t":"这句话说出口之后，我立刻就后悔了。太直白了。太——"},{"s":589.16,"e":597.33,"t":"但黑暗里传来一个很轻的声音。"},{"s":597.93,"e":602.25,"t":"像是笑了一下。"},{"s":602.85,"e":608.14,"t":"然后他说：\"我知道。\""},{"s":608.74,"e":617.39,"t":"那两个字——很轻，很短。"},{"s":617.99,"e":624.72,"t":"但让我一整夜都没睡着。"}]},{"num":20,"title":"第20章 开学","file":"chapters/ch020.mp3","dur":513.2,"size_mb":3.9,"segs":[{"s":0,"e":23.39,"t":"时间：9 月 8 日 · 高二上开学第一天"},{"s":24.85,"e":50.59,"t":"高二开学那天，我走进教室的时候，他已经在了。"},{"s":52.05,"e":156.15,"t":"他坐在倒数第三排靠窗——和上学期差不多的位置。我习惯性地往他后面走——然后发现自己已经不需要坐他后面了。我们选了同一个组合，同一间教室，连桌子都是同一排。"},{"s":157.61,"e":173.98,"t":"我走到他旁边的位置坐下来。"},{"s":175.45,"e":190.65,"t":"他把一瓶水推到我桌上。"},{"s":192.11,"e":200.3,"t":"\"给你的。\""},{"s":201.76,"e":211.12,"t":"\"……你自己带的？\""},{"s":212.58,"e":223.11,"t":"\"嗯。带了两瓶。\""},{"s":224.57,"e":259.66,"t":"我拿起那瓶水——瓶身是凉的，应该是他早上从宿舍带出来的。"},{"s":261.12,"e":279.84,"t":"他桌角放着另一瓶，一模一样的。"},{"s":281.3,"e":300.01,"t":"从高一下开始，他给我带豆浆。"},{"s":301.47,"e":320.19,"t":"高二上开学第一天，他给我带水。"},{"s":321.65,"e":347.38,"t":"我拧开盖子喝了一口——普通的凉白开。"},{"s":348.84,"e":366.39,"t":"但我觉得它比任何饮料都甜。"},{"s":367.85,"e":392.41,"t":"那天下午，他路过我座位的时候，停了一下。"},{"s":393.88,"e":407.91,"t":"\"以后每天下午 4 点半——\""},{"s":409.37,"e":417.56,"t":"他顿了顿。"},{"s":419.02,"e":441.25,"t":"\"——你来找我。我把我的物理笔记给你看。\""},{"s":442.71,"e":449.73,"t":"我抬头看他。"},{"s":451.19,"e":459.37,"t":"\"每天？\""},{"s":460.84,"e":469.02,"t":"\"每天。\""},{"s":470.49,"e":499.73,"t":"他说的不是\"有空的时候\"或者\"你有问题的时候\"。"},{"s":501.19,"e":512.89,"t":"他说的是\"每天\"。"}]},{"num":21,"title":"第21章 同一组","file":"chapters/ch021.mp3","dur":747.2,"size_mb":5.7,"segs":[{"s":0,"e":9.02,"t":"时间：9 月中旬 · 高二上"},{"s":9.78,"e":24.22,"t":"高二开学的第二周，生物课上，老师说了一句话："},{"s":24.97,"e":35.8,"t":"\"下节课实验，两人一组。自己找搭档。\""},{"s":36.55,"e":50.99,"t":"教室里安静了一秒，然后开始嗡嗡地响起来。"},{"s":51.74,"e":72.8,"t":"我坐在座位上没动。不是因为我不想找人——是因为我还没想好怎么开口。"},{"s":73.55,"e":83.78,"t":"然后我听见前面的椅子响了一声。"},{"s":84.53,"e":88.14,"t":"他站了起来。"},{"s":88.89,"e":93.1,"t":"走到我桌边。"},{"s":93.86,"e":97.47,"t":"\"走。\""},{"s":98.22,"e":102.43,"t":"\"……去哪？\""},{"s":103.18,"e":110.4,"t":"\"实验室。趁他们还在分。\""},{"s":111.15,"e":135.22,"t":"他站在我桌旁，手插在校服口袋里，表情很平常——像\"去食堂\"一样的语气。"},{"s":135.97,"e":144.4,"t":"我以为他会等我说\"好\"。"},{"s":145.15,"e":158.99,"t":"但他没等。他说完之后就转身往门口走了。"},{"s":159.74,"e":165.75,"t":"我背上书包跟上去。"},{"s":166.51,"e":185.76,"t":"走到门口的时候，我听见后面有人喊了一句：\"博文你们一组啊？\""},{"s":186.51,"e":190.12,"t":"他没回头。"},{"s":190.87,"e":196.29,"t":"\"对，我们一组。\""},{"s":197.04,"e":224.11,"t":"实验室在实验楼的二楼。宽大的台面，每个台子上摆着一个显微镜和一盒载玻片。"},{"s":224.87,"e":230.88,"t":"我们选了靠窗的那一组。"},{"s":231.63,"e":275.55,"t":"他把实验服穿上——白色的，有点大，袖口往上卷了两圈。我低头穿上自己的实验服，余光看见他在扣扣子，从下往上，动作不快。"},{"s":276.31,"e":287.74,"t":"今天的实验是观察洋葱表皮细胞。"},{"s":288.49,"e":319.78,"t":"老师讲完步骤之后，我低头切洋葱。切了两刀，眼睛就开始发酸。我又切了一刀——眼泪直接流下来了。"},{"s":320.53,"e":328.35,"t":"不是因为感动。"},{"s":329.1,"e":333.91,"t":"是因为洋葱。"},{"s":334.67,"e":353.32,"t":"我用手背擦了一下眼睛，但手上也沾了洋葱汁，越擦越辣。"},{"s":354.07,"e":357.08,"t":"\"我来切。\""},{"s":357.83,"e":364.45,"t":"他把刀从我手里拿过去。"},{"s":365.2,"e":370.61,"t":"\"你负责看显微镜。\""},{"s":371.37,"e":399.64,"t":"他低下头，开始切。动作比我利索——手稳，刀口整齐，剥下来的表皮薄得透光。"},{"s":400.4,"e":415.44,"t":"我站在旁边，用另一只干净的手背又擦了一下眼泪。"},{"s":416.19,"e":423.41,"t":"他没抬头，但说了一句："},{"s":424.16,"e":428.37,"t":"\"纸在台子左边。\""},{"s":429.12,"e":439.95,"t":"我转过头——左边确实有一盒纸巾。"},{"s":440.71,"e":447.32,"t":"他连这个都提前看好了。"},{"s":448.08,"e":467.93,"t":"制片的时候，他负责把标本放到载玻片上，我负责调显微镜。"},{"s":468.68,"e":481.32,"t":"他放好之后往旁边让了一步，把位置让给我。"},{"s":482.07,"e":524.18,"t":"我弯腰，对焦。视野从模糊慢慢变得清晰——细胞壁、细胞核、液泡，一格一格整整齐齐地排列着，在光线下呈现出淡淡的紫色。"},{"s":524.94,"e":529.15,"t":"\"看到了。\""},{"s":529.9,"e":546.75,"t":"他凑过来——肩膀贴着我的肩膀，低头看目镜。"},{"s":547.5,"e":574.57,"t":"他把一只手搭在桌沿，另一只手扶着显微镜的底座——那个姿势像是在保护那个画面。"},{"s":575.32,"e":581.34,"t":"\"很清楚。\"他说。"},{"s":582.09,"e":590.52,"t":"他说话的热气碰到我的耳朵。"},{"s":591.27,"e":600.29,"t":"我假装没注意到，继续调焦距。"},{"s":601.05,"e":623.91,"t":"但那份洋葱表皮细胞的玻片标本——我调了三分多钟才调到最清晰。"},{"s":624.66,"e":630.68,"t":"不是因为我没调好。"},{"s":631.43,"e":642.26,"t":"是因为我不想让他那么快把肩膀移开。"},{"s":643.01,"e":651.43,"t":"下课后，我把实验报告写完。"},{"s":652.19,"e":674.45,"t":"他在旁边收拾器材，把用过的载玻片放到回收盒里，把显微镜的镜头盖好。"},{"s":675.2,"e":678.21,"t":"\"你写完了？\""},{"s":678.96,"e":686.18,"t":"\"快了——就差结论。\""},{"s":686.93,"e":691.14,"t":"\"那我在门口等你。\""},{"s":691.89,"e":701.52,"t":"他说完就拎着书包站到走廊上去了。"},{"s":702.27,"e":716.11,"t":"我低头写最后一句话的时候，笔尖动得特别快。"},{"s":716.86,"e":722.28,"t":"不是因为赶时间。"},{"s":723.03,"e":747.09,"t":"是因为他在门口等我——这句写在实验报告结论栏里的不是答案，但我在心里写了一遍。"}]},{"num":22,"title":"第22章 酸奶","file":"chapters/ch022.mp3","dur":623,"size_mb":4.8,"segs":[{"s":0,"e":14.2,"t":"时间：9 月 19 日—21 日 · 高二上"},{"s":14.91,"e":26.27,"t":"他第一次给我带酸奶，是在九月的第三个周末。"},{"s":26.98,"e":49.7,"t":"那天下午他从外面回来，手里拎着一个塑料袋，袋子上印着学校小卖部的 logo。"},{"s":50.41,"e":56.09,"t":"他把袋子放在我桌上。"},{"s":56.8,"e":60.77,"t":"\"给你的。\""},{"s":61.48,"e":89.88,"t":"我打开袋子——里面是一瓶酸奶。不是那种小杯的，是瓶装的，盖子拧开里面还有一层锡纸。"},{"s":90.59,"e":96.27,"t":"\"……你专门出去买的？\""},{"s":96.98,"e":100.39,"t":"\"顺路。\""},{"s":101.1,"e":109.62,"t":"他坐下来，拧开水杯喝了一口。"},{"s":110.33,"e":117.71,"t":"\"上次你不是说想喝酸奶吗？\""},{"s":118.42,"e":153.64,"t":"我愣了一下——我确实说过。大概是一周前，在食堂排队的时候，我看见冰柜里的酸奶，随口说了一句\"好久没喝了\"。"},{"s":154.35,"e":160.03,"t":"我就说了那么一次。"},{"s":160.74,"e":164.72,"t":"他记住了。"},{"s":165.43,"e":173.38,"t":"那瓶酸奶我喝了一整个晚上。"},{"s":174.09,"e":184.88,"t":"不是喝不完——是舍不得喝快。"},{"s":185.59,"e":208.88,"t":"每次拧开盖子喝一小口，再拧紧，放在桌角。到晚上熄灯的时候，还有小半瓶。"},{"s":209.59,"e":219.81,"t":"我把它放在床头的小架子上，躺下来。"},{"s":220.52,"e":231.88,"t":"黑暗中，我听见他的声音从对面传过来。"},{"s":232.59,"e":236.57,"t":"\"你还没喝完？\""},{"s":237.28,"e":240.68,"t":"\"……快了。\""},{"s":241.39,"e":255.03,"t":"\"一瓶酸奶喝三个小时——你是品酒师吗？\""},{"s":255.74,"e":279.59,"t":"他的语气里有一种我没听过的调子——不是平时那种平，是带着一点尾音的往上翘。"},{"s":280.3,"e":283.71,"t":"像在笑。"},{"s":284.42,"e":291.23,"t":"我盯着黑暗中的天花板。"},{"s":291.94,"e":297.06,"t":"\"因为是你买的。\""},{"s":297.77,"e":301.74,"t":"我说。"},{"s":302.45,"e":309.84,"t":"然后对面安静了大概三秒。"},{"s":310.55,"e":319.07,"t":"然后他说：\"那我以后多买点。\""},{"s":319.78,"e":326.02,"t":"声音比刚才轻了一点。"},{"s":326.73,"e":340.93,"t":"但在这间漆黑的宿舍里，每一个字都特别清楚。"},{"s":341.64,"e":353,"t":"第二天早上，我桌上又多了一瓶。"},{"s":353.71,"e":363.37,"t":"和昨天一样的牌子，一样的口味。"},{"s":364.08,"e":390.77,"t":"我拿起来的时候，瓶身上还带着冷藏柜里拿出来不久的那种凉意——他大概是一大早就去买了。"},{"s":391.48,"e":396.6,"t":"我走到他座位旁边。"},{"s":397.31,"e":401.85,"t":"\"你今天又买了？\""},{"s":402.56,"e":406.53,"t":"他头也没抬。"},{"s":407.24,"e":413.49,"t":"\"不是说了多买点吗。\""},{"s":414.2,"e":426.13,"t":"他说完就翻了一页书，没给我回话的机会。"},{"s":426.84,"e":438.77,"t":"我站在他旁边，手里握着那瓶冰凉的酸奶。"},{"s":439.48,"e":450.84,"t":"\"多买点\"——他说的是\"多买点\"。"},{"s":451.55,"e":457.8,"t":"不是\"再买一次\"。"},{"s":458.51,"e":463.05,"t":"是\"多买点\"。"},{"s":463.76,"e":468.87,"t":"那瓶酸奶我没喝。"},{"s":469.58,"e":492.87,"t":"不是不想喝——是我把它放进了书包里，带回了宿舍，放在了床头的架子上。"},{"s":493.58,"e":500.39,"t":"和昨晚那瓶的空瓶放在一起。"},{"s":501.1,"e":509.06,"t":"两个瓶子，并排站着。"},{"s":509.77,"e":524.53,"t":"我看着它们站了一会儿，然后躺到床上。"},{"s":525.24,"e":551.37,"t":"窗外的风吹进来，把窗帘吹得轻轻鼓起来。宿舍里只有我一个人，他在教室还没回来。"},{"s":552.08,"e":560.03,"t":"我侧过头，看着那两瓶酸奶。"},{"s":560.74,"e":568.69,"t":"一瓶喝完了，一瓶还没开。"},{"s":569.4,"e":572.81,"t":"但我都没扔。"},{"s":573.52,"e":585.45,"t":"因为这是我第一次收到不只是\"顺手\"的东西。"},{"s":586.16,"e":591.27,"t":"他走了很远的路。"},{"s":591.98,"e":597.66,"t":"他记得我说过的话。"},{"s":598.37,"e":607.46,"t":"他把\"多买点\"当作一个承诺来说。"},{"s":608.17,"e":622.94,"t":"我闭上眼睛，在只有一个人的宿舍里，笑了一下。"}]},{"num":23,"title":"第23章 吃醋","file":"chapters/ch023.mp3","dur":647.4,"size_mb":4.9,"segs":[{"s":0,"e":11.97,"t":"时间：9 月 22 日 · 高二上"},{"s":12.8,"e":25.43,"t":"张尧来找我的时候，我正在座位上做题。"},{"s":26.26,"e":30.25,"t":"\"林深。\""},{"s":31.08,"e":58.35,"t":"我抬起头。张尧——博文的邻居，也是他的初中同学——站在我桌边。"},{"s":59.18,"e":69.81,"t":"\"你知道博文上周三看了我一眼吗？\""},{"s":70.65,"e":73.97,"t":"\"……什么意思？\""},{"s":74.8,"e":106.72,"t":"\"上周三中午你在走廊上跟我说话——他看见了。后来我去找他，他看了我一眼——不太高兴。\""},{"s":107.55,"e":114.2,"t":"我握着笔的手停了一下。"},{"s":115.03,"e":119.68,"t":"\"……你看错了吧。\""},{"s":120.51,"e":141.79,"t":"\"没看错。我认识他十年了。他不高兴的时候就是那个表情。\""},{"s":142.62,"e":167.22,"t":"张尧走了之后，我坐在座位上，盯着面前的题看了半天，一个字都没看进去。"},{"s":168.05,"e":178.03,"t":"中午在食堂，我和他坐在一起。"},{"s":178.86,"e":184.84,"t":"他今天不怎么说话。"},{"s":185.67,"e":239.53,"t":"不是完全不说——是那种表面看起来正常、但筷子按得比平时重的安静。他把碗里的饭夹起来，放下，夹起来，放下——好像吃饭只是一件他在完成的任务。"},{"s":240.36,"e":250.34,"t":"我吃完了，他碗里还剩大半。"},{"s":251.17,"e":255.16,"t":"\"你吃饱了？\""},{"s":255.99,"e":259.98,"t":"\"嗯。\""},{"s":260.81,"e":264.8,"t":"他放下筷子。"},{"s":265.63,"e":284.25,"t":"我看着他那个样子，心里有一个念头——但我不敢确认。"},{"s":285.08,"e":294.39,"t":"下午在楼梯口，他叫住了我。"},{"s":295.22,"e":303.86,"t":"\"你今天上午和张尧说什么了？\""},{"s":304.69,"e":331.95,"t":"他的语气很平——和平时一样。但我注意到他握着楼梯扶手的手指，指节发白。"},{"s":332.78,"e":344.09,"t":"\"没说什么——他过来跟我说了几句话。\""},{"s":344.92,"e":348.24,"t":"\"什么话？\""},{"s":349.07,"e":365.03,"t":"\"……他说——你上周三看了他一眼，不太高兴。\""},{"s":365.86,"e":369.85,"t":"他没回答。"},{"s":370.68,"e":374.67,"t":"沉默了一会儿。"},{"s":375.5,"e":390.13,"t":"\"以后——不要和张尧讨论数学题。\""},{"s":390.96,"e":403.6,"t":"\"……我没有和他讨论数学题。就说了几句话。\""},{"s":404.43,"e":409.08,"t":"\"那也别说了。\""},{"s":409.91,"e":417.23,"t":"他转身往上走了两步。"},{"s":418.06,"e":422.71,"t":"然后停下来。"},{"s":423.54,"e":430.86,"t":"\"你要问物理题，找我。\""},{"s":431.69,"e":437.01,"t":"他说完就走了。"},{"s":437.84,"e":453.8,"t":"我站在楼梯上，看着他的背影消失在三楼转角。"},{"s":454.63,"e":467.26,"t":"他要说的是——你要找，找我。"},{"s":468.09,"e":478.07,"t":"周海在晚自习的时候听了这件事。"},{"s":478.9,"e":482.89,"t":"\"他吃醋了。\""},{"s":483.72,"e":487.04,"t":"\"……不可能。\""},{"s":487.87,"e":505.16,"t":"\"怎么不可能？他不让你和别人说话——这不叫吃醋叫什么？\""},{"s":505.99,"e":509.98,"t":"我看着他。"},{"s":510.81,"e":515.47,"t":"\"他喜欢你。\""},{"s":516.3,"e":519.62,"t":"周海说。"},{"s":520.45,"e":527.1,"t":"我不敢接这句话。"},{"s":527.93,"e":573.81,"t":"但那天晚上我回到宿舍的时候，他已经躺下了。我推门进去，他没动——但我看见他放在被子上面的手指，微微收紧了一下。"},{"s":574.64,"e":580.63,"t":"他在装睡。"},{"s":581.46,"e":585.45,"t":"我没戳穿。"},{"s":586.28,"e":599.58,"t":"但我躺下之后，在黑暗里说了一句话。"},{"s":600.41,"e":610.38,"t":"\"我以后不和他们讨论数学题了。\""},{"s":611.21,"e":615.87,"t":"安静了很久。"},{"s":616.7,"e":624.01,"t":"久到我以为他睡着了。"},{"s":624.84,"e":639.47,"t":"然后黑暗里传来一声很轻的\"嗯\"。"},{"s":640.3,"e":647.62,"t":"像从被子里闷出来的。"}]},{"num":24,"title":"第24章 别扭","file":"chapters/ch024.mp3","dur":763.3,"size_mb":5.8,"segs":[{"s":0,"e":33.12,"t":"时间：9 月 23 日 · 高二上"},{"s":35.71,"e":79.18,"t":"吃醋那件事的第二天，我做了一件蠢事。"},{"s":81.77,"e":139.73,"t":"下午自习课，我走到他桌边，想打破那个还有点僵的气氛。"},{"s":142.32,"e":156.81,"t":"\"博文。\""},{"s":159.4,"e":171.82,"t":"他抬起头。"},{"s":174.4,"e":190.96,"t":"\"我能叫你小博吗？\""},{"s":193.55,"e":212.18,"t":"他看了我大概 3 秒。"},{"s":214.77,"e":225.12,"t":"\"不能。\""},{"s":227.71,"e":238.06,"t":"\"……为什么？\""},{"s":240.65,"e":259.28,"t":"他合上手里的书。"},{"s":261.86,"e":303.27,"t":"\"因为'博文'是'博文'。'小博'是'小博'。\""},{"s":305.85,"e":320.34,"t":"\"……有什么区别？\""},{"s":322.93,"e":333.28,"t":"他想了想。"},{"s":335.87,"e":352.43,"t":"\"'博文'只有你能叫。\""},{"s":355.02,"e":388.14,"t":"他说完就低下头继续看书了。"},{"s":390.73,"e":442.48,"t":"我站在他桌边，手里拿着本来要问他的物理卷子。"},{"s":445.07,"e":478.19,"t":"他说——\"博文\"只有我能叫。"},{"s":480.77,"e":511.83,"t":"下午，他桌上多了一瓶酸奶。"},{"s":514.41,"e":572.37,"t":"我坐下来的时候，他把它推过来——没看我，没说话。"},{"s":574.96,"e":622.57,"t":"我拿起来看了一眼——是我上次说好喝的那个牌子。"},{"s":625.16,"e":639.65,"t":"我打开喝了一口。"},{"s":642.24,"e":656.73,"t":"别扭的。"},{"s":659.32,"e":671.74,"t":"甜的。"},{"s":674.33,"e":697.1,"t":"两个味道混在一起。"},{"s":699.68,"e":763.86,"t":"就像我和他现在这样——不说话，但他给我买了酸奶。"}]},{"num":25,"title":"第25章 发烧","file":"chapters/ch025.mp3","dur":641,"size_mb":4.9,"segs":[{"s":0,"e":7.17,"t":"时间：10 月 5 日 · 高二上"},{"s":7.86,"e":17.78,"t":"国庆假期回来之后，我就开始不舒服了。"},{"s":18.47,"e":51.01,"t":"早上起来的时候嗓子干得像砂纸，头也沉。我摸了一下额头——没发烧，但那种\"快要发烧了\"的感觉已经来了。"},{"s":51.7,"e":56.66,"t":"我没有告诉任何人。"},{"s":57.35,"e":76.65,"t":"第一节课我撑着听完了。第二节开始之前，我趴在桌上，想缓一下。"},{"s":77.34,"e":87.81,"t":"再抬头的时候——桌角多了一杯热水。"},{"s":88.5,"e":109.46,"t":"我转过头——他坐回自己的座位了。但他桌上放着一盒退烧药，还没拆封。"},{"s":110.15,"e":117.87,"t":"他什么时候买的？什么时候放的？"},{"s":118.55,"e":122.97,"t":"我不知道。"},{"s":123.66,"e":139.65,"t":"但那杯热水冒着白气，在十月的冷空气里特别显眼。"},{"s":140.34,"e":148.61,"t":"我握起来喝了一口——烫的。"},{"s":149.3,"e":156.46,"t":"中午的时候，体温上来了。"},{"s":157.15,"e":187.48,"t":"我趴在桌上，头埋在胳膊里，浑身发冷。教室里有人在说话，有人在笑——那些声音像隔了一层水传过来。"},{"s":188.17,"e":200.3,"t":"然后我感觉到一只手贴上了我的额头。"},{"s":200.99,"e":203.75,"t":"凉的。"},{"s":204.44,"e":223.19,"t":"我睁开眼——他站在我旁边，手背贴着我的额头，眉头微微皱了一下。"},{"s":223.87,"e":228.29,"t":"\"你发烧了。\""},{"s":228.98,"e":232.84,"t":"\"……嗯。\""},{"s":233.52,"e":236.83,"t":"\"吃药了吗？\""},{"s":237.52,"e":240.83,"t":"\"吃了。\""},{"s":241.52,"e":244.83,"t":"\"那回宿舍。\""},{"s":245.52,"e":279.15,"t":"我站起来的时候，腿有点软。他伸手扶了我一下——手掌贴着我的手臂，隔着校服的袖子，我感觉到他手的温度。"},{"s":279.84,"e":285.36,"t":"凉凉的。很舒服。"},{"s":286.05,"e":294.87,"t":"他把我送到宿舍门口，没有进去。"},{"s":295.56,"e":301.07,"t":"\"你躺着。我去医务室。\""},{"s":301.76,"e":310.03,"t":"我说\"不用\"——但他已经转身走了。"},{"s":310.72,"e":337.74,"t":"我躺在床上，也不知道过了多久。头很重，身体发冷，被子被我裹了一圈又一圈。"},{"s":338.43,"e":342.84,"t":"然后门开了。"},{"s":343.53,"e":362.28,"t":"他回来了。手里拎着一个塑料袋——里面装着药、酒精棉、还有一个保温杯。"},{"s":362.97,"e":393.3,"t":"他坐到床沿上——我睡下铺——把保温杯拧开，倒了一杯热水放在床头。然后他拆开酒精棉，抽出一片。"},{"s":393.99,"e":397.85,"t":"\"手给我。\""},{"s":398.54,"e":401.29,"t":"我伸出手。"},{"s":401.98,"e":415.22,"t":"他握住我的手腕，用酒精棉擦了一下我的手心。"},{"s":415.91,"e":419.21,"t":"凉的。"},{"s":419.9,"e":448.58,"t":"他的拇指按在我手腕内侧——那个位置，脉搏在跳。他的拇指停在那里，大概过了两三秒才松开。"},{"s":449.27,"e":458.09,"t":"然后他把那杯热水放到我手里。"},{"s":458.78,"e":461.54,"t":"\"喝完。\""},{"s":462.22,"e":466.08,"t":"我喝了。"},{"s":466.77,"e":475.04,"t":"他又拆了一包退烧药放在桌上。"},{"s":475.73,"e":482.9,"t":"\"晚上如果又烧了，吃这个。\""},{"s":483.59,"e":488,"t":"我说了一声\"谢谢\"。"},{"s":488.69,"e":491.45,"t":"他没回答。"},{"s":492.14,"e":515.3,"t":"但他站起来之前，把挂在床头的校服外套拿了下来——团成一团，垫在我枕头上面。"},{"s":515.99,"e":520.95,"t":"\"这样高一点，舒服。\""},{"s":521.64,"e":526.6,"t":"那是他的校服。"},{"s":527.29,"e":559.27,"t":"我枕着他的校服，在被子里闭着眼睛。他的外套有一股洗衣液的味道——不是柚子味的那件，是另一件。"},{"s":559.96,"e":565.48,"t":"但我记住了那个味道。"},{"s":566.17,"e":571.68,"t":"第二天我退烧了。"},{"s":572.37,"e":584.5,"t":"早上去教室的时候，我桌上放着一杯豆浆。"},{"s":585.19,"e":589.05,"t":"温的。"},{"s":589.74,"e":601.87,"t":"我坐下来，看了一眼他的方向——他在看书。"},{"s":602.56,"e":613.59,"t":"但桌角放着一个已经拆开的退烧药盒。"},{"s":614.28,"e":621.45,"t":"和我床头那盒一模一样。"},{"s":622.14,"e":628.2,"t":"他给自己也买了一盒。"},{"s":628.89,"e":641.02,"t":"大概是——怕被我传染，不能照顾我。"}]},{"num":26,"title":"第26章 同一层楼","file":"chapters/ch026.mp3","dur":712.7,"size_mb":5.4,"segs":[{"s":0,"e":9.15,"t":"时间：10 月底 · 高二上，月考"},{"s":9.78,"e":18.42,"t":"月考的考场是按上次排名排的。"},{"s":19.05,"e":37.35,"t":"我拿着准考证在教学楼前面看了一眼——我在三楼，302 考场。"},{"s":37.98,"e":41.03,"t":"\"你呢？\""},{"s":41.67,"e":48.78,"t":"我把准考证递给旁边的人看。"},{"s":49.42,"e":55.01,"t":"\"303。\"他说。"},{"s":55.64,"e":59.71,"t":"303。"},{"s":60.34,"e":66.95,"t":"就在 302 隔壁。"},{"s":67.58,"e":92.99,"t":"中间隔了一道墙。但我走到三楼的时候，发现 302 和 303 之间隔的不是墙——是一扇窗户。"},{"s":93.62,"e":119.03,"t":"走廊尽头有一扇大窗，正对着天井。和我高一上站的那扇窗户在同一层楼，只是换了一个方向。"},{"s":119.67,"e":129.32,"t":"我站在那扇窗户前面，往对面看了一眼。"},{"s":129.95,"e":135.04,"t":"对面是一间空教室。"},{"s":135.67,"e":154.98,"t":"但我知道——从高一上开始，我和他之间的距离，已经从那扇窗户走到了这里。"},{"s":155.62,"e":159.17,"t":"同一层楼。"},{"s":159.81,"e":161.84,"t":"隔壁。"},{"s":162.48,"e":166.54,"t":"第一场考语文。"},{"s":167.18,"e":184.45,"t":"我坐在靠窗的位置，写完作文之后还剩一点时间，我往窗外看了一眼。"},{"s":185.09,"e":196.77,"t":"隔壁考场的窗户开着——但我看不到他。"},{"s":197.41,"e":226.37,"t":"可我知道他就在那扇窗户后面，大概隔着一道墙的距离。和我同时在做同一张卷子，和我同时在抬头看窗外。"},{"s":227.01,"e":237.17,"t":"这个认知让我的作文结尾多写了三行。"},{"s":237.81,"e":244.92,"t":"不为什么——就是突然想写。"},{"s":245.56,"e":254.19,"t":"第二场考数学的时候，发生了一件事。"},{"s":254.83,"e":270.58,"t":"我的 2B 铅笔在涂第三道选择题的时候——断了。"},{"s":271.22,"e":278.33,"t":"笔芯断在里面，转不动了。"},{"s":278.96,"e":299.29,"t":"我翻了一下笔袋——备用笔芯没带。夹层里只有一支签字笔和一管快用完的胶带。"},{"s":299.93,"e":303.99,"t":"还有半块橡皮。"},{"s":304.63,"e":322.41,"t":"是开学初他借给我的那块——后来他说不用还，我就一直放在笔袋里。"},{"s":323.05,"e":332.19,"t":"我盯着那半块橡皮看了大概两秒。"},{"s":332.83,"e":336.38,"t":"然后我举手了。"},{"s":337.02,"e":346.17,"t":"\"老师——我能借一下隔壁桌的铅笔吗？\""},{"s":346.8,"e":360.01,"t":"监考老师看了我一眼，点了点头，陪我到隔壁考场门口。"},{"s":360.65,"e":370.81,"t":"老师敲了一下门，里面的监考老师探出头来。"},{"s":371.44,"e":375.51,"t":"\"他铅笔断了。\""},{"s":376.15,"e":391.9,"t":"303 的监考老师往教室里看了一眼——\"谁有多的铅笔？\""},{"s":392.53,"e":399.14,"t":"然后我听见了一个声音："},{"s":399.77,"e":402.31,"t":"\"我这有。\""},{"s":402.95,"e":406,"t":"是他。"},{"s":406.63,"e":421.88,"t":"他站起来，走到门口，把一支削好的 2B 铅笔递给我。"},{"s":422.51,"e":427.09,"t":"没多问，没多说。"},{"s":427.72,"e":430.77,"t":"就递过来了。"},{"s":431.4,"e":461.38,"t":"我接住的时候，他的手指碰到我的手指——凉的，和他平时的手温不太一样。大概是因为考场的空调。"},{"s":462.02,"e":465.07,"t":"\"谢谢。\""},{"s":465.7,"e":468.75,"t":"我说。"},{"s":469.39,"e":472.94,"t":"他点了下头。"},{"s":473.58,"e":478.66,"t":"然后转身回座位了。"},{"s":479.3,"e":495.05,"t":"我回到自己的考场，坐下来，用那支铅笔画完了剩下的答题卡。"},{"s":495.68,"e":506.86,"t":"最后一笔涂完的时候，我把那支铅笔放在桌角。"},{"s":507.5,"e":517.15,"t":"等我做完卷子，抬头看了一眼窗外——"},{"s":517.79,"e":530.49,"t":"502 考场和 303 考场之间，隔了一道墙。"},{"s":531.13,"e":543.32,"t":"但他的手，刚刚从这个考场借到了那个考场。"},{"s":543.96,"e":551.58,"t":"考完最后一科，我在楼下等他。"},{"s":552.21,"e":560.34,"t":"他走出来的时候，手里拎着文具袋。"},{"s":560.98,"e":564.03,"t":"\"笔——\""},{"s":564.66,"e":570.25,"t":"\"你留着。下次别再断了。\""},{"s":570.89,"e":580.03,"t":"他说完就往前走了一步，走到我旁边。"},{"s":580.67,"e":583.72,"t":"\"考得怎么样？\""},{"s":584.35,"e":595.02,"t":"\"还行。数学最后一道大题没做出来。\""},{"s":595.66,"e":598.71,"t":"\"哪题？\""},{"s":599.34,"e":602.39,"t":"\"函数那道。\""},{"s":603.03,"e":612.68,"t":"他点了下头。\"那题我也想了挺久。\""},{"s":613.32,"e":630.59,"t":"他说\"我也想了挺久\"——不是\"那题不难\"或者\"你应该能写出来\"。"},{"s":631.23,"e":638.34,"t":"他说的是一起想了很久。"},{"s":638.98,"e":646.6,"t":"好像那场考试我们是一起考的。"},{"s":647.23,"e":665.53,"t":"虽然隔了一道墙，但在同一层楼，同一时间，为同一道题在转笔。"},{"s":666.16,"e":694.62,"t":"我走在他旁边，十一月的风从走廊那头吹过来。他刚考完试，校服没拉拉链，风把他的衣摆吹起来了一下。"},{"s":695.25,"e":702.37,"t":"距离下一次月考，还有一个月。"},{"s":703,"e":712.66,"t":"但下次——我们不只会在同一层楼了。"}]},{"num":27,"title":"第27章 封面有颜色的本子","file":"chapters/ch027.mp3","dur":865.3,"size_mb":13.2,"segs":[{"s":0,"e":9.21,"t":"时间：10 月 7 日—20 日 · 高二上"},{"s":9.79,"e":13.01,"t":"10 月 7 日"},{"s":13.59,"e":22.8,"t":"下午 4 点 25 分，我站起来，往他座位走。"},{"s":23.37,"e":62.52,"t":"不是约好的——是两周前的一个下午，他路过我座位的时候说了一句\"你物理作业写完没？拿来我看\"。从那之后，每天下午 4 点半，我会拿着一周攒下来的物理题去他那里。"},{"s":63.1,"e":86.13,"t":"他坐在倒数第三排靠窗。我走过去的时候，他正在把桌上的东西往旁边推——腾出一个放卷子的位置。"},{"s":86.7,"e":92.23,"t":"我坐下来，把卷子摊开。"},{"s":92.8,"e":98.33,"t":"他低头看了大概 30 秒。"},{"s":98.91,"e":109.5,"t":"\"第三题思路对了，但第二步用错了公式。\""},{"s":110.08,"e":120.21,"t":"他拿起笔，在草稿纸上写了一个公式，推过来。"},{"s":120.78,"e":130.46,"t":"我看了一眼——确实是我记混的那个。"},{"s":131.03,"e":141.16,"t":"\"这个地方用这个，上面那道题你就能接上了。\""},{"s":141.74,"e":148.19,"t":"\"……你只看了一眼就知道我卡在哪？\""},{"s":148.76,"e":156.59,"t":"\"因为你每次都在同一个地方卡住。\""},{"s":157.17,"e":168.22,"t":"他说完就低下头，在自己的本子上写了一行什么。"},{"s":168.8,"e":178.47,"t":"我没看清他在写什么——他用手臂挡了一下。"},{"s":179.05,"e":199.77,"t":"但我注意到他用的那个本子。封面上有一点颜色——深蓝色，好像还有一个小树的图案。"},{"s":200.35,"e":204.03,"t":"我没多想。"},{"s":204.61,"e":209.21,"t":"他把本子合上了。"},{"s":209.79,"e":219,"t":"\"今天先把这三道改完，明天再讲后面的。\""},{"s":219.58,"e":223.26,"t":"10 月 14 日"},{"s":223.84,"e":228.44,"t":"一周后，我又去了。"},{"s":229.02,"e":248.36,"t":"同样的时间，同样的位置。他已经把桌子腾好了，桌上放着一杯水——给我的。"},{"s":248.94,"e":274.73,"t":"我坐下来之后，他讲了大概 20 分钟。然后他停下来，从抽屉里拿出那个深蓝色的本子，翻开，低头写了一分钟。"},{"s":275.31,"e":283.14,"t":"我坐在他右边，距离不到 30 厘米。"},{"s":283.71,"e":301.21,"t":"他写字的时候，我习惯性地往那个方向看了一眼——不是刻意偷看，是余光扫到的。"},{"s":301.79,"e":314.22,"t":"但我什么也没看清。他把本子侧了一下，挡住了我的视线。"},{"s":314.8,"e":320.33,"t":"然后合上，放回抽屉。"},{"s":320.9,"e":329.19,"t":"\"讲完了。你回去把第五题做出来就行。\""},{"s":329.77,"e":332.53,"t":"我点了点头。"},{"s":333.11,"e":344.16,"t":"但我走出他座位的时候，回头看了一眼他的抽屉。"},{"s":344.74,"e":355.33,"t":"那个深蓝色的本子，合着，露出一截书脊。"},{"s":355.91,"e":360.97,"t":"他到底每天在写什么？"},{"s":361.55,"e":364.77,"t":"10 月 20 日"},{"s":365.35,"e":373.18,"t":"真相是在第三个星期三揭开的。"},{"s":373.75,"e":383.89,"t":"那天下午 4 点半，我到的时候，他不在座位上。"},{"s":384.46,"e":388.61,"t":"我就站在他桌边等。"},{"s":389.18,"e":408.99,"t":"他的桌面收拾得很干净——卷子叠成一沓，笔袋放在右上角，水杯放在左边。"},{"s":409.56,"e":421.54,"t":"那个深蓝色的本子——放在桌面上，没有合上。"},{"s":422.11,"e":428.56,"t":"我不确定他是不是故意留下的。"},{"s":429.14,"e":436.04,"t":"但我就站在那里，低头看了一眼。"},{"s":436.62,"e":444.45,"t":"那一页上的字很少。一行。"},{"s":445.03,"e":461.61,"t":"蓝黑色的墨水，字迹很整齐，和平时草稿纸上那种飞起来的样子不一样。"},{"s":462.18,"e":465.41,"t":"那行字写着："},{"s":465.98,"e":471.51,"t":"\"小深今天问了一道物理题。\""},{"s":472.08,"e":478.99,"t":"我盯着那行字看了大概 5 秒。"},{"s":479.57,"e":495.69,"t":"不是因为我没看懂——是因为我看懂了，但我的大脑拒绝处理它的意思。"},{"s":496.26,"e":515.61,"t":"他每天下午 4 点半拿出这个本子写一分钟——写的不是物理笔记，不是日记——写的是我。"},{"s":516.18,"e":527.24,"t":"\"小深今天问了一道物理题\"——他在记录我。"},{"s":527.81,"e":530.58,"t":"每一天。"},{"s":531.15,"e":544.51,"t":"我站在他座位旁边，手指搭在桌沿上，不知道该看哪里。"},{"s":545.08,"e":552.45,"t":"这时候他从教室门口走进来了。"},{"s":553.03,"e":566.85,"t":"他看见我站在他桌边，又看见那个本子——他脚步顿了一下。"},{"s":567.42,"e":576.17,"t":"然后他走过来，把本子合上，放进了抽屉里。"},{"s":576.75,"e":579.97,"t":"动作很轻。"},{"s":580.55,"e":585.61,"t":"安静持续了大概三秒。"},{"s":586.19,"e":588.95,"t":"\"你——\""},{"s":589.53,"e":592.29,"t":"\"……看见了。\""},{"s":592.87,"e":595.63,"t":"他看了我一眼。"},{"s":596.21,"e":600.81,"t":"然后他说了一句话。"},{"s":601.39,"e":609.22,"t":"\"你知道我是从什么时候开始写的吗？\""},{"s":609.79,"e":612.56,"t":"\"……什么时候？\""},{"s":613.13,"e":617.28,"t":"他沉默了一会儿。"},{"s":617.85,"e":623.84,"t":"\"高一上。12 月 7 号。\""},{"s":624.42,"e":630.41,"t":"我握着卷子的手指紧了一下。"},{"s":630.98,"e":653.09,"t":"\"第一页写的是：'今天 611 班那个站在走廊上的人——他今天看了我很久。他的眼睛里有光。'\""},{"s":653.66,"e":661.49,"t":"他说这句话的时候，语气很平。"},{"s":662.07,"e":669.9,"t":"像是在念一条已经背了几百遍的定理。"},{"s":670.47,"e":682.91,"t":"我站在他面前，感觉整个世界都安静了两秒。"},{"s":683.49,"e":689.01,"t":"高一上。12 月 7 号。"},{"s":689.59,"e":706.17,"t":"那时候我在走廊上看着他——我以为他从来没有注意到我。"},{"s":706.74,"e":710.89,"t":"但他不仅注意到了。"},{"s":711.47,"e":714.23,"t":"他记下来了。"},{"s":714.8,"e":721.25,"t":"他把那一天写进了本子里。"},{"s":721.83,"e":729.2,"t":"从那天开始，记了一年。"},{"s":729.77,"e":735.76,"t":"那天晚上我没有回教室。"},{"s":736.34,"e":750.15,"t":"我一个人走到了 611 班的走廊——我高一上站的那个位置。"},{"s":750.73,"e":779.75,"t":"那扇窗户还在。玻璃上的反光在路灯下映出我的脸。我站在那里，看着对面 610 班的最后一排——他高一上坐的位置。"},{"s":780.32,"e":782.16,"t":"空着的。"},{"s":782.74,"e":786.88,"t":"但他已经不在那里了。"},{"s":787.46,"e":795.29,"t":"我站在那扇窗户前面，忽然笑了。"},{"s":795.87,"e":802.31,"t":"不是苦笑——是真的笑了。"},{"s":802.89,"e":807.03,"t":"因为我发现了一件事。"},{"s":807.61,"e":831.1,"t":"我们高一上每天早上隔着那个天井互相看——他看我，我也看他。谁都不知道对方也在看。"},{"s":831.67,"e":839.5,"t":"但他在本子的第一页写下了那一天。"},{"s":840.08,"e":848.37,"t":"而我在心里，记下了每一个瞬间。"},{"s":848.95,"e":853.09,"t":"那扇窗户还在。"},{"s":853.67,"e":856.89,"t":"玻璃还在反光。"},{"s":857.47,"e":865.3,"t":"但我和他之间——已经不需要隔着它了。"}]},{"num":28,"title":"第28章 烦躁","file":"chapters/ch028.mp3","dur":919.8,"size_mb":7,"segs":[{"s":0,"e":20.52,"t":"时间：12 月 4 日 · 高二上"},{"s":22.35,"e":48.74,"t":"12 月 4 号那天，我也不知道自己怎么了。"},{"s":50.57,"e":135.58,"t":"早上起来的时候就感觉不对。不是哪里痛，不是哪里不舒服——就是闷。像有一团东西堵在胸口，不上不下。"},{"s":137.42,"e":234.16,"t":"早自习我坐在座位上了，但没看书。我盯着英语课本的第一页，盯着那篇课文的第一行——看了十分钟，一个字都没读进去。"},{"s":235.99,"e":255.04,"t":"下午 4 点半我没有去他那里。"},{"s":256.88,"e":353.62,"t":"不是不想去。是觉得自己今天去了也说不出什么好话。我怕我一开口，就会把那团堵在胸口的东西吐出来——吐在他面前。"},{"s":355.45,"e":371.57,"t":"我不想让他看见那样的我。"},{"s":373.4,"e":399.79,"t":"但 4 点 45 的时候，他走过来了。"},{"s":401.62,"e":419.21,"t":"在我桌边站了一下。"},{"s":421.04,"e":429.84,"t":"\"你今天没来。\""},{"s":431.67,"e":440.46,"t":"\"……嗯。\""},{"s":442.3,"e":452.56,"t":"\"为什么？\""},{"s":454.39,"e":461.72,"t":"\"不想去。\""},{"s":463.55,"e":475.28,"t":"他沉默了几秒。"},{"s":477.11,"e":502.03,"t":"然后他拉出我旁边的椅子，坐了下来。"},{"s":503.86,"e":511.19,"t":"\"那我来。\""},{"s":513.02,"e":552.59,"t":"他把物理卷子放在我桌上——不是我的，是他自己的。"},{"s":554.43,"e":582.28,"t":"\"最后一道大题我不确定答案。你看看。\""},{"s":584.11,"e":597.3,"t":"我低头看那道题。"},{"s":599.13,"e":628.45,"t":"他不需要我不确定。他哪道题都会。"},{"s":630.28,"e":642.01,"t":"但他坐在这里了。"},{"s":643.84,"e":699.54,"t":"我拿起笔，看了一眼那道题。然后我开口说了一句话——不是关于题的。"},{"s":701.37,"e":714.56,"t":"\"我今天心情不好。\""},{"s":716.39,"e":723.72,"t":"\"看出来了。\""},{"s":725.55,"e":734.35,"t":"\"那你还来？\""},{"s":736.18,"e":746.44,"t":"他想了想。"},{"s":748.27,"e":783.45,"t":"\"心情不好的时候，有人在旁边——会好得快一点。\""},{"s":785.28,"e":814.6,"t":"他说的不是\"我陪你\"，不是\"你怎么了\"。"},{"s":816.43,"e":854.54,"t":"他说的是\"会好得快一点\"——像一个经过验证的事实。"},{"s":856.37,"e":919.4,"t":"我低头看着他那道我明明知道答案的大题，忽然觉得胸口那团东西松了一点。"}]},{"num":29,"title":"第29章 寒假","file":"chapters/ch029.mp3","dur":789.2,"size_mb":6,"segs":[{"s":0,"e":15.44,"t":"时间：1 月 10 日 · 高二上期末"},{"s":16.58,"e":34.75,"t":"期末成绩出来那天，我排在 132 名。"},{"s":35.88,"e":75.85,"t":"不算差。比期中的 187 名进步了。但离他还差着一大截——他 64 名。"},{"s":76.99,"e":105.14,"t":"我盯着那个数字看了一会儿，然后把成绩单折好，放进口袋里。"},{"s":106.28,"e":120.81,"t":"走出公告栏的时候，他在外面等我。"},{"s":121.95,"e":128.31,"t":"\"多少？\""},{"s":129.44,"e":137.62,"t":"\"132。\""},{"s":138.75,"e":144.21,"t":"他点了点头。"},{"s":145.34,"e":158.06,"t":"\"你比期中进步了 55 名。\""},{"s":159.19,"e":163.74,"t":"\"……你算了？\""},{"s":164.87,"e":173.95,"t":"\"每期的排名我都看了。\""},{"s":175.09,"e":185.99,"t":"他说完就往前走了一步。"},{"s":187.13,"e":190.76,"t":"\"走吧。\""},{"s":191.9,"e":206.43,"t":"寒假开始那天，我们一起走出校门。"},{"s":207.56,"e":246.62,"t":"他的家和我的家在相反的方向。他在城东，我在城西——隔着大概 20 公里。"},{"s":247.76,"e":267.74,"t":"走出校门之后，他往左走，我往右走。"},{"s":268.88,"e":282.51,"t":"走了大概十步，我回头看了一眼。"},{"s":283.64,"e":290,"t":"他也在回头。"},{"s":291.14,"e":298.4,"t":"我们对视了一秒。"},{"s":299.54,"e":324.97,"t":"然后他笑了一下——嘴角往上翘了一下，然后转回去了。"},{"s":326.11,"e":332.47,"t":"我也转回去了。"},{"s":333.6,"e":338.14,"t":"20 公里。"},{"s":339.28,"e":366.53,"t":"不算远。但在这个没有住校的寒假里——它就是很远。"},{"s":367.67,"e":384.93,"t":"寒假第三天晚上，我给他发了一条微信。"},{"s":386.06,"e":389.69,"t":"\"睡了？\""},{"s":390.83,"e":400.82,"t":"过了一分半，他回了。"},{"s":401.96,"e":406.5,"t":"\"没。\""},{"s":407.63,"e":413.09,"t":"\"在干嘛？\""},{"s":414.22,"e":420.58,"t":"\"看书。\""},{"s":421.71,"e":431.71,"t":"过了一会儿他回了一条："},{"s":432.84,"e":438.29,"t":"\"你呢？\""},{"s":439.43,"e":445.79,"t":"\"发呆。\""},{"s":446.92,"e":453.28,"t":"然后就没有了。"},{"s":454.42,"e":475.31,"t":"但那个绿色的对话框，我翻来覆去看了好几遍。"},{"s":476.44,"e":483.71,"t":"\"没\"——\"你呢？\""},{"s":484.85,"e":490.3,"t":"四个字。"},{"s":491.43,"e":503.24,"t":"但我抱着手机看了好一会儿。"},{"s":504.38,"e":512.55,"t":"寒假第七天。"},{"s":513.69,"e":518.23,"t":"\"睡了？\""},{"s":519.37,"e":524.82,"t":"\"睡吧。\""},{"s":525.95,"e":531.4,"t":"\"晚安。\""},{"s":532.54,"e":535.26,"t":"\"晚安。\""},{"s":536.4,"e":544.57,"t":"寒假第十五天。"},{"s":545.71,"e":552.07,"t":"\"睡了？\""},{"s":553.2,"e":557.74,"t":"\"刚洗完。\""},{"s":558.88,"e":564.33,"t":"\"我也是。\""},{"s":565.47,"e":593.63,"t":"然后他发了一张照片——窗外的月亮。不大，但很亮。"},{"s":594.76,"e":622.92,"t":"我回了一张——我的窗户外面，也是同一个月亮。"},{"s":624.06,"e":630.41,"t":"20 公里。"},{"s":631.55,"e":642.45,"t":"但月亮是同一轮。"},{"s":643.59,"e":653.58,"t":"寒假最后一个晚上。"},{"s":654.71,"e":661.07,"t":"\"明天开学了。\""},{"s":662.21,"e":666.75,"t":"\"嗯。\""},{"s":667.89,"e":673.34,"t":"\"东西收好了？\""},{"s":674.47,"e":679.01,"t":"\"收好了。\""},{"s":680.15,"e":686.51,"t":"\"明天见。\""},{"s":687.64,"e":701.27,"t":"我盯着那三个字看了好一会儿。"},{"s":702.4,"e":706.04,"t":"明天见。"},{"s":707.17,"e":720.8,"t":"整个寒假，最像样的一句话。"},{"s":721.93,"e":727.38,"t":"我回了一个字："},{"s":728.52,"e":733.97,"t":"\"好。\""},{"s":735.11,"e":757.81,"t":"然后把手机放在枕头旁边，闭上眼睛。"},{"s":758.95,"e":788.93,"t":"明天见——这三个字比我整个寒假的任何一条消息都重。"}]},{"num":30,"title":"第30章 天台","file":"chapters/ch030.mp3","dur":740.7,"size_mb":5.7,"segs":[{"s":0,"e":11.41,"t":"时间：2 月 10 日 · 高二下学期开学第一天"},{"s":12.03,"e":21.45,"t":"开学那天下午，他走到我座位边上。"},{"s":22.07,"e":24.55,"t":"\"跟我来。\""},{"s":25.17,"e":28.14,"t":"\"去哪？\""},{"s":28.76,"e":31.24,"t":"他没回答。"},{"s":31.86,"e":47.73,"t":"但他站在我桌边等了我一下——那个姿势的意思是\"你来了就知道了\"。"},{"s":48.35,"e":53.31,"t":"我站起来，跟他走。"},{"s":53.93,"e":72.77,"t":"他带我从教学楼的侧楼梯上了六楼。六楼上面有一扇铁门——平时是锁着的。"},{"s":73.39,"e":83.31,"t":"他从口袋里掏出一把钥匙，打开了那扇门。"},{"s":83.93,"e":87.9,"t":"\"你哪来的钥匙？\""},{"s":88.52,"e":94.96,"t":"\"学生会的。天台归我管。\""},{"s":95.58,"e":104.01,"t":"他推开门，侧过身，等我先走出去。"},{"s":104.63,"e":115.54,"t":"我走出去的那一瞬间——天台。"},{"s":116.16,"e":124.1,"t":"整片天空就在我面前。"},{"s":124.72,"e":168.35,"t":"那天下午的阳光很好。二月的风还是凉的，但阳光落在身上，把凉意晒成了暖的。天台的水泥地面被照成浅灰色，远处城市的天际线在空气里清清楚楚。"},{"s":168.97,"e":174.43,"t":"他走过来，站到我旁边。"},{"s":175.05,"e":180.5,"t":"两只手搭在围栏上。"},{"s":181.12,"e":184.1,"t":"安静了一会儿。"},{"s":184.72,"e":186.7,"t":"\"小深。\""},{"s":187.32,"e":189.8,"t":"\"嗯？\""},{"s":190.42,"e":198.85,"t":"\"你知道这个天台对我来说是什么吗？\""},{"s":199.47,"e":201.95,"t":"\"……什么？\""},{"s":202.57,"e":213.48,"t":"他沉默了很久。久到我以为他不会回答了。"},{"s":214.1,"e":226.99,"t":"然后他说：\"是我决定不再一个人待着的地方。\""},{"s":227.61,"e":231.58,"t":"我转过头看他。"},{"s":232.2,"e":252.53,"t":"他没有看我。他低着头，看着围栏上的一道划痕——不知道是哪个学生留下来的。"},{"s":253.15,"e":277.45,"t":"\"我高一上的时候——坐在最后一排。每天早上我抬头，都能看见 611 班的走廊上有个人站在那。\""},{"s":278.07,"e":284.02,"t":"他说的那个人是我。"},{"s":284.64,"e":288.61,"t":"\"我看了你一年半。\""},{"s":289.23,"e":292.2,"t":"他说。"},{"s":292.82,"e":330.01,"t":"\"我在窗户边上看了你一年。我不知道你的名字，不知道你在哪个班，不知道你早上站在走廊上是在背书还是发呆。但我每次抬头——你都在。\""},{"s":330.63,"e":343.52,"t":"风从城市那边吹过来，把他校服的衣摆吹动了一下。"},{"s":344.14,"e":350.1,"t":"他把手从围栏上放下来。"},{"s":350.72,"e":365.1,"t":"\"2 月 13 号——你进 610 班了。你坐到我后面。\""},{"s":365.72,"e":368.2,"t":"他顿了顿。"},{"s":368.81,"e":388.65,"t":"\"那天我回家在本子上写了一行字。'他进 610 班了。原来他叫林深。'\""},{"s":389.27,"e":404.64,"t":"我站在他旁边，手指握着围栏的边缘，握得发白。"},{"s":405.26,"e":411.21,"t":"\"我高一上就想离你近一点。\""},{"s":411.83,"e":421.25,"t":"他说这话的时候，声音比刚才低了一些。"},{"s":421.87,"e":428.32,"t":"\"但我不知道该怎么靠近你。\""},{"s":428.94,"e":434.89,"t":"然后他转过身来面对我。"},{"s":435.51,"e":463.28,"t":"阳光落在他的侧脸上——他的眼睛里有光。那种像早上第一节课前、太阳照到对面教学楼白墙再反射过来的光。"},{"s":463.9,"e":468.36,"t":"\"我想和你在一起。\""},{"s":468.98,"e":470.97,"t":"他说。"},{"s":471.59,"e":486.46,"t":"四个字。没有铺垫，没有修饰，没有\"如果\"或者\"可能\"。"},{"s":487.08,"e":490.55,"t":"就是这四个字。"},{"s":491.17,"e":494.15,"t":"\"我喜欢你。\""},{"s":494.77,"e":498.74,"t":"他又说了一遍。"},{"s":499.36,"e":514.73,"t":"声音比第一遍稍微小一点——但每一笔每一画都清清楚楚。"},{"s":515.35,"e":527.25,"t":"我站在天台上，二月的风从耳边吹过去。"},{"s":527.87,"e":540.76,"t":"我以前想过——如果他真的说出来了，我会怎么样。"},{"s":541.38,"e":550.8,"t":"我想过我会紧张、会脸红、会结巴。"},{"s":551.42,"e":561.84,"t":"但真正发生的时候，我什么感觉都没有。"},{"s":562.46,"e":589.73,"t":"不——不是没有感觉。是感觉太多了，多到我的大脑选择关闭了一部分功能，只留下了一个念头。"},{"s":590.35,"e":594.32,"t":"我听见自己说："},{"s":594.94,"e":598.91,"t":"\"我也喜欢你。\""},{"s":599.53,"e":613.41,"t":"然后我看见他嘴角动了一下——眼睛底下那一块皱了一下。"},{"s":614.03,"e":617.01,"t":"1 厘米的皱。"},{"s":617.63,"e":621.59,"t":"然后他问了一句："},{"s":622.21,"e":627.67,"t":"\"你愿意做我男朋友吗。\""},{"s":628.29,"e":645.15,"t":"不是疑问句的语气——是那种他已经知道答案、但还是想听我说出来的语气。"},{"s":645.77,"e":648.25,"t":"我说：\""},{"s":648.87,"e":652.34,"t":"愿意。\""},{"s":652.96,"e":655.93,"t":"他笑了。"},{"s":656.55,"e":677.38,"t":"不是嘴角动一下的那种——是真的笑了。眼睛弯了一下，嘴角往上，整张脸都亮了一瞬。"},{"s":678,"e":689.9,"t":"然后他转回去，重新看向远处的城市。"},{"s":690.52,"e":695.98,"t":"我也转回去，站在他旁边。"},{"s":696.6,"e":709.49,"t":"天台的围栏有一点冰，但阳光照到的地方是暖的。"},{"s":710.11,"e":718.54,"t":"我们并排站着，谁都没有再说话。"},{"s":719.16,"e":734.53,"t":"远处的天际线在下午的阳光里被染成一层淡淡的橘色。"},{"s":735.15,"e":740.61,"t":"和我想象中一模一样。"}]},{"num":31,"title":"第31章 第一天","file":"chapters/ch031.mp3","dur":812.3,"size_mb":6.2,"segs":[{"s":0,"e":18.83,"t":"时间：2 月 11 日 · 高二下，在一起第一天"},{"s":19.77,"e":34.83,"t":"在一起之后的第一天，和前一天没什么区别。"},{"s":35.77,"e":75.68,"t":"早上 6 点 40，闹钟响了。我坐起来，看见他已经在穿校服了——背对着我，把拉链从下往上拉好。"},{"s":76.62,"e":81.89,"t":"\"起了？\""},{"s":82.83,"e":88.1,"t":"\"起了。\""},{"s":89.05,"e":97.33,"t":"对话和以前一样。"},{"s":98.27,"e":104.29,"t":"但感觉不一样。"},{"s":105.24,"e":151.92,"t":"早自习的时候，我坐在座位上，低头看英语书。但看了十分钟，一行都没读进去。因为我一直在想——现在我和他是什么关系？"},{"s":152.86,"e":162.65,"t":"想了十分钟，没想出答案。"},{"s":163.6,"e":183.17,"t":"准确地说——是想出了答案，但不知道该怎么执行。"},{"s":184.12,"e":211.98,"t":"如果我现在走过去跟他说话，应该是用\"男朋友\"的语气还是\"朋友\"的语气？"},{"s":212.92,"e":226.47,"t":"如果我用\"男朋友\"的语气，他会怎么反应？"},{"s":227.41,"e":238.71,"t":"如果我什么也不做，他会怎么想？"},{"s":239.65,"e":257.72,"t":"我盯着英语书上的单词，脑子里全是这些问题。"},{"s":258.67,"e":269.21,"t":"然后一张纸条被推到我桌上。"},{"s":270.15,"e":274.67,"t":"我打开。"},{"s":275.61,"e":279.37,"t":"他的字："},{"s":280.32,"e":290.1,"t":"\"别想了。好好背书。\""},{"s":291.05,"e":306.11,"t":"我抬头——他坐在前面，低头看书。"},{"s":307.05,"e":319.85,"t":"但他后脑勺好像长了眼睛一样。"},{"s":320.79,"e":335.85,"t":"我低下头，把那四个字又读了一遍。"},{"s":336.79,"e":351.1,"t":"\"别想了\"——他怎么知道我在想？"},{"s":352.04,"e":364.84,"t":"中午去食堂的时候，他在门口等我。"},{"s":365.78,"e":411.72,"t":"我走过去的时候，他看了我一眼。然后他伸手——不是牵我的手——是把我的书包带子从我肩膀上拿下来，拎到他手里。"},{"s":412.66,"e":420.19,"t":"\"你书包好像很重。\""},{"s":421.13,"e":425.65,"t":"\"……还好。\""},{"s":426.59,"e":443.16,"t":"他没再说别的。就帮我拎着书包，走进食堂了。"},{"s":444.1,"e":473.47,"t":"我跟在后面，看着他把我的书包挂到椅背上，然后坐到我旁边——不是对面。"},{"s":474.41,"e":481.94,"t":"他平时坐对面的。"},{"s":482.88,"e":487.4,"t":"今天坐旁边。"},{"s":488.34,"e":493.61,"t":"下午换座位。"},{"s":494.55,"e":533.71,"t":"按上学期期末的成绩排的——我 132 名。不算差，但也不算好。换了之后我数了一下——我离他隔了 5 行。"},{"s":534.65,"e":541.43,"t":"比之前远了一点。"},{"s":542.37,"e":558.18,"t":"我坐在新位置上，盯着前面的距离看了一会儿。"},{"s":559.12,"e":571.17,"t":"然后一张纸又被推到我桌上。"},{"s":572.11,"e":576.63,"t":"我打开："},{"s":577.57,"e":591.88,"t":"\"你每天都来问我物理题。比距离重要。\""},{"s":592.82,"e":607.13,"t":"我握着那张纸，在座位上坐了三秒。"},{"s":608.07,"e":618.61,"t":"然后我站起来，走到他桌边。"},{"s":619.55,"e":627.08,"t":"\"第四题怎么做？\""},{"s":628.03,"e":634.8,"t":"他抬头看了我一眼。"},{"s":635.74,"e":658.34,"t":"那个眼神——不是\"你这就来了\"——是\"我就知道你会来\"。"},{"s":659.28,"e":666.05,"t":"然后他拿起了笔。"},{"s":667,"e":679.04,"t":"晚上回宿舍，熄灯之后。"},{"s":679.99,"e":683.75,"t":"\"小深。\""},{"s":684.69,"e":689.21,"t":"\"嗯？\""},{"s":690.15,"e":702.2,"t":"\"你今天一共问了我七道物理题。\""},{"s":703.14,"e":706.91,"t":"\"……有吗？\""},{"s":707.85,"e":722.15,"t":"\"有。上午两道，中午一道，下午四道。\""},{"s":723.1,"e":728.37,"t":"我沉默了一下。"},{"s":729.31,"e":733.07,"t":"\"你数了？\""},{"s":734.01,"e":743.05,"t":"\"你每次走过来，我都数了。\""},{"s":743.99,"e":749.26,"t":"安静了几秒。"},{"s":750.21,"e":753.97,"t":"\"太多了？\""},{"s":754.91,"e":761.69,"t":"\"不是。\""},{"s":762.63,"e":768.65,"t":"他顿了一下。"},{"s":769.6,"e":790.68,"t":"\"就是——让你多跑几趟也没关系。反正我都在。\""},{"s":791.62,"e":805.18,"t":"黑暗里，我把被子拉过头顶。"},{"s":806.12,"e":812.14,"t":"然后笑了一下。"}]},{"num":32,"title":"第32章 第三次推迟","file":"chapters/ch032.mp3","dur":1005.7,"size_mb":7.7,"segs":[{"s":0,"e":6.02,"t":"时间：3 月初 · 在一起两周后"},{"s":6.49,"e":9.49,"t":"在一起两周了。"},{"s":9.96,"e":62.98,"t":"两周——说长不长，说短不短。短到我还是会在路过 610 班门口时下意识放慢脚步，长到我已经开始习惯每天下午 4 点半去他座位这件事——习惯了推椅子时那一声\"吱\"，习惯了他低头讲题时后颈那一截白，习惯了他偶尔回头看我一眼时眼底那一条 1 厘米的皱。"},{"s":63.45,"e":68.33,"t":"但有一件事我还是不习惯。"},{"s":68.8,"e":73.69,"t":"不习惯他欲言又止的样子。"},{"s":74.16,"e":80.93,"t":"今天是周四，下午最后一节自习课。"},{"s":81.4,"e":120.87,"t":"教室里只剩翻书声和窗外远处的广播声。博文坐在我前面两排的位置——上周换座位，他往前挪了一排，我在原地没动，距离变成了四行。不算远，但也不像之前那样一抬头就能看见他的后脑勺。"},{"s":121.34,"e":125.1,"t":"我低头做物理卷子。"},{"s":125.57,"e":139.49,"t":"做完最后一道大题，抬头的时候，看见他正侧着身，手搭在桌沿，看着我。"},{"s":139.96,"e":172.29,"t":"那个眼神——我说不上来。不是平时那种\"你又做完了？拿来我看\"的眼神，也不是吃醋时那种压着脾气的眼神。它更软，像有什么话在嘴里含了很久，含到快化了，又咽回去。"},{"s":172.76,"e":178.77,"t":"他看见我抬头，嘴角动了一下。"},{"s":179.24,"e":182.63,"t":"然后转回去了。"},{"s":183.1,"e":185.35,"t":"我有点在意。"},{"s":185.82,"e":200.49,"t":"放学后我去他座位拿笔记本——他上周说好借我的电磁学笔记，一直放在他桌角。"},{"s":200.96,"e":203.59,"t":"\"博文，笔记——\""},{"s":204.06,"e":210.83,"t":"\"嗯。\"他递过来，指尖碰到我的手指。"},{"s":211.3,"e":214.3,"t":"一秒。"},{"s":214.77,"e":227.56,"t":"然后就收回去了。他低头收拾书包，动作比平时慢，像在等什么。"},{"s":228.03,"e":230.66,"t":"我没走。"},{"s":231.13,"e":236.77,"t":"过了大概十秒，他抬起头。"},{"s":237.24,"e":239.12,"t":"\"林深。\""},{"s":239.59,"e":241.84,"t":"\"嗯？\""},{"s":242.31,"e":262.99,"t":"\"我其实……\"他停住了。喉结动了一下。然后他笑了笑，那个笑很轻，像怕惊动什么似的，\"算了。\""},{"s":263.46,"e":265.72,"t":"\"算了什么？\""},{"s":266.19,"e":269.57,"t":"\"算了，等高考完吧。\""},{"s":270.04,"e":273.05,"t":"又是这句。"},{"s":273.52,"e":302.85,"t":"我没有追问。不是不想，是我不敢。我怕我一追问，就会听到什么我还没准备好听的话。也怕我一追问，他就真的说了——说出来之后，我们还回得去吗？"},{"s":303.32,"e":308.2,"t":"所以我也笑了笑，说：\"好。\""},{"s":308.67,"e":312.06,"t":"他看了我大概 5 秒。"},{"s":312.53,"e":326.81,"t":"然后站起来，拎着书包往外走。走到门口时停了一下，没回头，只说了一句："},{"s":327.28,"e":332.17,"t":"\"明天下午 4 点半，老地方。\""},{"s":332.64,"e":334.9,"t":"\"好。\""},{"s":335.37,"e":340.25,"t":"我回到座位上，趴在桌上。"},{"s":340.72,"e":349,"t":"周海从后门进来，看见我的样子，叹了口气。"},{"s":349.47,"e":351.72,"t":"\"他又说了？\""},{"s":352.19,"e":354.82,"t":"\"又说了。\""},{"s":355.29,"e":357.93,"t":"\"第三次了吧？\""},{"s":358.4,"e":360.28,"t":"\"嗯。\""},{"s":360.75,"e":363.75,"t":"\"你就不想问清楚？\""},{"s":364.22,"e":366.48,"t":"\"我怕。\""},{"s":366.95,"e":369.2,"t":"\"怕什么？\""},{"s":369.67,"e":376.82,"t":"\"怕他说了之后，我发现不是我想的那样。\""},{"s":377.29,"e":380.67,"t":"周海沉默了一会儿。"},{"s":381.14,"e":389.79,"t":"\"你有没有想过——他说的可能就是你想的那样。\""},{"s":390.26,"e":392.89,"t":"\"想过。\""},{"s":393.36,"e":396.37,"t":"\"那不就结了。\""},{"s":396.84,"e":403.23,"t":"\"那是他说的。不是我猜的。不一样。\""},{"s":403.7,"e":413.48,"t":"周海不说话了。他拍了拍我的肩膀，走回自己的座位。"},{"s":413.95,"e":415.82,"t":"不一样。"},{"s":416.29,"e":456.9,"t":"我也说不上来哪里不一样，但它就是不一样。我猜的——我猜了两年多了。从高一上那个窗户开始，我就一直在猜他每一个动作、每一个眼神、每一句话的潜台词。猜对了那就是我运气好，猜错了我也习惯了。"},{"s":457.37,"e":461.13,"t":"但如果是他说的——"},{"s":461.6,"e":464.61,"t":"那就是真的。"},{"s":465.08,"e":474.1,"t":"而\"真的\"这两个字，比我想象中要重得多。"},{"s":474.57,"e":479.83,"t":"晚自习结束后，我走回宿舍。"},{"s":480.3,"e":485.19,"t":"走廊尽头有个人靠着墙。"},{"s":485.66,"e":492.81,"t":"我走近了才看清——是博文。"},{"s":493.28,"e":506.81,"t":"他也刚回来，校服外套搭在肩上，手里拿着一个杯子。看见我，他站直了身。"},{"s":507.28,"e":509.16,"t":"\"你还没睡？\""},{"s":509.63,"e":518.65,"t":"\"刚洗完。\"他说。然后顿了顿，把手里的杯子递过来。"},{"s":519.12,"e":530.4,"t":"我接过来——是热的。打开盖子，豆浆的甜味散出来。"},{"s":530.87,"e":536.14,"t":"\"你下午没怎么喝东西。\"他说。"},{"s":536.61,"e":555.03,"t":"我愣了一下——下午我确实没喝水，第三节课就开始口干，但我自己都没在意，他竟然注意到了。"},{"s":555.5,"e":557.75,"t":"\"谢谢。\""},{"s":558.22,"e":560.1,"t":"\"嗯。\""},{"s":560.57,"e":595.92,"t":"他没走。我也没走。我们就这么站在走廊尽头，路灯的光从窗户外面照进来，把他的影子拉得很长。夜晚的操场空荡荡的，远处宿舍楼的灯一盏一盏灭下去。"},{"s":596.39,"e":606.91,"t":"我握着那杯豆浆，手指被烫得发麻，但我不想放下。"},{"s":607.38,"e":610.77,"t":"\"林深。\""},{"s":611.24,"e":613.49,"t":"\"嗯？\""},{"s":613.96,"e":616.97,"t":"他侧过头看我。"},{"s":617.44,"e":640.37,"t":"那个距离——不到 30 厘米。我能看见他眼睛里的光，能看见他睫毛的影子投在眼睑上。他张了张嘴，又闭上了。"},{"s":640.84,"e":644.23,"t":"我看见他在咽。"},{"s":644.7,"e":655.23,"t":"不是咽口水的那种咽——是把什么话硬生生压回去的那种咽。"},{"s":655.7,"e":663.21,"t":"他垂在身侧的手握成了拳，又松开。"},{"s":663.68,"e":665.94,"t":"——他在犹豫。"},{"s":666.41,"e":695.74,"t":"博文是一个很少犹豫的人。他不管做什么都是干脆的——拿主意干脆，做题干脆，连吃醋都是直接把话说出来。可每次到了我面前，他就会变得不像他。"},{"s":696.21,"e":699.97,"t":"\"你到底想说什么？\""},{"s":700.44,"e":715.1,"t":"他看我的眼神变了——不是那种\"我在想\"的眼神，而是那种\"我在决定\"的眼神。"},{"s":715.57,"e":719.33,"t":"过了大概 3 秒。"},{"s":719.8,"e":725.06,"t":"他抬起手，握住了我的手腕。"},{"s":725.53,"e":734.93,"t":"那只手是暖的——和那天借笔记时碰到的手指一样暖。"},{"s":735.4,"e":746.68,"t":"他的拇指按在我的脉搏上，用力了一下，然后松开了。"},{"s":747.15,"e":756.93,"t":"\"算了。\"他说，声音低下去，\"我怕。\""},{"s":757.4,"e":760.78,"t":"这回轮到我愣住了。"},{"s":761.25,"e":764.26,"t":"\"你怕什么？\""},{"s":764.73,"e":773,"t":"他没回答。只是转过身，往宿舍走了两步。"},{"s":773.47,"e":776.1,"t":"然后停了下来。"},{"s":776.57,"e":782.59,"t":"\"我怕说出来之后……你不信。\""},{"s":783.06,"e":796.21,"t":"他说这句话的时候没回头。声音比平时小，小到我差点没听清。"},{"s":796.68,"e":800.82,"t":"但走廊太安静了。"},{"s":801.29,"e":810.69,"t":"安静到每一个字都像钉子一样，钉进我耳朵里。"},{"s":811.16,"e":813.42,"t":"\"我信。\""},{"s":813.89,"e":816.89,"t":"我听见自己说。"},{"s":817.36,"e":820.37,"t":"他肩膀动了一下。"},{"s":820.84,"e":824.6,"t":"然后他走进宿舍门了。"},{"s":825.07,"e":831.09,"t":"我站在原地，把那杯豆浆喝完。"},{"s":831.56,"e":833.81,"t":"甜。"},{"s":834.28,"e":837.29,"t":"和上次的一样甜。"},{"s":837.76,"e":841.14,"t":"他记得我喜欢甜的。"},{"s":841.61,"e":850.64,"t":"我一直站在走廊尽头，直到杯子凉了才回去。"},{"s":851.11,"e":866.15,"t":"推门进宿舍的时候，他已经躺下了。我看不见他的脸——他把被角拉过头顶。"},{"s":866.62,"e":872.25,"t":"我轻手轻脚地爬上自己的床。"},{"s":872.72,"e":875.36,"t":"躺下。"},{"s":875.83,"e":878.46,"t":"关了灯。"},{"s":878.93,"e":891.34,"t":"黑暗中，我能听见他的呼吸——不匀，像还没睡着。"},{"s":891.81,"e":894.06,"t":"\"博文。\""},{"s":894.53,"e":896.79,"t":"没有回应。"},{"s":897.26,"e":902.9,"t":"\"我说的是真的。我信你。\""},{"s":903.37,"e":906.37,"t":"安静了很久。"},{"s":906.84,"e":911.73,"t":"久到我以为他已经睡着了。"},{"s":912.2,"e":920.47,"t":"然后——黑暗中传来一声很轻的\"嗯\"。"},{"s":920.94,"e":925.83,"t":"像从被子里闷出来的。"},{"s":926.3,"e":930.06,"t":"我把眼睛闭上。"},{"s":930.53,"e":938.8,"t":"天花板上的月光很淡，淡到几乎看不见。"},{"s":939.27,"e":959.95,"t":"但我脑子里全是走廊尽头他回过头看我的那个表情——那个咽回去的动作，那只握紧又松开的手。"},{"s":960.42,"e":962.68,"t":"他在怕。"},{"s":963.15,"e":966.15,"t":"怕我不信他。"},{"s":966.62,"e":976.02,"t":"不是怕我不喜欢他——是怕我不相信他是认真的。"},{"s":976.49,"e":986.64,"t":"这个认知在我胸口盘了很久，盘到整颗心都是满的。"},{"s":987.11,"e":990.87,"t":"我喜欢他眼睛里的光。"},{"s":991.34,"e":1005.63,"t":"但那一刻我发现——我更喜欢他害怕的时候，还是选择走向我的样子。"}]},{"num":33,"title":"第33章 日常","file":"chapters/ch033.mp3","dur":906.1,"size_mb":13.8,"segs":[{"s":0,"e":16.75,"t":"时间：3 月中旬—4 月初 · 高二下"},{"s":17.86,"e":39.9,"t":"在一起之后，生活并没有发生什么惊天动地的变化。"},{"s":41.01,"e":80.69,"t":"没有每天写情书，没有每天说\"我喜欢你\"，没有那种偶像剧里突然多出来的浪漫桥段。"},{"s":81.79,"e":183.2,"t":"我们还是每天 6 点 40 起床，他先洗好，然后敲一下我的床沿——\"起了\"——然后我们一起去教室。早自习他在前面，我在后面。上课的时候各上各的，偶尔传一张纸条，上面写着\"中午吃什么\"或者\"物理作业第四题答案不对\"。"},{"s":184.3,"e":247.8,"t":"中午有时候一起吃饭，有时候不一起。不一起的时候他会在桌上留一张便利贴——\"帮我去小卖部带一瓶水\"或者\"食堂今天有糖醋排骨\"。"},{"s":248.9,"e":310.63,"t":"晚自习结束后一起走回宿舍。路不长，200 米，够说一天里最重要的几句话——\"明天英语听写你背了吗\"、\"没\"、\"我也没\"。"},{"s":311.73,"e":347.88,"t":"然后回到宿舍，各洗各的，躺在床上，隔着黑暗说几句有的没的，然后睡着。"},{"s":348.99,"e":358.69,"t":"第二天，一样。"},{"s":359.79,"e":370.37,"t":"没有哪一天是特殊的。"},{"s":371.47,"e":382.05,"t":"但每一天都变得不一样了。"},{"s":383.16,"e":393.74,"t":"有一天晚上，熄灯之后。"},{"s":394.84,"e":400.13,"t":"\"小深。\""},{"s":401.23,"e":404.76,"t":"\"嗯？\""},{"s":405.86,"e":432.32,"t":"\"你今天下午那节化学课——老师讲的那个方程式，你听懂了没？\""},{"s":433.42,"e":439.59,"t":"\"听懂了。\""},{"s":440.7,"e":450.4,"t":"\"那你明天早上给我讲一遍。\""},{"s":451.5,"e":460.32,"t":"\"……你上课不是也在吗？\""},{"s":461.42,"e":465.83,"t":"\"走神了。\""},{"s":466.93,"e":472.22,"t":"我笑了一下。"},{"s":473.32,"e":477.73,"t":"\"好。\""},{"s":478.84,"e":486.77,"t":"黑暗中安静了一会儿。"},{"s":487.87,"e":492.28,"t":"\"博文。\""},{"s":493.39,"e":497.8,"t":"\"嗯？\""},{"s":498.9,"e":512.12,"t":"\"你现在走神都这么理直气壮的吗？\""},{"s":513.23,"e":520.28,"t":"他沉默了两秒。"},{"s":521.38,"e":526.68,"t":"\"跟你学的。\""},{"s":527.78,"e":545.41,"t":"有一个周六下午，宿舍只有我们两个人。"},{"s":546.52,"e":594.14,"t":"他在看书，我在写作业。窗外是四月初的阳光——不烈，暖的，照在桌面上，把白纸照得发亮。"},{"s":595.24,"e":613.76,"t":"我写完最后一道题，放下笔，靠在椅背上。"},{"s":614.86,"e":626.32,"t":"他坐在对面，翻了一页书。"},{"s":627.42,"e":633.6,"t":"\"写完了？\""},{"s":634.7,"e":639.99,"t":"\"写完了。\""},{"s":641.09,"e":645.5,"t":"\"那出去走走？\""},{"s":646.6,"e":651.01,"t":"\"去哪？\""},{"s":652.12,"e":661.82,"t":"\"不知道。随便走走。\""},{"s":662.92,"e":745.81,"t":"我们就在校园里走了大概四十分钟。没有目的地，从教学楼走到操场，从操场走到实验楼后面那条种满梧桐树的路。四月的梧桐已经长出了新叶，嫩绿色，在风里轻轻晃。"},{"s":746.91,"e":768.08,"t":"走到那棵最大的梧桐树下面的时候，我停了一下。"},{"s":769.18,"e":774.47,"t":"\"怎么了？\""},{"s":775.57,"e":780.86,"t":"\"没什么。\""},{"s":781.97,"e":816.36,"t":"我只是想起来——高一上的时候，我站在这里，偷偷看他窗户的那个秋天。"},{"s":817.46,"e":825.4,"t":"现在已经春天了。"},{"s":826.5,"e":835.32,"t":"他没问我为什么停下。"},{"s":836.42,"e":849.65,"t":"但他走到我旁边，也停下来了。"},{"s":850.75,"e":864.86,"t":"我们就在那棵梧桐树下站了一会儿。"},{"s":865.96,"e":885.36,"t":"风吹过来的时候，他的肩膀碰到了我的肩膀。"},{"s":886.46,"e":895.28,"t":"然后他说：\"走吧。\""},{"s":896.38,"e":906.08,"t":"我们就继续往前走了。"}]},{"num":34,"title":"第34章 白色光","file":"chapters/ch034.mp3","dur":800.8,"size_mb":12.2,"segs":[{"s":0,"e":9.06,"t":"时间：4 月 15 日—5 月 10 日 · 高二下"},{"s":9.53,"e":12.55,"t":"4 月 15 日"},{"s":13.02,"e":21.69,"t":"在一起一个半月之后，他带我上了第二次天台。"},{"s":22.17,"e":37.64,"t":"这一次和第一次不一样。第一次是二月的下午，阳光把整片天台染成橘色的。"},{"s":38.11,"e":65.65,"t":"今天是四月。午后的太阳很高，从天顶直直地照下来——没有橘色，没有暖调。光是白色的，把天台的地面照得发亮。"},{"s":66.12,"e":71.78,"t":"他用钥匙打开铁门，走出去。"},{"s":72.25,"e":77.16,"t":"我跟着他，走到天台中央。"},{"s":77.63,"e":104.42,"t":"他把天台的地面切成了一半亮、一半暗——从围栏到中间有一条笔直的分界线，亮的那边是阳光，暗的那边是楼的影子。"},{"s":104.89,"e":111.3,"t":"他站在亮的那边，面对着我。"},{"s":111.78,"e":117.06,"t":"\"你以后每天下午 4 点半来天台。\""},{"s":117.53,"e":120.17,"t":"他说。"},{"s":120.64,"e":122.53,"t":"\"……为什么？\""},{"s":123,"e":128.66,"t":"\"因为天台安静。适合讲题。\""},{"s":129.13,"e":132.53,"t":"\"在教室也能讲。\""},{"s":133,"e":135.64,"t":"\"教室太吵。\""},{"s":136.11,"e":138,"t":"他顿了顿。"},{"s":138.47,"e":144.88,"t":"\"而且——天台只有我能上来。\""},{"s":145.35,"e":151.39,"t":"后半句他说得比前半句轻一点。"},{"s":151.86,"e":155.26,"t":"但我听得很清楚。"},{"s":155.73,"e":157.62,"t":"\"……好。\""},{"s":158.09,"e":165.26,"t":"他点了点头，然后往围栏那边走了一步。"},{"s":165.73,"e":168.37,"t":"\"还有——\""},{"s":168.84,"e":171.11,"t":"\"嗯？\""},{"s":171.58,"e":176.1,"t":"\"高考完，我带你去一个地方。\""},{"s":176.58,"e":178.46,"t":"\"什么地方？\""},{"s":178.93,"e":182.33,"t":"\"到时候你就知道了。\""},{"s":182.8,"e":194.88,"t":"他没有看我。他站在白色光里，微微眯着眼，看着远处的城市。"},{"s":195.35,"e":199.5,"t":"我在影子这边看着他。"},{"s":199.97,"e":201.86,"t":"\"很远吗？\""},{"s":202.33,"e":204.97,"t":"\"不远。\""},{"s":205.44,"e":208.08,"t":"\"要走很久？\""},{"s":208.55,"e":211.19,"t":"\"不会。\""},{"s":211.67,"e":214.31,"t":"他侧过头来。"},{"s":214.78,"e":217.42,"t":"\"你跟着我就行。\""},{"s":217.89,"e":220.53,"t":"4 月 16 日"},{"s":221,"e":226.66,"t":"第二天下午 4 点半，我上了天台。"},{"s":227.13,"e":229.4,"t":"他已经在了。"},{"s":229.87,"e":249.11,"t":"我走到他旁边的时候，注意到一个细节——从这个角度看过去，刚好能看见 611 班走廊的那扇窗户。"},{"s":249.58,"e":252.23,"t":"反光玻璃。"},{"s":252.7,"e":260.24,"t":"快两年了。那扇窗户还在那里。"},{"s":260.71,"e":266.75,"t":"高一上的时候，我站在那里看他。"},{"s":267.22,"e":280.43,"t":"现在我和他站在同一个天台上，看着他高一上坐着的那间教室的窗户。"},{"s":280.9,"e":286.56,"t":"从那里到这里——走了快两年。"},{"s":287.03,"e":289.3,"t":"\"你在看什么？\""},{"s":289.77,"e":294.29,"t":"他的声音从旁边传来。"},{"s":294.77,"e":297.41,"t":"\"看那扇窗户。\""},{"s":297.88,"e":303.54,"t":"我指了指 611 班的走廊。"},{"s":304.01,"e":321.74,"t":"他看了一眼，然后说：\"我高一上的时候，每天晚上从 610 班的窗户看你从走廊走过去。\""},{"s":322.21,"e":325.23,"t":"我转过头看他。"},{"s":325.7,"e":327.59,"t":"\"你——\""},{"s":328.06,"e":347.68,"t":"\"你走路的步子很快。像有什么急事。但走到走廊中间的时候会慢下来——大概是走到我窗户正对着的位置。\""},{"s":348.15,"e":354.19,"t":"他说这话的时候语气很平。"},{"s":354.66,"e":360.32,"t":"\"我每天都在等你走到那个位置。\""},{"s":360.79,"e":366.45,"t":"风把他前额的头发吹乱了一点。"},{"s":366.92,"e":369.94,"t":"他伸手理了一下。"},{"s":370.41,"e":377.21,"t":"\"然后你走过去之后，我就继续写题了。\""},{"s":377.68,"e":390.13,"t":"我站在天台的光里，四月午后的风从耳边吹过去。"},{"s":390.6,"e":400.41,"t":"高一上每天晚上——我以为我是一个人在走廊上走。"},{"s":400.88,"e":406.92,"t":"但他每天都在窗户后面看着。"},{"s":407.39,"e":410.03,"t":"5 月 10 日"},{"s":410.5,"e":418.8,"t":"第四次上天台的那天，天气已经有点热了。"},{"s":419.28,"e":433.24,"t":"我走上去的时候，他已经到了。靠在围栏上，手里拎着一瓶水——给我的。"},{"s":433.71,"e":439.74,"t":"我接过来，拧开盖子喝了一口。"},{"s":440.22,"e":465.12,"t":"我选了对面的座位——他们那一桌在靠窗位置。教学楼后面的梧桐树已经绿了，阳光通过树叶洒下来，在桌面上亮一块、暗一块。"},{"s":465.59,"e":468.61,"t":"\"小深。\""},{"s":469.08,"e":470.97,"t":"\"嗯？\""},{"s":471.44,"e":476.34,"t":"他走过来，站到我面前。"},{"s":476.81,"e":482.85,"t":"近——比平时近。"},{"s":483.32,"e":497.66,"t":"近到我甚至能看见他锁骨上方有一颗很小的痣——我之前从来没注意过。"},{"s":498.13,"e":500.77,"t":"他低下头。"},{"s":501.24,"e":505.39,"t":"然后他吻了我。"},{"s":505.87,"e":523.98,"t":"很短——大概两秒。他的嘴唇碰到我的嘴唇，凉的，带着一点薄荷糖的味道。"},{"s":524.45,"e":527.84,"t":"然后他退开了。"},{"s":528.31,"e":532.84,"t":"站在那里，看着我。"},{"s":533.31,"e":540.86,"t":"脸上没有表情——但他的耳尖是红的。"},{"s":541.33,"e":543.22,"t":"\"你生气吗？\""},{"s":543.69,"e":545.58,"t":"他问。"},{"s":546.05,"e":548.31,"t":"我愣了一下。"},{"s":548.78,"e":550.67,"t":"\"……不生气。\""},{"s":551.14,"e":560.57,"t":"然后他笑了——嘴角往上，眼睛底下那一块皱了一下。"},{"s":561.05,"e":564.06,"t":"1 厘米的皱。"},{"s":564.54,"e":574.35,"t":"我看着他那个皱——忽然在那一刻知道了一件事："},{"s":574.82,"e":581.23,"t":"我这辈子，想一直看到这个皱。"},{"s":581.7,"e":588.87,"t":"那天晚上，我在走廊上碰见了周海。"},{"s":589.34,"e":604.44,"t":"他很久没主动跟我说话了——不是疏远，是高三大家各忙各的，碰面的机会本来就少。"},{"s":604.91,"e":610.19,"t":"但那天他在走廊上拦住了我。"},{"s":610.66,"e":612.55,"t":"\"林深。\""},{"s":613.02,"e":614.53,"t":"\"嗯？\""},{"s":615,"e":618.77,"t":"\"你每天看博文几次？\""},{"s":619.24,"e":623.02,"t":"我没想到他会问这个。"},{"s":623.49,"e":626.13,"t":"\"……干嘛？\""},{"s":626.6,"e":629.24,"t":"\"我帮你算了一下。\""},{"s":629.71,"e":641.79,"t":"他从口袋里掏出一张皱巴巴的纸——上面用铅笔画了几个正字。"},{"s":642.26,"e":654.33,"t":"\"你今天看了他大概 24 次。午休最密集——13 分钟里抬头 8 次。\""},{"s":654.8,"e":657.07,"t":"我愣住了。"},{"s":657.54,"e":661.69,"t":"\"你——你数这个干嘛？\""},{"s":662.16,"e":666.69,"t":"\"因为我想让你知道一件事。\""},{"s":667.16,"e":670.56,"t":"他把那张纸翻过来。"},{"s":671.03,"e":688.76,"t":"背面的左上角也画了几个正字——笔迹和前面的不一样。更用力一些，字压得更深。"},{"s":689.23,"e":692.63,"t":"\"这是他看你的次数。\""},{"s":693.1,"e":694.99,"t":"他顿了顿。"},{"s":695.46,"e":725.27,"t":"\"上周末晚自习后我找他聊天，闲聊的时候说起来了。他说他每天晚上回教室拿东西的时候，会在 610 班窗户那里站一会儿——看你从 611 班走廊走过去。\""},{"s":725.74,"e":732.15,"t":"\"他说——高一上到现在，习惯了。\""},{"s":732.62,"e":738.66,"t":"我把那张纸从周海手里接过来。"},{"s":739.13,"e":752.34,"t":"那张纸上，他看我的次数，比我看他的次数——多一行正字。"},{"s":752.81,"e":760.35,"t":"晚上我在宿舍里，把那行正字数了一遍。"},{"s":760.83,"e":771.39,"t":"然后我把它折好，放进了那个深蓝色本子的最后一页里。"},{"s":771.86,"e":778.65,"t":"并排，和他写的最后一页在一起。"},{"s":779.13,"e":786.67,"t":"高一上到现在——他看我，我也看他。"},{"s":787.14,"e":790.54,"t":"不只是窗户那边。"},{"s":791.01,"e":794.03,"t":"不只是天台上。"},{"s":794.5,"e":800.91,"t":"是每一个他没说出口的时刻。"}]},{"num":35,"title":"第35章 暑假","file":"chapters/ch035.mp3","dur":949.2,"size_mb":14.5,"segs":[{"s":0,"e":27.93,"t":"时间：7 月—8 月 · 高二升高三的夏天"},{"s":29.05,"e":40.76,"t":"暑假我没有回家。"},{"s":41.89,"e":86.93,"t":"我跟家里说要补课——其实学校确实有补课，但不是天天有。大多数时候，我一个人待在宿舍里做卷子。"},{"s":88.06,"e":95.26,"t":"他也留下来了。"},{"s":96.39,"e":161.25,"t":"他回家的时间比我更短——回去住了十天，然后就回来了。他回来那天下午，我正趴在桌上做英语阅读，听到门锁咔嗒响了一声。"},{"s":162.37,"e":175.89,"t":"他推门进来，手里拎着一个袋子。"},{"s":177.01,"e":182.42,"t":"\"你怎么回来了？\""},{"s":183.54,"e":188.05,"t":"\"补课。\""},{"s":189.17,"e":199.98,"t":"\"补课不是下周才开始吗？\""},{"s":201.11,"e":220.03,"t":"他把袋子放到桌上，从里面掏出一瓶酸奶。"},{"s":221.15,"e":228.36,"t":"\"提前回来不行吗。\""},{"s":229.49,"e":238.49,"t":"他把酸奶放到我桌上。"},{"s":239.62,"e":245.03,"t":"冰的。"},{"s":246.15,"e":271.37,"t":"外面三十七度的天，他把酸奶从家里带到了学校。"},{"s":272.5,"e":283.31,"t":"那个暑假过得格外慢。"},{"s":284.44,"e":354.7,"t":"每天早上我们一起去教室——整栋教学楼只有高三的楼层有人，走廊安静得能听见电扇转动的声音。我们把桌子并到一起，面对面坐着，各做各的卷子。"},{"s":355.83,"e":368.44,"t":"做到累了，就抬头看一眼对方。"},{"s":369.56,"e":387.58,"t":"有时候他先抬头，有时候我先。"},{"s":388.71,"e":404.92,"t":"如果目光碰上了，他就说：\"休息一下。\""},{"s":406.05,"e":438.48,"t":"然后我们趴在同一张桌子上，面对面，不说话，闭着眼睛。"},{"s":439.6,"e":452.22,"t":"电扇在头顶嗡嗡地转。"},{"s":453.34,"e":468.66,"t":"夏天的热气从窗户外面涌进来。"},{"s":469.78,"e":520.23,"t":"但那个画面——他闭着眼睛，睫毛垂下来，呼吸平稳——我觉得比任何一道我做对的题都重要。"},{"s":521.35,"e":534.87,"t":"有一天傍晚，太阳快落山了。"},{"s":535.99,"e":592.75,"t":"我们从教室出来，沿着操场走了几圈。操场上没什么人，夕阳把整片天空染成一层一层的橘色——从深到浅，从近到远。"},{"s":593.87,"e":609.19,"t":"走到第三圈的时候，他忽然开口了。"},{"s":610.31,"e":615.72,"t":"\"小深。\""},{"s":616.84,"e":622.25,"t":"\"嗯？\""},{"s":623.37,"e":630.58,"t":"\"你想考哪个大学？\""},{"s":631.71,"e":639.81,"t":"我脚步慢了一下。"},{"s":640.94,"e":644.54,"t":"\"还没想好。\""},{"s":645.67,"e":696.12,"t":"这是假话。我想过——我想过很多次。但我每次想到这个问题，都会先想到一个前提：他要考哪所。"},{"s":697.24,"e":700.84,"t":"\"你呢？\""},{"s":701.97,"e":709.18,"t":"\"我在看江大。\""},{"s":710.3,"e":732.82,"t":"——江城大学。省内的重点一本。物理系还不错。"},{"s":733.95,"e":739.35,"t":"\"物理系？\""},{"s":740.48,"e":745.89,"t":"\"嗯。\""},{"s":747.01,"e":752.42,"t":"他顿了顿。"},{"s":753.54,"e":762.55,"t":"\"你也考虑一下江大。\""},{"s":763.68,"e":802.41,"t":"他说这句话的时候，目光落在远处的地平线上，夕阳把他的脸照成温暖的橘色。"},{"s":803.54,"e":816.15,"t":"\"你计科或者什么，江大都有。\""},{"s":817.28,"e":822.68,"t":"我没说话。"},{"s":823.81,"e":856.24,"t":"但那天晚上，我回到宿舍之后，打开了手机，查了一晚上的江城大学。"},{"s":857.36,"e":881.69,"t":"录取分数线。专业设置。校区位置。"},{"s":882.81,"e":900.83,"t":"然后我关掉手机，在黑暗里躺了很久。"},{"s":901.95,"e":910.96,"t":"他在对面床上翻了个身。"},{"s":912.09,"e":916.59,"t":"\"还没睡？\""},{"s":917.72,"e":923.12,"t":"\"……快了。\""},{"s":924.25,"e":930.56,"t":"我闭上眼睛。"},{"s":931.68,"e":935.29,"t":"江大。"},{"s":936.41,"e":941.82,"t":"他在。"},{"s":942.94,"e":949.25,"t":"我也在。"}]},{"num":36,"title":"第36章 金色标","file":"chapters/ch036.mp3","dur":1064.8,"size_mb":16.2,"segs":[{"s":0,"e":17.59,"t":"时间：9 月 1 日（周一）· 高三第一天"},{"s":18.47,"e":21.99,"t":"高三。"},{"s":22.87,"e":45.39,"t":"这两个字写在黑板上、贴在走廊墙上、印在每个人的表情里。"},{"s":46.27,"e":91.31,"t":"开学第一天，整个年级弥漫着一种说不清的紧张感——像所有人都在同一时刻意识到了一个事实：该来的，终于来了。"},{"s":92.19,"e":107.67,"t":"我站在教学楼门口的告示牌前，看分班表。"},{"s":108.55,"e":147.25,"t":"不用找——我的名字在第 12 行，理科（物化生）组合，高三 3 班。博文在同一个班，名单上隔了 7 行。"},{"s":148.13,"e":208.65,"t":"理科班的人数少了很多——选文科的人走了一大批，留下来的都是选了物化生的。课程表发下来的时候我扫了一眼——物理、化学、生物几乎每天都有，数学排在一三五大早上。"},{"s":209.53,"e":215.16,"t":"同一间教室。"},{"s":216.04,"e":222.37,"t":"同一张课表。"},{"s":223.25,"e":228.18,"t":"同一个方向。"},{"s":229.06,"e":233.28,"t":"\"林深。\""},{"s":234.16,"e":257.38,"t":"午休的时候，周海从教室门口探进头来，\"你猜你这次排多少？\""},{"s":258.26,"e":262.49,"t":"\"什么排名？\""},{"s":263.37,"e":278.85,"t":"\"期末分班考的总榜。贴出来了，在年级公告栏。\""},{"s":279.73,"e":296.62,"t":"我走过去。公告栏前面围了好几个人，我挤进去——"},{"s":297.5,"e":303.13,"t":"白纸黑字。"},{"s":304,"e":317.38,"t":"第一名到第三百名，按分数排下来的。"},{"s":318.25,"e":324.59,"t":"我在第 89 行。"},{"s":325.47,"e":331.1,"t":"89 名。"},{"s":331.98,"e":341.13,"t":"我盯着那个数字看了三遍。"},{"s":342.01,"e":370.86,"t":"第一遍是\"看错了\"，第二遍是\"真的是我\"，第三遍是——心跳突然快了起来。"},{"s":371.74,"e":399.18,"t":"高一上我连前 300 都进不去。高一下我挤进 200。高二上我冲到 132。"},{"s":400.06,"e":405.69,"t":"现在 89。"},{"s":406.57,"e":429.09,"t":"\"前一百了！\"周海在我旁边喊了一声，\"看见没？金色标！\""},{"s":429.97,"e":467.27,"t":"他指的是公告栏上的标记——前 100 名的名字前面，贴了一个小小的金色圆标。不多，就在最前面那一列。"},{"s":468.15,"e":476.59,"t":"我的名字前面也有一个。"},{"s":477.47,"e":492.95,"t":"我伸出手指碰了一下那个标——贴得挺牢的。"},{"s":493.83,"e":524.09,"t":"回到教室的时候，博文已经坐在座位上了。他在看书，听见我的脚步声没抬头，但问了一句："},{"s":524.97,"e":529.19,"t":"\"看见排名了？\""},{"s":530.07,"e":534.3,"t":"\"看见了。\""},{"s":535.17,"e":538.69,"t":"\"多少？\""},{"s":539.57,"e":545.2,"t":"\"89。\""},{"s":546.08,"e":553.82,"t":"他翻书的手停了一下。"},{"s":554.7,"e":564.55,"t":"然后抬起头来看我。"},{"s":565.43,"e":607.66,"t":"那个眼神——我不知道怎么形容。不是\"意料之中\"的平淡，也不是\"你太棒了\"的那种激动。他看了我大概 3 秒，然后说："},{"s":608.54,"e":621.2,"t":"\"你按这个速度——12 月能进 50。\""},{"s":622.08,"e":639.68,"t":"他说这句话的时候语气很平，像在陈述一个事实。"},{"s":640.56,"e":663.07,"t":"但我注意到他的嘴角往上翘了一下——不到 1 厘米，但我看见了。"},{"s":663.95,"e":682.25,"t":"我低下头，假装在找书，不让他看见我在笑。"},{"s":683.13,"e":692.98,"t":"\"89 名，你那是什么表情？\""},{"s":693.86,"e":712.16,"t":"下午最后一节自习课，周海坐到我旁边，歪着头看我。"},{"s":713.04,"e":719.37,"t":"\"什么什么表情？\""},{"s":720.25,"e":729.4,"t":"\"一副'好像还不够'的表情。\""},{"s":730.28,"e":735.91,"t":"\"我没说不够。\""},{"s":736.79,"e":744.53,"t":"\"你脸上写了：不够。\""},{"s":745.41,"e":749.63,"t":"我不说话了。"},{"s":750.51,"e":806.81,"t":"周海说的是对的。89 名，年级前 100，金色标——这些东西放一年前我会高兴到跳起来。但现在坐在这个教室里，我知道 89 名意味着什么。"},{"s":807.69,"e":818.24,"t":"意味着我可以够到一本线了。"},{"s":819.12,"e":823.35,"t":"但还不够。"},{"s":824.23,"e":842.52,"t":"因为博文在 47 名——比我高 42 个名次。"},{"s":843.4,"e":851.14,"t":"我到现在还追不上他。"},{"s":852.02,"e":859.06,"t":"我把头埋进胳膊里。"},{"s":859.94,"e":903.57,"t":"\"行了。\"周海的声音从旁边飘过来，\"你从 300+ 追到 89，用了一年半。剩下的 42 个名次——你还有一整年。\""},{"s":904.45,"e":907.97,"t":"我没回答。"},{"s":908.85,"e":916.59,"t":"但我在心里说了一句话："},{"s":917.47,"e":925.91,"t":"一整年。够了。"},{"s":926.79,"e":936.64,"t":"晚自习结束，我收拾书包。"},{"s":937.52,"e":955.82,"t":"一盒牛奶被放在我的桌角上——不是我的。"},{"s":956.7,"e":981.33,"t":"我抬头——博文已经走到门口了。他没回头，只往后扬了一下手。"},{"s":982.21,"e":1001.91,"t":"我拿起那盒牛奶，看到上面贴了一张便利贴，是他的字："},{"s":1002.79,"e":1009.83,"t":"> 前 100 了。继续。"},{"s":1010.71,"e":1037.45,"t":"三个字加一个句号——不是感叹号。是他一贯的风格，不多写一个多余的字。"},{"s":1038.33,"e":1051.7,"t":"我把便利贴撕下来，折好，放进笔袋里。"},{"s":1052.58,"e":1058.91,"t":"然后把牛奶喝完。"},{"s":1059.79,"e":1064.72,"t":"甜的。"}]},{"num":37,"title":"第37章 最后一年","file":"chapters/ch037.mp3","dur":892.8,"size_mb":13.6,"segs":[{"s":0,"e":8.91,"t":"时间：9 月—次年 5 月 · 高三"},{"s":9.47,"e":17.04,"t":"高三的日子过得既快又慢。"},{"s":17.6,"e":48.35,"t":"快的是每天——早自习、第一节课、第二节课、午休、下午课、晚自习、回宿舍。像一个循环，还没反应过来，一周就过去了。"},{"s":48.9,"e":80.98,"t":"慢的是整个人——你总觉得六月八号永远不会来。黑板上的倒计时一天一天地减，但当你盯着那个数字的时候，它好像根本没在动。"},{"s":81.54,"e":87.78,"t":"博文和我坐在同一间教室。"},{"s":88.34,"e":97.69,"t":"但高三之后，我们说话的时间反而变少了。"},{"s":98.25,"e":108.05,"t":"不是因为关系变了——是因为太累了。"},{"s":108.61,"e":147.82,"t":"每天早上我到教室的时候，他已经在了。桌上一杯豆浆，和以前一样。他有时候抬头看我一眼，有时候不抬——不是不想看，是连抬头的力气都想省下来留给做题。"},{"s":148.38,"e":150.61,"t":"我也一样。"},{"s":151.16,"e":157.4,"t":"我们之间最常说的话变成了："},{"s":157.96,"e":161.08,"t":"\"这题你做了吗？\""},{"s":161.64,"e":163.42,"t":"\"做了。\""},{"s":163.97,"e":166.65,"t":"\"答案多少？\""},{"s":167.2,"e":170.77,"t":"\"我选C。你呢？\""},{"s":171.33,"e":174,"t":"\"我也选C。\""},{"s":174.56,"e":179.46,"t":"然后继续低头做题。"},{"s":180.02,"e":186.25,"t":"十月中旬有一次模拟考。"},{"s":186.81,"e":205.97,"t":"成绩出来那天，我在公告栏上找了很久才找到自己的名字——73 名。"},{"s":206.53,"e":210.09,"t":"比上次进步了。"},{"s":210.65,"e":219.12,"t":"但我往上看的时候，看见他在 41 名。"},{"s":219.67,"e":221.9,"t":"41。"},{"s":222.46,"e":227.8,"t":"中间隔着 32 个人。"},{"s":228.36,"e":250.64,"t":"那天晚自习我没有去找他——我一个人坐在座位上，把错题本翻出来，把那套卷子重新做了一遍。"},{"s":251.2,"e":260.55,"t":"做到一半的时候，一张便利贴被推到我桌上。"},{"s":261.11,"e":263.78,"t":"他的字："},{"s":264.34,"e":268.8,"t":"\"73 了。继续。\""},{"s":269.35,"e":279.16,"t":"我抬头——他坐在前面几排，没有回头。"},{"s":279.71,"e":288.18,"t":"我低下头，把那三个字又看了一遍。"},{"s":288.74,"e":294.53,"t":"然后拿起笔，继续做题。"},{"s":295.09,"e":305.78,"t":"冬天的时候，晚自习结束后天已经完全黑了。"},{"s":306.34,"e":316.59,"t":"我们走在回宿舍的路上，呼出的气变成白雾。"},{"s":317.14,"e":350.56,"t":"那段时间我的数学遇到了瓶颈——不管怎么做，分数就是卡在 110 上不去。有一天晚上我趴在桌上，盯着面前那张卷子，一个字都不想写。"},{"s":351.12,"e":356.91,"t":"他走过来，在我旁边坐下了。"},{"s":357.47,"e":360.14,"t":"\"哪题不会？\""},{"s":360.7,"e":366.49,"t":"\"不是不会——是烦。\""},{"s":367.05,"e":387.1,"t":"他没说话。坐了一会儿，然后站起来，走出去。过了一会儿他回来了，手里拿着两杯热水。"},{"s":387.66,"e":395.23,"t":"他把一杯放到我面前，然后坐下来。"},{"s":395.79,"e":398.46,"t":"\"那就不做了。\""},{"s":399.02,"e":401.69,"t":"\"……什么？\""},{"s":402.25,"e":410.27,"t":"\"今天不做了。明天再做。又不会跑。\""},{"s":410.83,"e":413.5,"t":"我看着他。"},{"s":414.06,"e":433.66,"t":"他没有说\"你再坚持一下\"或者\"这道题不难你再想想\"。他说的是\"今天不做了\"。"},{"s":434.22,"e":442.69,"t":"我握着那杯热水，手指被烫得发麻。"},{"s":443.24,"e":448.59,"t":"然后我合上了卷子。"},{"s":449.15,"e":461.18,"t":"那是高三上学期我唯一一次在晚自习结束前合上卷子。"},{"s":461.73,"e":467.97,"t":"但那一晚，我睡得很好。"},{"s":468.53,"e":474.77,"t":"三月份的时候有一次体检。"},{"s":475.33,"e":497.16,"t":"量身高体重的时候，我站上去，发现我长高了一点——173 了。高一的时候我才 170。"},{"s":497.72,"e":503.06,"t":"他站在旁边等我的数据。"},{"s":503.62,"e":506.74,"t":"\"多少？\""},{"s":507.3,"e":509.97,"t":"\"173。你呢？\""},{"s":510.53,"e":514.98,"t":"\"168。\""},{"s":515.54,"e":521.78,"t":"我说：\"你是不是也长了？\""},{"s":522.33,"e":528.13,"t":"\"没。我还是高一那个数。\""},{"s":528.68,"e":536.26,"t":"我说：\"那你以后要抬头看我了。\""},{"s":536.82,"e":539.49,"t":"他看了我一眼。"},{"s":540.05,"e":559.21,"t":"那个眼神——不是\"你完了\"也不是\"你等着\"——是那种\"你尽管说，我有的是办法\"的眼神。"},{"s":559.76,"e":570.01,"t":"然后他说：\"那又怎样。我低头看你也能看。\""},{"s":570.57,"e":574.58,"t":"旁边的人没听懂。"},{"s":575.14,"e":578.7,"t":"但我听懂了。"},{"s":579.26,"e":589.06,"t":"五月份的时候，教室里的气氛变得越来越紧。"},{"s":589.62,"e":607.44,"t":"有人开始失眠，有人在课间趴在桌上就能睡着，有人吃着吃着饭突然哭了。"},{"s":608,"e":619.14,"t":"我看着那个人被同学围着安慰，心里也跟着紧了一下。"},{"s":619.69,"e":625.49,"t":"博文顺着我的目光看了一眼。"},{"s":626.04,"e":631.39,"t":"然后他低下头，继续吃饭。"},{"s":631.95,"e":635.96,"t":"\"你晚上睡得好吗？\""},{"s":636.51,"e":638.3,"t":"他问。"},{"s":638.85,"e":640.64,"t":"\"还行。\""},{"s":641.19,"e":643.87,"t":"\"真的？\""},{"s":644.42,"e":647.54,"t":"\"……有时候会醒。\""},{"s":648.1,"e":654.34,"t":"他夹了一筷子菜，放到我碗里。"},{"s":654.89,"e":659.35,"t":"\"考不上江大也没关系。\""},{"s":659.91,"e":662.58,"t":"他说。"},{"s":663.14,"e":668.49,"t":"我握着筷子的手停了一下。"},{"s":669.04,"e":671.72,"t":"\"你说什么？\""},{"s":672.27,"e":679.4,"t":"\"我说——考不上也没关系。\""},{"s":679.96,"e":687.53,"t":"他嚼了一口饭，咽下去，才继续说。"},{"s":688.09,"e":696.56,"t":"\"江大不是唯一的选择。你努力过了就行。\""},{"s":697.11,"e":699.34,"t":"我看着他。"},{"s":699.9,"e":703.02,"t":"他没有看我。"},{"s":703.57,"e":716.5,"t":"但他说这句话的时候，筷子上夹着的那块肉，放到了我的碗里。"},{"s":717.05,"e":725.97,"t":"那天晚上，我睡得比前几天都安稳。"},{"s":726.52,"e":739.89,"t":"倒计时变成 30 天的时候，学校给高三放了一下午的假。"},{"s":740.45,"e":751.14,"t":"大部分人回家了。我没回——我在教室做卷子。"},{"s":751.7,"e":757.94,"t":"做到一半的时候，他走进来。"},{"s":758.49,"e":762.5,"t":"手里拎着两瓶水。"},{"s":763.06,"e":766.18,"t":"\"你怎么回来了？\""},{"s":766.74,"e":770.3,"t":"\"你不是也没走吗。\""},{"s":770.86,"e":781.55,"t":"他把一瓶水放在我桌上，然后坐到他自己的位置上。"},{"s":782.11,"e":803.5,"t":"教室里只有我们两个人。电扇在转，窗外的风吹进来，把桌上的试卷吹得微微掀起来。"},{"s":804.05,"e":833.02,"t":"他坐下来之后没做题。他拿了一本书出来——不是课本，是那本封面上有深蓝色和小树的、他已经很久没拿出来的本子。"},{"s":833.57,"e":844.71,"t":"我看见他翻开最后一页，拿起笔，写了几行字。"},{"s":845.27,"e":849.28,"t":"然后合上了。"},{"s":849.84,"e":852.96,"t":"我问他写什么了。"},{"s":853.51,"e":856.19,"t":"他没回答。"},{"s":856.74,"e":873.23,"t":"但后来——很久以后——我翻到那一页的时候，看见了那行字："},{"s":873.79,"e":892.95,"t":"\"2026/5/8 距离高考还有 30 天。 小深还在做题。 我也还在。 我们都会好的。\""}]},{"num":38,"title":"第38章 围墙外的城市","file":"chapters/ch038.mp3","dur":571.5,"size_mb":8.7,"segs":[{"s":0,"e":14.55,"t":"时间：6 月 6 日—8 日 · 高考"},{"s":15.15,"e":18.55,"t":"6 月 6 日"},{"s":19.15,"e":31.76,"t":"高考前夜，我坐在宿舍床上，面前摊着五套卷子。"},{"s":32.36,"e":56.12,"t":"不是临时抱佛脚——是把做过的卷子再过一遍。对一下答案，确认自己不会在同一个地方再错一次。"},{"s":56.73,"e":64,"t":"他坐在对面床，也在看卷子。"},{"s":64.61,"e":70.91,"t":"房间里只有翻纸的声音。"},{"s":71.52,"e":78.31,"t":"过了一阵子，他抬头看了我一眼。"},{"s":78.91,"e":81.82,"t":"\"看得进去吗？\""},{"s":82.43,"e":85.82,"t":"\"……看不进去。\""},{"s":86.43,"e":89.34,"t":"\"那别看了。\""},{"s":89.94,"e":99.16,"t":"他站起来，把我手里的卷子抽走，放到桌上。"},{"s":99.76,"e":103.16,"t":"\"出去走走。\""},{"s":103.76,"e":127.52,"t":"我们走到操场，坐在跑道旁边的长椅上。六月的晚上不冷不热，风带着白天晒过的草地气味。"},{"s":128.13,"e":163.52,"t":"围墙外面的城市亮着灯。远处高楼的轮廓在天际线上连成一片，近处是居民楼的窗户，一格一格的，有的亮着灯，有的没有。"},{"s":164.13,"e":177.22,"t":"他坐在我旁边，两只手搭在膝盖上，看着围墙外面。"},{"s":177.82,"e":181.22,"t":"\"明天就考了。\""},{"s":181.82,"e":184.73,"t":"\"嗯。\""},{"s":185.34,"e":188.73,"t":"\"紧张吗？\""},{"s":189.34,"e":192.73,"t":"\"有一点。\""},{"s":193.34,"e":196.25,"t":"他点了点头。"},{"s":196.86,"e":200.25,"t":"\"我也有一点。\""},{"s":200.86,"e":205.7,"t":"然后他就不说话了。"},{"s":206.31,"e":238.31,"t":"我们坐在那里，看着围墙外面的城市。围墙不高——两米左右。上面爬着一些不知名的藤蔓植物，风一吹，叶子轻轻晃动。"},{"s":238.92,"e":246.19,"t":"高一的时候，我站在走廊上看他。"},{"s":246.8,"e":256.01,"t":"高二的时候，我们坐在天台上看城市。"},{"s":256.62,"e":268.74,"t":"现在高三了，我们坐在操场上看围墙外面的灯。"},{"s":269.34,"e":276.62,"t":"位置在变，旁边的人没变。"},{"s":277.22,"e":280.13,"t":"\"小深。\""},{"s":280.74,"e":283.16,"t":"\"嗯？\""},{"s":283.77,"e":290.07,"t":"\"你还记得天台上的颜色吗？\""},{"s":290.68,"e":294.07,"t":"\"橘色的。\""},{"s":294.68,"e":306.8,"t":"\"嗯。\"他点了点头。\"橘色是 2 月 11 日的颜色。\""},{"s":307.41,"e":320.01,"t":"2 月 11 日——那是表白之后、我们正式在一起的日子。"},{"s":320.62,"e":323.53,"t":"他记得。"},{"s":324.13,"e":329.47,"t":"他把那天的颜色记住了。"},{"s":330.07,"e":336.86,"t":"\"考完之后——我带你去一个地方。\""},{"s":337.47,"e":341.35,"t":"\"上次你说过了。\""},{"s":341.95,"e":349.71,"t":"\"我知道。再说一次，怕你忘了。\""},{"s":350.32,"e":353.71,"t":"\"我没忘。\""},{"s":354.32,"e":358.68,"t":"他又安静了一会儿。"},{"s":359.29,"e":364.13,"t":"然后他说：\"那就好。\""},{"s":364.74,"e":368.13,"t":"6 月 7 日"},{"s":368.74,"e":374.07,"t":"语文。数学。"},{"s":374.68,"e":387.77,"t":"考完数学出来的时候，太阳正烈。我站在考场楼下等他。"},{"s":388.38,"e":404.86,"t":"他从楼梯上走下来——看见我的时候，脚步没停，但嘴角动了一下。"},{"s":405.47,"e":407.89,"t":"\"怎么样？\""},{"s":408.5,"e":426.92,"t":"\"语文 130 应该稳的。数学——最后一道大题写了一半。\""},{"s":427.53,"e":430.44,"t":"\"我也差不多。\""},{"s":431.05,"e":442.2,"t":"和我们一起备考的每一天一样——\"我也差不多\"。"},{"s":442.8,"e":451.53,"t":"站在同一片太阳下，往同一个方向走。"},{"s":452.14,"e":456.5,"t":"6 月 8 日"},{"s":457.11,"e":462.44,"t":"理综。英语。"},{"s":463.05,"e":490.68,"t":"考完英语的那个下午，我从考场走出来。阳光还是和昨天一样烈，但比昨天轻了一些——因为我知道这是最后一科了。"},{"s":491.29,"e":494.68,"t":"他在门口等我。"},{"s":495.29,"e":508.87,"t":"站在教学楼前面那棵樟树下面。手插在校服口袋里。"},{"s":509.47,"e":516.75,"t":"看见我出来了，他站直了身子。"},{"s":517.35,"e":521.72,"t":"所有科目都考完了。"},{"s":522.32,"e":532.5,"t":"十二年的书，两天的卷子，全部结束了。"},{"s":533.11,"e":538.44,"t":"他看着我，我也看着他。"},{"s":539.05,"e":541.47,"t":"\"你跟我来。\""},{"s":542.08,"e":544.02,"t":"他说。"},{"s":544.63,"e":553.35,"t":"然后他转身，往教学楼的方向走了。"},{"s":553.96,"e":557.35,"t":"我跟上去。"},{"s":557.96,"e":561.35,"t":"没有问去哪。"},{"s":561.96,"e":571.66,"t":"因为我知道——他一定会带我去那个地方。"}]},{"num":39,"title":"第39章 本子","file":"chapters/ch039.mp3","dur":932.1,"size_mb":14.2,"segs":[{"s":0,"e":10.67,"t":"时间：6 月 30 日（周一）— 7 月 2 日（周三）· 高考后"},{"s":11.04,"e":14,"t":"6 月 30 日"},{"s":14.37,"e":20.6,"t":"查录取的那天，我在电脑前坐了一个上午。"},{"s":20.97,"e":41.12,"t":"屏幕上的网页刷新了一遍又一遍，每一次都显示\"系统繁忙\"。我一边刷新一边想——如果没录上怎么办？如果因为一分之差滑档了怎么办？"},{"s":41.49,"e":44.16,"t":"然后页面出来了。"},{"s":44.53,"e":49.27,"t":"江城大学 · 计算机科学与技术"},{"s":49.65,"e":53.2,"t":"一本。第一志愿。"},{"s":53.57,"e":57.43,"t":"我盯着那行字看了大概 10 秒。"},{"s":57.8,"e":66.98,"t":"然后我站起来，走进客厅，倒了一杯水，喝完了，才拿出手机。"},{"s":67.35,"e":70.02,"t":"手指有点抖。"},{"s":70.39,"e":73.06,"t":"我拨了博文的号码。"},{"s":73.43,"e":76.1,"t":"响了两声就接了。"},{"s":76.47,"e":77.95,"t":"\"喂？\""},{"s":78.32,"e":81.29,"t":"——他的声音有点紧。"},{"s":81.66,"e":83.14,"t":"\"查了吗？\""},{"s":83.51,"e":85.29,"t":"\"查了。\""},{"s":85.66,"e":86.84,"t":"\"怎么样？\""},{"s":87.21,"e":90.47,"t":"\"江城大学。计科。\""},{"s":90.84,"e":94.1,"t":"电话那头安静了一秒。"},{"s":94.47,"e":98.62,"t":"然后他说：\"我也查了。\""},{"s":98.99,"e":100.48,"t":"\"怎么样？\""},{"s":100.85,"e":104.4,"t":"\"江城大学。物理系。\""},{"s":104.77,"e":126.11,"t":"我握着手机，站在客厅中央。窗外是七月的阳光，蝉声一阵一阵的，不知道哪一栋楼有人在装修，电钻的声音从远处传过来。"},{"s":126.48,"e":127.97,"t":"很吵。"},{"s":128.34,"e":131.89,"t":"但我什么声音都听不到了。"},{"s":132.26,"e":135.82,"t":"\"我们……同一所？\""},{"s":136.19,"e":137.67,"t":"\"同一所。\""},{"s":138.04,"e":143.08,"t":"他顿了顿，又说：\"同一个校区。\""},{"s":143.45,"e":145.53,"t":"7 月 1 日"},{"s":145.9,"e":147.97,"t":"EMS 到了。"},{"s":148.34,"e":161.09,"t":"牛皮纸信封，盖着江城大学的红色印章。拿在手里不重，但我的手指把它捏出了一个角。"},{"s":161.46,"e":168.87,"t":"我翻了翻手机——博文在微信上发了一条消息："},{"s":169.24,"e":171.31,"t":"> 到了？"},{"s":171.68,"e":173.17,"t":"> 到了。"},{"s":173.54,"e":176.2,"t":"> 明天下午，老地方。"},{"s":176.57,"e":181.61,"t":"\"老地方\"——我知道他指的是哪里。"},{"s":181.98,"e":184.35,"t":"7 月 2 日"},{"s":184.73,"e":186.8,"t":"下午三点。"},{"s":187.17,"e":207.03,"t":"我走到教学楼下的时候，博文已经站在那里了。他靠在楼门口旁边的墙上，手里拎着一个纸袋，穿着一件白 T 恤——不是校服。"},{"s":207.4,"e":213.62,"t":"七月的阳光把他的影子缩成脚底下一个点。"},{"s":213.99,"e":219.63,"t":"他看见我来了，没说话，转身往楼里走。"},{"s":220,"e":221.48,"t":"我跟上去。"},{"s":221.85,"e":252.97,"t":"楼道里很安静。放暑假已经快一个月了，教学楼里空荡荡的，只有走廊尽头的风扇还在不知疲倦地转着。墙上那些高考倒计时的贴纸还没撕——\"距高考还有 0 天\"，有人用马克笔在下面画了一个笑脸。"},{"s":253.34,"e":256.01,"t":"他没停下来。"},{"s":256.38,"e":259.93,"t":"一直往上走，走到四楼。"},{"s":260.3,"e":263.27,"t":"然后他左转了。"},{"s":263.64,"e":266.01,"t":"我停下脚步。"},{"s":266.38,"e":270.53,"t":"四楼——我知道这里是哪里。"},{"s":270.9,"e":273.27,"t":"611 班。"},{"s":273.64,"e":277.5,"t":"他停在了 611 班门口。"},{"s":277.87,"e":281.13,"t":"然后他转过身来看着我。"},{"s":281.5,"e":284.16,"t":"\"你知道这是哪里吧？\""},{"s":284.53,"e":286.31,"t":"我喉咙发紧。"},{"s":286.68,"e":288.46,"t":"\"知道。\""},{"s":288.83,"e":295.65,"t":"611 班。我的高一教室。"},{"s":296.02,"e":312.03,"t":"那扇窗户——我靠窗坐了一年半的窗户。每天早自习我站在那里，透过玻璃看对面 610 班的最后一排。"},{"s":312.4,"e":314.77,"t":"看他的那扇窗。"},{"s":315.14,"e":328.47,"t":"博文站在 611 班门口，没进去。他伸手推了一下那扇窗户——咯吱一声，窗户往外开了。"},{"s":328.85,"e":333.29,"t":"然后他转过头看向走廊外面。"},{"s":333.66,"e":348.48,"t":"我顺着他的目光看过去——从这个角度，刚好看见对面的 610 班教室。最后一排，他的老位置。"},{"s":348.85,"e":353,"t":"5 米。隔着天井。"},{"s":353.37,"e":358.41,"t":"原来从这个角度看过去，是这样的。"},{"s":358.78,"e":364.12,"t":"\"我以前一直想问你一个问题。\"他说。"},{"s":364.49,"e":365.97,"t":"\"什么？\""},{"s":366.34,"e":371.38,"t":"\"你站在这里的时候——你在看什么？\""},{"s":371.75,"e":376.49,"t":"我看着对面那扇空荡荡的窗户。"},{"s":376.86,"e":394.94,"t":"\"看你。你坐在最后一排，低头写字。偶尔抬头往这边看一眼。有时候用红笔在纸上划一道。你摸后脑勺的时候我会笑。\""},{"s":395.31,"e":396.79,"t":"我停了一下。"},{"s":397.16,"e":401.02,"t":"\"我站在这里看了你一年半。\""},{"s":401.39,"e":405.24,"t":"他听完这句话，没回答。"},{"s":405.61,"e":409.76,"t":"他从纸袋里拿出了一样东西。"},{"s":410.13,"e":412.21,"t":"一个本子。"},{"s":412.58,"e":422.06,"t":"封面是深蓝色的，上面有小小的树图案——我见过这个本子。"},{"s":422.43,"e":436.95,"t":"去年 10 月。每天下午 4 点半，他都会拿出这个本子，写 1 分钟。我坐在他右边，从来没有看到内容。"},{"s":437.32,"e":439.4,"t":"他把本子递给我。"},{"s":439.77,"e":444.81,"t":"我接过来的时候，手指是凉的。"},{"s":445.18,"e":447.25,"t":"翻开第一页——"},{"s":447.62,"e":464.81,"t":"字迹很整齐，不像他平时写草稿那种飞起来的样子。蓝黑色的墨水，一行一行，日期写在每一条的左上角。"},{"s":465.18,"e":467.56,"t":"第一行写着："},{"s":467.93,"e":471.78,"t":"2024/12/7"},{"s":472.15,"e":484.01,"t":"\"今天 611 班那个站在走廊上的人——他今天看了我很久。他的眼睛里有光。\""},{"s":484.38,"e":488.82,"t":"我的手指停在了那一行字上。"},{"s":489.19,"e":493.05,"t":"2024 年 12 月 7 日。"},{"s":493.42,"e":495.19,"t":"高一上。"},{"s":495.56,"e":514.83,"t":"那是开学大概三个月后。我每天站在走廊上，以为自己是一个人在看。我以为那扇 5 米外的窗户后面的人永远不会知道我的存在。"},{"s":515.2,"e":516.98,"t":"但他知道。"},{"s":517.35,"e":521.5,"t":"他不仅知道——他记下来了。"},{"s":521.87,"e":523.65,"t":"我往下翻。"},{"s":524.02,"e":525.8,"t":"第二页。"},{"s":526.17,"e":530.32,"t":"2024/12/14"},{"s":530.69,"e":541.06,"t":"\"今天他又在走廊上。我发现我抬头的时候会找他。这个习惯不太好。\""},{"s":541.43,"e":543.21,"t":"第三页。"},{"s":543.58,"e":547.73,"t":"2024/12/20"},{"s":548.1,"e":556.99,"t":"\"他今天没来走廊。我抬头看了三次——他没在。是不是生病了？\""},{"s":557.36,"e":559.14,"t":"第四页。"},{"s":559.51,"e":563.66,"t":"2025/1/8"},{"s":564.03,"e":571.44,"t":"\"期末了。不知道下学期还能不能在学校里看见他。\""},{"s":571.81,"e":574.18,"t":"我的手有点抖。"},{"s":574.55,"e":591.15,"t":"我看见了那个时间跨度——从高一上的 12 月，一直到高一下的 2 月。每次记录都只有一两行，有时候只有半行。"},{"s":591.52,"e":596.26,"t":"2025/2/13"},{"s":596.63,"e":601.67,"t":"\"他进 610 班了。原来他叫林深。\""},{"s":602.04,"e":610.05,"t":"下面有一行，字迹比前面稍微潦草一点，像是补写的："},{"s":610.42,"e":615.16,"t":"\"他坐在我后面。80 厘米。\""},{"s":615.53,"e":619.97,"t":"我看到这里，眼泪突然就下来了。"},{"s":620.35,"e":636.65,"t":"不是那种\"感动的眼泪\"——是那种你发现你一直以为是一个人的事情，其实是两个人一起经历的那种眼泪。"},{"s":637.02,"e":641.46,"t":"我一直以为暗恋是我一个人的事。"},{"s":641.83,"e":646.87,"t":"但这本子告诉我——不是。"},{"s":647.24,"e":648.72,"t":"\"你——\""},{"s":649.1,"e":652.65,"t":"我说不出话来了。"},{"s":653.02,"e":657.17,"t":"博文站在我旁边，没看我。"},{"s":657.54,"e":662.58,"t":"他看着对面的 610 班窗户。"},{"s":662.95,"e":675.7,"t":"\"我高一上第一次抬头的时候——你在走廊上看我。我心里有了一种说不出来的满。\""},{"s":676.07,"e":677.55,"t":"他顿了顿。"},{"s":677.92,"e":683.25,"t":"\"那时候我就知道……完了。\""},{"s":683.62,"e":685.7,"t":"\"什么叫完了？\""},{"s":686.07,"e":690.81,"t":"\"就是——你再也不能不看他的意思。\""},{"s":691.18,"e":697.41,"t":"我们站在 611 班的窗户前站了很久。"},{"s":697.78,"e":717.34,"t":"七月的风从窗外吹进来，带着操场上被晒过的塑胶跑道的气味。对面 610 班的窗帘被风吹得鼓起来，飘了一下，又落回去。"},{"s":717.71,"e":720.67,"t":"我低头看那个本子。"},{"s":721.04,"e":726.08,"t":"翻到最后一页，有记录的那一页。"},{"s":726.45,"e":730.31,"t":"2025/7/2"},{"s":730.68,"e":738.38,"t":"\"我告诉他了。所有的事。他哭了。"},{"s":738.75,"e":746.76,"t":"他的眼睛里有光——和那天第一次看到的时候一样。\""},{"s":747.13,"e":754.24,"t":"\"我第一次看到你的时候——你知道我看到了什么吗？\""},{"s":754.61,"e":759.95,"t":"博文的声音从旁边传来。很轻。"},{"s":760.32,"e":776.32,"t":"\"你眼睛里的光——是像早上第一节课前、太阳刚升起来、照到对面教学楼的白墙再反射过来的那种光。\""},{"s":776.69,"e":778.77,"t":"我转过头看他。"},{"s":779.14,"e":789.81,"t":"他没在看我——但他笑了。眼睛底下那一块皱了一下——1 厘米的皱。"},{"s":790.18,"e":792.25,"t":"\"我说完了。\""},{"s":792.62,"e":794.4,"t":"他说。"},{"s":794.77,"e":801,"t":"我低下头，把本子合上，封面朝上。"},{"s":801.37,"e":810.85,"t":"深蓝色的封面上，那棵小树的轮廓在下午的阳光里特别清楚。"},{"s":811.22,"e":813.89,"t":"\"这个本子——\""},{"s":814.26,"e":816.04,"t":"\"送你了。\""},{"s":816.41,"e":818.48,"t":"\"……你不是还在写吗？\""},{"s":818.85,"e":821.22,"t":"\"以后换新的。\""},{"s":821.59,"e":823.97,"t":"他转过头来看我。"},{"s":824.34,"e":827.3,"t":"\"你要不要跟我去一个地方？\""},{"s":827.67,"e":830.04,"t":"我们走在楼梯上。"},{"s":830.41,"e":840.19,"t":"七月的阳光从天窗照下来，把楼梯间的灰尘照成一条一条的金线。"},{"s":840.56,"e":846.79,"t":"我捏着那个本子的封面，手指还是凉的。"},{"s":847.16,"e":852.49,"t":"\"最后一页那行字——你什么时候写的？\""},{"s":852.86,"e":854.94,"t":"\"今天早上。\""},{"s":855.31,"e":857.98,"t":"\"……你早知道我会哭？\""},{"s":858.35,"e":859.53,"t":"\"不知道。\""},{"s":859.9,"e":861.38,"t":"他顿了顿。"},{"s":861.76,"e":863.53,"t":"\"但我带纸了。\""},{"s":863.9,"e":869.24,"t":"他伸手从口袋里掏出一包纸巾，递给我。"},{"s":869.61,"e":871.39,"t":"我接过来。"},{"s":871.76,"e":883.02,"t":"撕开包装的时候，我看到他在笑——嘴角往上，眼睛底下皱了一下。"},{"s":883.39,"e":887.84,"t":"七月的风从窗外吹进来。"},{"s":888.21,"e":896.51,"t":"我把我高一上站在走廊上看了他一年半这件事，告诉了他。"},{"s":896.88,"e":903.69,"t":"他把高一上就开始记录我的本子，交给了我。"},{"s":904.07,"e":908.81,"t":"我们站在楼梯口，谁都没说话。"},{"s":909.18,"e":912.14,"t":"但不是因为没话说。"},{"s":912.51,"e":919.33,"t":"是因为话说完了之后，好像什么都不用再说了。"},{"s":919.7,"e":921.48,"t":"\"带路吧。\""},{"s":921.85,"e":923.92,"t":"我说。"},{"s":924.29,"e":926.07,"t":"他点了点头。"},{"s":926.44,"e":932.07,"t":"然后往六楼的方向走——天台。"}]},{"num":40,"title":"第40章 你没会错意","file":"chapters/ch040.mp3","dur":995.2,"size_mb":15.2,"segs":[{"s":0,"e":10.15,"t":"时间：7 月 16 日（周三）· 高考后的夏天"},{"s":10.55,"e":12.77,"t":"7 月 16 日"},{"s":13.16,"e":17.92,"t":"我跟在博文后面，走上六楼。"},{"s":18.32,"e":52.26,"t":"楼梯间的阳光从天窗斜斜地照下来，把我的影子叠在他的影子上。我手里还捏着那个深蓝色的本子——封面上小树的轮廓在光里特别清楚。从 7 月 2 号那天他把它交给我开始，我走到哪里都带着它。"},{"s":52.66,"e":56.46,"t":"他在天台门口停了一下。"},{"s":56.86,"e":84.14,"t":"那扇铁门——两年前他带我来过一次。那天下午的阳光把整片天台染成橘色的，他站在门前面，回过头来看我，说了一句我到现在都记得的话。"},{"s":84.53,"e":88.66,"t":"\"我高一上就想离你近一点。\""},{"s":89.05,"e":91.91,"t":"那是两年前的事了。"},{"s":92.31,"e":103.72,"t":"他伸手推开门——铁门发出吱的一声。和两年前一模一样。"},{"s":104.12,"e":107.61,"t":"然后他走了出去。"},{"s":108.01,"e":109.59,"t":"我跟上去。"},{"s":109.99,"e":141.39,"t":"天台还是那个天台。水泥地面，边上生锈的围栏，远处的城市天际线在七月的热气里微微扭曲。围栏上还留着不知道谁刻的字——\"2025 高考加油\"，笔画已经被晒褪色了。"},{"s":141.79,"e":150.04,"t":"不一样的是这一次我不再是\"跟他上来看看\"的那个人了。"},{"s":150.43,"e":155.19,"t":"博文走到围栏边上，没转过来。"},{"s":155.59,"e":177.16,"t":"七月的风从城市那边吹过来，带着柏油路面晒过的气味和他衣服上那股熟悉的洗衣液味道——不是柚子味的，换了，但我也闻了两年了。"},{"s":177.55,"e":182.95,"t":"\"你知道这个天台对我来说是什么吗？\""},{"s":183.34,"e":187.15,"t":"他开口了，声音不大。"},{"s":187.55,"e":192.62,"t":"我走过去，靠在他旁边的围栏上。"},{"s":193.02,"e":194.92,"t":"\"什么？\""},{"s":195.32,"e":197.54,"t":"他沉默了一会儿。"},{"s":197.93,"e":203.33,"t":"\"高二那天——我在这里说了一句话。\""},{"s":203.72,"e":205.31,"t":"\"哪句？\""},{"s":205.71,"e":208.24,"t":"\"'我想和你在一起'。\""},{"s":208.64,"e":218.79,"t":"他说这句话的时候语气很平，像在读一条早就确定的定理。"},{"s":219.19,"e":228.07,"t":"\"我说完那句话之后，这个天台就不再是普通的天台了。\""},{"s":228.46,"e":251.3,"t":"他转过头来看我。阳光落在他侧脸上，把他眼底的光照得发亮——那种像早上第一节课前、太阳照到对面教学楼白墙再反射过来的光。"},{"s":251.7,"e":258.04,"t":"\"从那之后——我来天台就不用一个人了。\""},{"s":258.44,"e":267.32,"t":"风忽然大了一些，把他的头发吹乱了一点。他没伸手去理。"},{"s":267.72,"e":269.94,"t":"我也没说话。"},{"s":270.34,"e":277.31,"t":"不是因为没话说。是因为有些话不需要说。"},{"s":277.71,"e":297.06,"t":"过了好一会儿，他从口袋里掏出一个东西——一个本子。新的，封面是纯黑色的，连价格标签都没撕干净，露出一截白色的边。"},{"s":297.46,"e":300.31,"t":"\"我昨天晚上写的。\""},{"s":300.71,"e":302.29,"t":"他递过来。"},{"s":302.69,"e":316.01,"t":"我接住的时候，手指碰到他的手指——暖的。和两年前借笔记那次一样暖。"},{"s":316.41,"e":318.95,"t":"我翻开第一页。"},{"s":319.34,"e":332.98,"t":"字迹很整齐，和他那个深蓝色本子里的字一样。蓝黑色的墨水，在纸面上微微反光。"},{"s":333.38,"e":338.14,"t":"2026/7/15"},{"s":338.53,"e":343.29,"t":"\"明天我要跟他说：你没会错意。"},{"s":343.69,"e":349.4,"t":"从高一开始就没有。以后也不会。\""},{"s":349.79,"e":357.09,"t":"我看着那行字，喉咙动了一下，没说出来。"},{"s":357.49,"e":371.13,"t":"他伸手把我的手指按在那一页上——他的拇指按在我的手背上，用力了一下，然后松开了。"},{"s":371.52,"e":374.06,"t":"\"那个本子送你了。\""},{"s":374.46,"e":376.36,"t":"他说。"},{"s":376.76,"e":380.25,"t":"\"这是新的。第一页给你看。\""},{"s":380.64,"e":399.04,"t":"我低头看着那行字。他把\"你没会错意\"单独写在一行——字比其他行稍微用力一点，笔画比旁边的字深一些。"},{"s":399.44,"e":400.39,"t":"\"你——\""},{"s":400.78,"e":403.96,"t":"话卡在喉咙里。"},{"s":404.35,"e":414.5,"t":"他没催我。他只是转过去，重新看向远处的城市天际线。"},{"s":414.9,"e":420.93,"t":"夏天的风从我们两个人之间穿过去。"},{"s":421.32,"e":440.99,"t":"我忽然想起高一上那个站在走廊上的自己——趴在窗台上，透过 5 米宽的空气，看着对面那个永远不知道我在看他的人。"},{"s":441.39,"e":449,"t":"那时候我想：我这辈子大概只能这样看他了。"},{"s":449.4,"e":457.01,"t":"但现在我站在天台边上，手里握着他昨天写的字。"},{"s":457.4,"e":462.16,"t":"上面写着：你没会错意。"},{"s":462.56,"e":465.73,"t":"从高一开始就没有。"},{"s":466.13,"e":468.35,"t":"以后也不会。"},{"s":468.74,"e":470.97,"t":"——\"以后\"。"},{"s":471.36,"e":478.66,"t":"这个词从高一到现在，我从来没敢认真想过。"},{"s":479.05,"e":480.64,"t":"\"博文。\""},{"s":481.04,"e":482.94,"t":"\"嗯？\""},{"s":483.34,"e":487.14,"t":"\"你为什么选江城大学？\""},{"s":487.54,"e":491.03,"t":"他转过头来看了我一眼。"},{"s":491.42,"e":497.45,"t":"\"物理系只有江大在省内收分最合适。\""},{"s":497.85,"e":500.7,"t":"\"……就这样？\""},{"s":501.1,"e":503.32,"t":"他沉默了一会儿。"},{"s":503.72,"e":511.01,"t":"\"也有一部分——\"他顿了一下，\"是因为你。\""},{"s":511.41,"e":515.21,"t":"\"……什么叫'也有一部分'？\""},{"s":515.61,"e":522.59,"t":"他的目光落在远处的天际线上，不看我。"},{"s":522.99,"e":537.26,"t":"\"就是——\"他的声音比刚才小了一点，\"你在那里。所以我填志愿的时候没有犹豫过。\""},{"s":537.66,"e":555.42,"t":"夏天午后的风从远处吹过来，带着热浪。不知道哪栋楼的空调外机在嗡嗡地转，声音很远很模糊。"},{"s":555.82,"e":573.58,"t":"我把那个纯黑色的本子合上，两只手各握着一个本子——深蓝的，从高一开始写的；纯黑的，从昨天开始写的。"},{"s":573.98,"e":577.47,"t":"\"那你——接下来写什么？\""},{"s":577.86,"e":579.45,"t":"他想了想。"},{"s":579.84,"e":584.6,"t":"\"写江城大学秋天有没有银杏。\""},{"s":585,"e":586.27,"t":"\"还有呢？\""},{"s":586.66,"e":592.06,"t":"\"写大一第一节课你会坐第几排。\""},{"s":592.45,"e":594.04,"t":"\"还有呢？\""},{"s":594.44,"e":596.97,"t":"他转过头来看我。"},{"s":597.37,"e":611.64,"t":"那个眼神——我说不上来。不是回答，是那种\"你真的要我说完吗\"的眼神。"},{"s":612.04,"e":615.53,"t":"我看着他，没躲开。"},{"s":615.93,"e":623.54,"t":"他嘴角动了一下——然后眼睛底下那一块皱了一下。"},{"s":623.94,"e":626.16,"t":"1 厘米的皱。"},{"s":626.55,"e":631.63,"t":"\"写你不用再问'还有呢'的那天。\""},{"s":632.02,"e":633.93,"t":"他说。"},{"s":634.32,"e":637.18,"t":"心脏猛地跳了一下。"},{"s":637.58,"e":639.8,"t":"\"哪天是那天？\""},{"s":640.19,"e":642.1,"t":"他没马上回答。"},{"s":642.49,"e":658.99,"t":"过了一会儿，他伸手拿走我手里的纯黑色本子，翻到刚才那一页，在\"以后也不会\"下面又写了一行字。"},{"s":659.38,"e":665.09,"t":"他写的时候没挡着——我看见了。"},{"s":665.49,"e":673.1,"t":"他的字写得比上一行轻一些，像是写给自己看的："},{"s":673.5,"e":676.35,"t":"\"写到不用写的那天。\""},{"s":676.75,"e":680.56,"t":"他把本子合上，递回给我。"},{"s":680.95,"e":685.71,"t":"\"哪一天是'不用写的那天'？\""},{"s":686.11,"e":693.09,"t":"他把目光从我脸上移开，看向远处的城市。"},{"s":693.48,"e":698.87,"t":"\"等我不用靠写来确认你还在的那天。\""},{"s":699.27,"e":702.76,"t":"风忽然安静了一瞬。"},{"s":703.16,"e":721.87,"t":"远处工地打桩的声音停了几秒，不知道是午休还是换料。操场上空荡荡的，暑假的学校像另一个星球。"},{"s":722.27,"e":729.56,"t":"我站在他旁边，肩膀之间隔了一个拳头的距离。"},{"s":729.96,"e":732.5,"t":"比 80 厘米近。"},{"s":732.89,"e":741.14,"t":"比 5 米——比那扇反光玻璃——近太多了。"},{"s":741.54,"e":743.44,"t":"\"那要很久。\""},{"s":743.84,"e":745.42,"t":"我说。"},{"s":745.82,"e":748.04,"t":"\"我知道。\""},{"s":748.44,"e":750.66,"t":"\"你会写很多本。\""},{"s":751.05,"e":752.64,"t":"\"嗯。\""},{"s":753.04,"e":756.21,"t":"\"你书房装得下吗？\""},{"s":756.61,"e":758.51,"t":"他转过来看我。"},{"s":758.9,"e":773.18,"t":"那个表情——不是笑，是那种\"你终于不紧张了\"的表情。嘴角往上翘了大概半厘米。"},{"s":773.58,"e":776.75,"t":"\"装不下就放你那边。\""},{"s":777.14,"e":779.36,"t":"他说。"},{"s":779.76,"e":784.2,"t":"我低下头，笑了一下。"},{"s":784.6,"e":809.97,"t":"远处的天际线上，云在慢慢地移动。七月的天空从蓝色开始往橘色过渡——不是两年前那种鲜艳的橘色，是更淡的、被夏天的热气稀释过的橘色。"},{"s":810.37,"e":815.45,"t":"不是同一个下午，但颜色是一样的。"},{"s":815.84,"e":828.21,"t":"我忽然觉得，两年前站在这里的我和现在站在这里的我，不是同一个人。"},{"s":828.61,"e":842.88,"t":"两年前我站在这里，听到他说\"我喜欢你\"，心里想的是：这是真的吗？他会不会后悔？"},{"s":843.28,"e":849.94,"t":"现在我还是站在这里，手里多了两个本子。"},{"s":850.34,"e":863.34,"t":"一个高二上他被我发现的本子——记录了他从高一上就开始的、三年半的注视。"},{"s":863.74,"e":878.33,"t":"一个昨天晚上才买的、第一页就写着\"你没会错意\"——从高一开始就没有，以后也不会。"},{"s":878.73,"e":884.44,"t":"我低下头，把两个本子并排拿在手里。"},{"s":884.83,"e":887.05,"t":"\"博文。\""},{"s":887.45,"e":888.72,"t":"\"嗯？\""},{"s":889.12,"e":900.54,"t":"\"我高一上站在走廊上的时候——从来没想过能走到今天这一步。\""},{"s":900.93,"e":902.52,"t":"他没回答。"},{"s":902.91,"e":915.92,"t":"但他把手从围栏上拿下来——搭在围栏上的那只手——然后往我这边挪了一点。"},{"s":916.32,"e":918.54,"t":"不到 5 厘米。"},{"s":918.93,"e":920.84,"t":"但够了。"},{"s":921.23,"e":932.33,"t":"他的手臂外侧贴着我的手臂外侧。皮肤碰到皮肤的那一下，两个人都没动。"},{"s":932.73,"e":937.49,"t":"夏天的风从城市那边吹过来。"},{"s":937.89,"e":943.91,"t":"远处的天际线在热气里微微起伏。"},{"s":944.31,"e":948.75,"t":"我没看他，他也没看我。"},{"s":949.15,"e":951.68,"t":"我们就那么站着。"},{"s":952.08,"e":962.87,"t":"两个本子叠在一起，一个从过去写到今天，一个从今天开始写。"},{"s":963.26,"e":969.61,"t":"他的手搭在围栏上，离我的手大概 2 厘米。"},{"s":970,"e":972.86,"t":"我没再往那边挪。"},{"s":973.25,"e":975.79,"t":"不是因为不敢。"},{"s":976.19,"e":995.22,"t":"是因为我知道——明天、后天、大学四年、以后——还有很长很长的时间可以慢慢挪。"}]}];
